(window.GIM_TS=window.GIM_TS||{})["Rosh Hashanah.1"]={"from":24,"a":[["ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמר שמואל את שלוש ההלכות הללו, ואינן נלמדות זו מזו. \u0003דאי אשמעינן\u0004 \u0005[שאילו היה משמיע לנו]\u0006 רק כי \u0003הלכה כר' שמעון שזורי, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהוא אומר כן \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 \u0003יש בילה\u0004 \u0005[בלילה],\u0006 \u0003שדברים המעורבים נחשבים כבלולים לגמרי, על כן קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מאמר שני: \u0003לכל אין בילה.\u0004","ועוד: \u0003ואי אשמעינן\u0004 \u0005[ואילו היה משמיע לנו]\u0006 \u0003לכל אין בילה\u0004 — \u0003הוה אמינא כרבנן סבירא ליה\u0004 \u0005[הייתי אומר\u0006 ש\u0005כחכמים הוא סבור]\u0006 לענין מעשרות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003הלכה כר' שמעון שזורי.\u0004","\u0003ואי אשמעינן הני תרתי\u0004 \u0005[ואילו היה משמיע לנו\u0006 את \u0005אלה השתים]\u0006 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כפי שהקשה ר' זירא \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003שמואל\u0004 על דברי \u0003שמואל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]:\u0006 \u0003הכל הולך אחר גמר פרי.\u0004","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק דבר זה ש\u0003הכל הולך אחר גמר פרי, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אפילו תבואה וזיתים נמי\u0004 \u0005[גם כן]\u0006 הולכים בהם אחר גמר הפרי — \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003הלכה כר' שמעון שזורי במאי דפליג\u0004 \u0005[במה שחלק]\u0006 בשאר מינים, אבל לא בתבואה וזיתים.","ושואלים: \u0003ולשמעינן הני תרתי\u0004 \u0005[ושישמיע לנו\u0006 רק \u0005את שתי אלה],\u0006 שהלכה כר' שמעון שזורי ושהכל הולך אחר גמר פרי, ובכך היינו למדים את כל שיטתו של שמואל, \u0003לכל אין בילה למה לי?\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 לא החידוש שבצד השלילי שלכל אין בילה, אלא ש\u0003ליין ושמן יש בילה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר:\u0004 נאמר, \u0003\"באספך מגרנך ומיקבך\"\u0004 (דברים טז, יג), ללמד, \u0003מה גורן ויקב מיוחדין שגדילין על מי שנה שעברה,\u0004 שהרי הם גידולי בעל היונקים מן הרטיבות שבקרקע, וגידולם ממי הגשמים של השנה שעברה, ודינם שהם \u0003מתעשרין לשנה שעברה, אף כל שגדילין על מי שנה שעברה\u0004 — \u0003מתעשרין\u0004 אף הם \u0003לשנה שעברה. יצאו ירקות שגדילין על מי שנה הבאה,\u0004 שהרי זמן גידולם קצר, והם גדלים ממי הגשמים היורדים עליהם במשך זמן גידולם, ולכן \u0003מתעשרין\u0004 הם \u0003לשנה הבאה.\u0004","\u0003ר' עקיבא אומר:\u0004 דבר זה נלמד באופן אחר, ומה שנאמר \u0003\"באספך מגרנך ומיקבך\"\u0004 יש לדרוש באופן זה: \u0003מה גורן ויקב מיוחדין שגדילין על רוב מים,\u0004 שגידולם ממי הגשמים, שהם רוב המים המצויים, ודינם שהם \u0003מתעשרין לשנה שעברה, אף כל שגדילין על רוב מים מתעשרין\u0004 כמותם \u0003לשנה שעברה. יצאו ירקות שגדילין על כל מים\u0004 שגידולם לא רק על מי גשמים אלא גם בהשקיה ממי מעינות ונהרות, והם \u0003מתעשרין לשנה הבאה.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה, העשוי לנבוע מן ההסבר השונה בדברי הכתוב? \u0003אמר ר' אבהו: בצלים הסריסין ופול המצרי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בצלים הסריסין,\u0004 כלומר, בצלים שממעכים את הזרעים באחד משלבי הצמיחה, כדי שלא יגדלו הפקעות והזרעים אלא יצמיחו ירק ופקעות קטנות בלבד, \u0003ו\u0004כן \u0003פול המצרי\u0004 שזרעו לצורך ירק, אם \u0003מנע מהן מים שלשים יום לפני ראש השנה\u0004 של שנת השביעית, ועל ידי כך הם מפסיקים לגדל ירק ומתחילים לגדל זרעים — הרי הם \u0003מתעשרין לשעבר ומותרין בשביעית, ואם לאו\u0004 — \u0003אסורין בשביעית ומתעשרין לשנה הבאה.\u0004 ואם כן הדבר תלוי לא במין הצמחים אלא במצבם בפועל, אם אכן הם שותים ממי שנה שעברה או ממי שנה זו, והוא כשיטת ר' יוסי הגלילי.","שנינו במשנה: \u0003באחד בשבט ראש השנה לאילן,\u0004 כדברי בית שמאי. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 קבעו כראש שנת האילנות את התאריך הזה? \u0003אמר ר' אלעזר אמר ר' אושעיא: הואיל ויצאו\u0004 (ונגמרו) כבר \u0003רוב גשמי\u0004 ה\u0003שנה, ועדיין רוב תקופה מבחוץ\u0004 שרוב תקופת טבת הוא לאחר מכן. שנמשכת עד יום שוויון היום והלילה האביבי, בערך בניסן.","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 כלומר, הלא אין זה נימוק אלא טענה לפתור! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אף על פי שרוב תקופה מבחוץ,\u0004 שעדיין נמשכת תקופת טבת, מכל מקום \u0003הואיל ויצאו רוב גשמי שנה\u0004 הרי אנו רואים זאת כסיומה של שנת הגשמים הזו, וכל הגדל מכאן והלאה נחשב כשל השנה הבאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003מעשה בר' עקיבא שליקט\u0004 פירות \u0003אתרוג\u0004 מן האילן \u0003באחד בשבט ונהג בו שני\u0004 סוגי \u0003עישורין\u0004 \u0005[מעשרות].\u0006 שאותה שנה היתה שנה שניה (או חמישית) לשנות השמיטה, ובשנה שניה מפרישים מעשר שני ואילו בשלישית מעשר עני, והוא הפריש את שניהם מחמת הספק."],["ומדוע נהג בו כך? \u0003אחד\u0004 מחמת הספק אם באחד בשבט כבר נתחדשה שנת האילן כדברי בית שמאי, ואחד מחמת הספק שמא אינה שאינה מתחדשת אלא בחמישה עשר בשבט \u0003כדברי בית הלל.\u0004","\u0003ר' יוסי בר יהודה אומר: לא מנהג בית שמאי ובית הלל נהג בה,\u0004 כלומר, לא מחמת ספק זה עשה כן, \u0003אלא מנהג רבן גמליאל ור' אליעזר נהג בה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אתרוג שוה לאילן בשלשה דרכים, ולירק\u0004 הוא שוה \u0003בדרך אחד.\u0004 כיצד? \u0003שוה לאילן בשלשה דרכים: לערלה\u0004 שבשלוש השנים הראשונות, פירותיו אסורים באכילה כאילן, \u0003ול\u0004ענין נטע \u0003רבעי,\u0004 שכדין האילן, אף פירותיו בשנה הרביעית צריכים פדיון, \u0003ול\u0004ענין \u0003שביעית\u0004 לגבי קביעת שנת השמיטה. ובכל שלושת הדינים הללו הזמן הקובע הוא תאריך חנטת האתרוג, כדין פירות האילן. ושווה האתרוג \u0003לירק בדרך אחד\u0004 — \u0003שבשעת לקיטתו עישורו\u0004 שלענין שנות המעשר, אנו הולכים לא אחר חנטת הפרי אלא לאחר לקיטתו, אלו \u0003דברי רבן גמליאל.\u0004","\u0003ר' אליעזר אומר: אתרוג שוה לאילן לכל דבר.\u0004","לפני שבאים לדון בפרטים תוהים על עיקרו של המעשה: \u0003ומי עבדינן כתרי חומרי\u0004 \u0005[והאם עושים,\u0006 נוהגים \u0005אנו כשתי חומרות]\u0006 הסותרות זו את זו? \u0003והתניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לעולם הלכה כדברי בית הלל, ו\u0004אולם \u0003הרוצה לעשות כדברי בית שמאי\u0004 — \u0003עושה,\u0004 ואם רוצה לעשות \u0003כדברי בית הלל\u0004 — \u0003עושה.\u0004 אולם, אם הוא עושה \u0003מקולי בית שמאי ומקולי בית הלל\u0004 יחד — הרי זה \u0003רשע,\u0004 ואם הוא עושה \u0003מחומרי בית שמאי ומחומרי בית הלל\u0004 — \u0003עליו הכתוב אומר \"והכסיל בחשך הולך\"\u0004 (קהלת ב, יד). \u0003אלא\u0004 ינהג \u0003אי\u0004 \u0005[או]\u0006 \u0003כבית שמאי בקוליהון ובחומריהון\u0004 \u0005[בקולותיהם ובחומרותיהם],\u0006 או \u0003כבית הלל בקוליהון ובחומריהון\u0004 \u0005[בקולותיהם ובחומרותיהם].\u0006 ואם כן, כיצד זה נהג ר' עקיבא כשתי החומרות?","ומשיבים: \u0003ר' עקיבא גמריה אסתפק ליה\u0004 \u0005[לימודו הסתפק לו]\u0006 \u0003ולא ידע\u0004 מה היא שיטת בית הלל, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בית הלל באחד בשבט אומר, אי\u0004 \u0005[אם]\u0006 \u0003בחמישה עשר בשבט אומר,\u0004 ומשום כך נהג כשתי השיטות, אבל בעצם רצה לנהוג כדעת בית הלל.","ומבררים עוד את הברייתא: \u0003ר' יוסי בר יהודה אומר: לא מנהג בית שמאי ובית הלל נהג בה אלא מנהג רבן גמליאל ור' אליעזר נהג בה.\u0004 ותוהים: אם כן, מאחר שעשה זאת \u0003באחד בשבט\u0004 משמע ש\u0003כבית שמאי נהג בה,\u0004 שהרי לדעת בית הלל אחד בשבט שייך בבירור לשנה שעברה, ואף אם חשש לדעת ר' אליעזר לא היה צריך להפריש מעשר נוסף!","\u0003אמר ר' חנינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנניא: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003באתרוג שחנטו פירותיו קודם חמישה עשר דאידך שבט עסקינן\u0004 \u0005[של שבט האחר\u0006 בשנה שעברה, \u0005עוסקים אנו]\u0006 ואם כן מצד זמן החנטה ברור שאותו אתרוג שייך לשנה השניה, אלא שחשש ר' עקיבא לדעת רבן גמליאל ההולך אחר הלקיטה, ולקיטה זו הרי היתה בשלישית. \u0003ובדין הוא אפילו קודם לכן\u0004 שבעצם לא היה ספק זה תלוי באחד בשבט דווקא וגם אם היה קוטפם זמן רב קודם לכן היה ספק זה קיים אלא \u0003מעשה שהיה כך היה\u0004 שנזדמן הדבר באחד בשבט.","\u0003רבינא אמר: כרוך ותני\u0004 \u0005[ושנה]\u0006 ותקן את הגירסה בנוסח זה: \u0003לא אחד בשבט היה אלא חמישה עשר בשבט היה, ולא מנהג בית שמאי ובית הלל נהג בה אלא מנהג רבן גמליאל ור' אליעזר נהג בה\u0004 ולפי שיטת בית הלל.","לעצם דין עישור האתרוג \u0003אמר רבה בר רב הונא: השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר רבן גמליאל\u0004 כי \u0003אתרוג אחר לקיטתו עישורו כירק,\u0004 יש לומר ש\u0003ראש השנה שלו\u0004 לגבי מנין שנות המעשר הוא \u0003תשרי\u0004 כמו שאר הירקות, וכפי ששנינו שאחד בתשרי הוא ראש השנה למעשר ירקות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב בר רב הונא מתוספתא, ששנינו בה: \u0003ר' שמעון בן אלעזר אומר: ליקט אתרוג ערב חמישה עשר בשבט עד שלא תבוא\u0004 (תשקע) \u0003השמש, וחזר וליקט\u0004 אתרוג אחר \u0003משתבוא השמש\u0004 ונתחדשה שנת אילן חדשה — \u0003אין תורמין ומעשרין מזה על זה, לפי\u0004 הכלל \u0003שאין תורמין ומעשרין לא מן החדש על הישן ולא מן הישן על החדש.\u0004 וכן אם \u0003היתה\u0004 זו שנה \u0003שלישית\u0004 ש\u0003נכנסת\u0004 לשנה \u0003הרביעית\u0004 בשנות השמיטה, הרי ממה ששייך ל\u0003שלישית\u0004 מפריש \u0003מעשר ראשון ומעשר עני,\u0004 וממה ששייך ל\u0003רביעית\u0004 מפריש \u0003מעשר ראשון ומעשר שני.\u0004"],["ומעתה נברר את השיטה: \u0003מאן שמעת ליה דאזיל בתר\u0004 \u0005[מי שמעת אותו ש\u0006הוא \u0005הולך\u0006 באתרוג \u0005אחר\u0006 זמן\u0005]\u0006 ה\u0003לקיטה,\u0004 הלא הוא \u0003רבן גמליאל, וקתני\u0004 \u0005[ו\u0006עם כל זה \u0005שנה]\u0006 ר' שמעון בן אלעזר שזמן ראש השנה לכך הוא ב\u0003שבט,\u0004 ושלא כדברי רבה בר רב הונא בשיטת רבן גמליאל!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו, ו\u0003אי אתמר הכי אתמר\u0004 \u0005[אם נאמר, כך נאמר]:\u0006 \u0003אמר רבה בר רב הונא: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר רבן גמליאל\u0004 כי הולכים ב\u0003אתרוג אחר\u0004 ה\u0003לקיטה כירק\u0004 — \u0003ראש השנה שלו\u0004 כאילן, ב\u0003שבט.\u0004","ושואלים: \u0003מאי שנא התם\u0004 \u0005[במה שונה שם]\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003\"אם היתה שניה נכנסת לשלישית\" ומאי שנא הכא\u0004 \u0005[ובמה שונה כאן]\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003\"אם היתה שלישית נכנסת לרביעית\"?\u0004 כלומר, מדוע לא הביא אותה דוגמה עצמה?","ומשיבים: \u0003מלתא אגב אורחיה קא משמע לן\u0004 \u0005[דבר בדרך אגב השמיע לנו]:\u0006 ש\u0003אתרוג קשיא ליה ידא\u0004 \u0005[קשה לו\u0006 משמוש \u0005היד]\u0006 \u0003ואיידי דממשמשי ביה כולי עלמא\u0004 \u0005[וכיון שממשמשים בו הכל] \u0006\u0003בשביעית,\u0004 שהרי בשנה זו כל הפרדסים הפקר והכל רשאים להכנס ולקטוף, וממשמשים באילן, ובשל כך \u0003לא טעין פרי עד תלת שנין\u0004 \u0005[אינו טוען פירות\u0006 הראויים לאכילה \u0005עד שלוש שנים].\u0006","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן מר' ינאי: אתרוג, ראש השנה שלו אימתי? אמר ליה\u0004 \u0005[לו]\u0006 ר' ינאי: \u0003שבט.\u0004 שאל אותו שוב ר' יוחנן: \u0003שבט\u0004 זה שאמרת האם הוא לחשבון ה\u0003חדשים\u0004 שהוא למנין הירח, כלומר, בחודש שבט כרגיל, \u0003או\u0004 שמא כוונתך לחודש \u0003שבט\u0004 הנמנה ל\u0003תקופה\u0004 של החמה, שהוא חל שלושים יום יום לאחר שנכנסה תקופת טבת, שהוא זמן שאינו קבוע בכל השנים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה הוא שבט למנין ה\u0003חדשים,\u0004 ואין משנים את הזמנים לפי התקופה גם אם היא מקדימה או מאחרת.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ששאל זאת \u0003ר' יוחנן מר' ינאי: היתה שנה מעוברת מהו\u0004 כיצד צריך לנהוג לענין ראש השנה לאילנות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר רוב שנים\u0004 ואף בשנה מעוברת ראש השנה לאילן הוא בשבט ואינו משתנה.","\u0003אמר רבה: אתרוג בת ששית,\u0004 כלומר, שגדל בשנה השישית לשמיטה \u0003שנכנסה לשביעית\u0004 ונקטף בשנה השביעית — \u0003פטורה מן המעשר\u0004 כדין פירות שמיטה, \u0003ופטורה מן הביעור\u0004 שאף שמבערים פירות שביעית שלא נאכלו, אין אתרוג זה בכללם. ואילו \u0003בת שביעית שנכנסה לשמינית\u0004 — \u0003פטורה במעשר וחייבת בביעור\u0004 כפרי של שביעית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בשלמא סיפא\u0004 \u0005[נניח בסוף],\u0006 בהלכה השניה, יש להסביר שחייבת בביעור \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 אולם \u0003רישא\u0004 שאמרת \u0003פטורה מן הביעור אמאי\u0004 \u0005[מדוע]\u0006 פטורה — \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 זמן ה\u0003חנטה\u0004 וזה היה בשנה קודמת, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003תיחייב במעשר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 איך אפשר לומר זאת, שהרי \u0003יד הכל ממשמשין בה,\u0004 שהרי הכל רשאים להכנס לפרדסים כדי ליטול את הפירות שהם הפקר בשנה זו ובתוך כדי כך הרי הם ממשמשים את כל הפירות שבהם, ואף אתרוג זה הוא בפועל הפקר \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003תיחייב במעשר?!\u0004 ואף שאינו פטור כפרי שביעית, הוא פטור מן המעשר משום שהוא הפקר.","ואילו \u0003רב המנונא אמר: בת ששית שנכנסת לשביעית, לעולם,\u0004 כלומר לכל ענין, נחשבת היא לשל השנה ה\u0003ששית, ובת שביעית הנכנסת לשמינית\u0004 — \u0003לעולם\u0004 נחשבת כשל \u0003שביעית.\u0004","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא, \u0003ר' שמעון בן יהודה אומר משום ר' שמעון: אתרוג בת ששית שנכנסת לשביעית\u0004 — \u0003פטורה מן המעשר\u0004 לפי ששנת השביעית היא, \u0003ופטורה מן הביעור\u0004 שלדעתו \u0003אין לך דבר שחייב במעשר אלא אם כן\u0004 גם \u0003גדל בחיוב\u0004 מעשרות וגם \u0003נלקט בחיוב.\u0004 וכן \u0003בת שביעית שנכנסת לשמינית\u0004 — \u0003פטורה מן המעשר ופטורה מן הביעור, שאין לך דבר שחייב בביעור אלא אם כן גדל בשביעית ונלקט בשביעית.\u0004","ומעירים: \u0003רישא\u0004 \u0005[\u0006החלק \u0005הראשון]\u0006 של ברייתא זו \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003לרב המנונא\u0004 האומר כי בת שישית שנכנסת לשביעית לעולם הוא של שישית, ולדבריו היה צריך להיות איפוא חייב במעשר, ואילו \u0003סיפא [\u0004החלק \u0005האחרון]\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003בין לרבה בין לרב המנונא,\u0004 שלדברי רבה בת שביעית שנכנסה לשמינית חייבת בביעור, ואף לדברי רב המנונא יש להחשיבה לגמרי כבת שביעית ולחייבה בביעור!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בכך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בבברייתא\u0005],\u0006 \u0003אמר ר' יוסי:\u0004 החכם \u0003אבטולמוס העיד משום חמשה זקנים: אתרוג\u0004 נדון \u0003אחר\u0004 זמן \u0003לקיטתו ל\u0004ענין \u0003מעשר, ו\u0004אילו \u0003רבותינו נמנו,\u0004 כלומר, דנו בדבר והגיעו למנין ולהצבעה \u0003באושא, ואמרו\u0004 שנוהגים ודנים בו \u0003אחר\u0004 זמן \u0003לקיטתו, בין למעשר בין לשביעית.\u0004","על הדברים האלה תוהים: \u0003שביעית מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמה],\u0006 שהרי במעשרות דנו, ומדוע הזכירו גם את ענין שביעית?"],["ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003אתרוג,\u0004 הולכים \u0003אחר\u0004 זמן \u0003לקיטתו ל\u0004ענין \u0003מעשר ואחר חנטה ל\u0004ענין \u0003שביעית. ורבותינו נמנו באושא\u0004 וגמרו: \u0003אחר לקיטתו בין למעשר בין לשביעית.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שדנו גם אמוראי ארץ ישראל בנושא זה: \u0003ר' יוחנן וריש לקיש אמרי תרוייהו\u0004 \u0005[אמרו שניהם]:\u0006 \u0003אתרוג בת ששית שנכנסה לשביעית\u0004 — \u0003לעולם\u0004 נחשבת כשייכת לשנה ה\u0003ששית. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אתרוג בת ששית שנכנסה לשביעית אפילו\u0004 היה הפרי גדול רק \u0003כזית ונעשית\u0004 גדולה \u0003כככר\u0004 — \u0003חייבין עליה משום טבל\u0004 אם לא עישרוהו, לפי שאנו נוהגים בפרי כאילו היה שייך לכל ענין כשל השנה שעברה, שהיא שנת מעשר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אילן שחנטו פירותיו קודם חמישה עשר בשבט\u0004 — \u0003מתעשר לשנה שעברה,\u0004 ואם חנטו פירותיו ל\u0003אחר חמישה עשר בשבט\u0004 — \u0003מתעשר לשנה הבאה. אמר ר' נחמיה: במה דברים אמורים\u0004 — \u0003באילן שעושה שתי בריכות בשנה,\u0004 כלומר, שני דורות של צאצאים בשנה.","על לשון זו תוהים: \u0003שתי בריכות סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 וכי מה צאצאים יש באילן? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כעין שתי בריכות.\u0004 כלומר, שני יבולים.","\u0003אבל אילן העושה\u0004 מטבעו \u0003בריכה אחת\u0004 בלבד, \u0003כגון דקלים וזיתים וחרובין,\u0004 שנותנים פירות רק פעם אחת בשנה, \u0003אף על פי שחנטו פירותיהן קודם חמישה עשר בשבט\u0004 — \u0003מתעשרין לשנה הבאה,\u0004 שהולכים בהם אחר זמן הלקיטה.","\u0003אמר ר' יוחנן: נהגו העם בחרובין כ\u0004שיטת \u0003ר' נחמיה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 על דבר זה: שנינו כי מין התאנים הקרויים \u0003בנות שוח\u0004 — \u0003שביעית שלהן\u0004 לענין איסור אכילה וחיוב ביעור הוא בשנה ה\u0003שניה\u0004 למעשר, \u0003מפני שעושות\u0004 פירות \u0003לשלש השנים,\u0004 ופירות שהבשילו בשנה השניה למחזור שנות השמיטה, חנטו כבר בשנת השמיטה. משמע שדנים לא לפי זמן הלקיטה אלא לפי זמן החנטה!","\u0003אישתיק\u0004 \u0005[שתק]\u0006 ר' יוחנן ולא השיב, שנראה כאילו אין בפיו תשובה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא הכהן לר' יוסי הכהן: אמאי אישתיק\u0004 \u0005[מדוע שתק]?\u0006 \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 לריש לקיש: \u0003אמינא לך אנא\u0004 \u0005[אומר אני לך]\u0006 שיטת \u0003ר' נחמיה ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 את שיטת \u0003רבנן\u0004 \u0005[חכמים]?!\u0006","ומשיבים: \u0003משום דאמר ליה\u0004 \u0005[ש\u0006היה \u0005אומר לו]\u0006 ריש לקיש: \u0003שבקת\u0004 \u0005[מניח אתה]\u0006 את דברי \u0003רבנן\u0004 \u0005[חכמים]\u0006 המרובים \u0003ועבדת\u0004 \u0005[ועושה אתה]\u0006 \u0003כ\u0004דברי \u0003ר' נחמיה\u0004 ששיטתו שיטת יחיד?!","ושואלים עוד: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן: \u0003קאמינא לך\u0004 \u0005[אני אומר לך]\u0006 שאין אני אלא מוסר מה ש\u0003\"נהגו\"\u0004 העם, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 דבר שהוא בעיקרו \u0003איסורא\u0004 \u0005[איסור]?!\u0006 ודוחים: גם כך לא היה יכול לענות לו, \u0003דאמר ליה\u0004 \u0005[שהיה\u0006 יכול ריש לקיש \u0005לומר לו]:\u0006 \u0003במקום איסורא, כי נהגו שבקינן להו\u0004 \u0005[במקום שיש איסור, כאשר\u0006 נהגו להיפך \u0005מניחים אנו להם]\u0006 לעשות כן?!","ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 ר' יוחנן לריש לקיש כך: \u0003כי אמינא לך אנא\u0004 \u0005[כאשר אמרתי לך אני]\u0006 כר' נחמיה — היה זה דווקא ב\u0003מעשר חרובין דרבנן\u0004 \u0005[ש\u0006הוא \u0005מדברי סופרים],\u0006 שאין חובת מעשר בחרובים מן התורה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003לי\u0004 מענין \u0003שביעית\u0004 שהיא \u0003דאורייתא\u0004 \u0005[מן התורה]?!\u0006 וכיון שזו היא תשובה ניצחת נראה שיש לברר שוב את המסורת בענין זה.","\u0003אלא אמר ר' אבא הכהן: תמיהני אם השיבה ריש לקיש לתשובה זו.\u0004 כלומר, שמא לא הקשה ריש לקיש קושיה זו שיש לה פירכה ברורה כזו. ותוהים: מה מקום לשאלה \u0003אם השיבה? הא אותבה\u0004 \u0005[הרי השיבה]\u0006 וכך היה המעשה! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003אם קיבלה ר' יוחנן,\u0004 ושתק משום שלא היה בידו מה לענות, \u0003אם\u0004 \u0005[או]\u0006 \u0003לא קיבלה,\u0004 ושתק מפני שסבר שאין שאלה זו ראויה לתשובה, כיון שאין לדמות ענין מעשר שהוא מדברי סופרים לענין שביעית שהיא מן התורה."],["\u0003בארבעה פרקים\u0004 (זמנים) בשנה \u0003העולם נידון: בפסח\u0004 נידון העולם \u0003על התבואה, בעצרת\u0004 (חג השבועות) נידון \u0003על פירות האילן\u0004 של השנה, \u0003בראש השנה\u0004 — \u0003כל באי עולם עוברין לפניו כבני מרון, שנאמר: \"היצר יחד לבם המבין אל כל מעשיהם\"\u0004 (תהלים לג, טו), \u0003ובחג\u0004 הסוכות \u0003נידונין על המים\u0004 של גשמי השנה הבאה.","נאמר במשנה שבפסח נידונים על התבואה, ושואלים: \u0003הי\u0004 \u0005[איזו]\u0006 \u0003תבואה? אילימא הא\u0004 \u0005[אם נאמר זאת]\u0006 ה\u0003תבואה דקיימא\u0004 \u0005[שעומדת\u0006 עכשיו\u0005]\u0006 בשיבוליה ועומדת להיקצר מפסח עד שבועות, \u0003כל הני הרפתקי דעדו עלה\u0004 \u0005[כל אותן הרפתקאות שבאו עליה]\u0006 בגשמים ובמזיקים במשך כל החורף \u0003אימת איתדון\u0004 \u0005[מתי נדונו עליה]?\u0006 \u0003אלא\u0004 צריך לומר שמדובר \u0003בתבואה דמזדרעא\u0004 \u0005[העתידה להזרע]\u0006 בשנה הבאה.","ועוד שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 \u0003דחד דינא מתדנא\u0004 \u0005[בדין אחד\u0006 היא \u0005נידונת]\u0006 ולא יותר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תבואה שאירע בה קרי\u0004 (מאורע, מכשול) \u0003או אונס,\u0004 אם אירע זה \u0003קודם הפסח\u0004 — \u0003נידונית לשעבר\u0004 בדין שהיה בשנה שעברה, ואם אירע בה \u0003לאחר הפסח\u0004 — \u0003נידונית להבא.\u0004 וכן \u0003אדם שאירע בו קרי או אונס,\u0004 אם היה זה \u0003קודם יום הכפורים\u0004 — \u0003נידון לשעבר\u0004 בראש השנה של השנה שעברה, \u0003לאחר יום הכפורים נידון להבא.\u0004 ואם כן, הרי שאותה תבואה עצמה נידונה פעמיים גם לפני פסח וגם לאחר הפסח.","\u0003אמר רבא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003תרי דיני מתדנא\u0004 \u0005[בשני דינים נידונת]\u0006 מזריעתה עד הפסח, ומפסח עד לקציר. \u0003אמר אביי: הלכך\u0004 \u0005[משום כך],\u0006 נלמד מכאן: \u0003כי חזי אינש דמצלח זרעא אפלא\u0004 \u0005[כאשר רואה אדם שמצליח הזרע האפיל],\u0006 כלומר, אותם צמחים שזורעים עוד בתחילת החורף והם מגיעים להבשלה רק באביב או בקיץ — \u0003ליקדים וליזרע חרפא\u0004 \u0005[שיקדים ויזרע זרע בכיר\u0006 הממהר לצמוח\u0005]\u0006 כגון שעורה, שאפשר לזרוע בסוף החורף ותצמח עד לאחרי פסח. והטעם — \u0003דעד דמטי למדייניה קדים סליק\u0004 \u0005[שעד שיבואו לדונו\u0006 בפסח הבא \u0005מקדים ועולה]\u0006 ואף יצליח בגידולו, שהרי כבר יודע הוא שנידון באותה שנה לטובה.","לגופה של המשנה שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו\u0006 זו\u0005]\u0006 שהרי היא \u0003לא\u0004 כשיטת \u0003ר' מאיר ולא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' יוסי ולא\u0004 כשיטת \u0003ר' נתן.\u0004","\u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003הכל נידונים בראש השנה, וגזר דין שלהם נחתם ביום הכפורים,\u0004 אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר: הכל נידונים בראש השנה, וגזר דין שלהם נחתם כל אחד ואחד בזמנו: בפסח\u0004 נחתם הדין \u0003על התבואה, בעצרת על פירות האילן, בחג\u0004 הסוכות הם \u0003נידונין על המים, ואדם נידון בראש השנה וגזר דין שלו נחתם ביום הכפורים.\u0004","\u0003ר' יוסי אומר: אדם נידון בכל יום\u0004 ולאו דווקא פעם אחת בשנה, \u0003שנאמר: \"ותפקדנו לבקרים\"\u0004 (איוב ז, יח), כלומר, שבכל בוקר יש פקידה ודיון. \u0003ר' נתן אומר: אדם נידון בכל שעה, שנאמר: \"לרגעים תבחננו\"\u0004 (איוב ז, יח).","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לעולם\u0004 משנתנו כשיטת \u0003ר' יהודה היא, וכי קתני מתניתין\u0004 \u0005[וכאשר שנויה משנתנו]\u0006 הרי היא לענין \u0003גזר הדין\u0004 (\"חתימה\") ולא לעיקר הדין, שהוא אכן נעשה לכולם בראש השנה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 — \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003אדם,\u0004 שהיה צריך להוסיף שביום הכפורים נידון האדם!","\u0003אמר רבא: האי תנא\u0004 \u0005[תנא זה]\u0006 של משנתנו הוא תנא \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל היא, דתנא דבי\u0004 \u0005[ששנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, בארבעה פרקים העולם נידון: בפסח על התבואה, בעצרת על פירות האילן, בחג נידונין על המים, ואדם נידון בראש השנה וגזר דין שלו נחתם ביום הכפורים. וכי קתני מתניתין\u0004 \u0005[וכאשר שנויה משנתנו],\u0006 הריהי שנויה על \u0003תחלת\u0004 ה\u0003דין,\u0004 שאדם נידון בראש השנה.","\u0003אמר רב חסדא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי?\u0004 על שאלה זו תוהים: מה מקום לחפש את טעמו, הלא \u0003כדקאמר טעמיה\u0004 \u0005[כפי שאמר את טעמו]:\u0006 \u0003\"ותפקדנו לבקרים\"!\u0004 ומסבירים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אמרנו]:\u0006 אם הסתמך ר' יוסי על פסוק זה — \u0003מאי טעמא\u0004 \u0005[מה טעם,\u0006 מדוע\u0005]\u0006 \u0003לא אמר כר' נתן\u0004 שאדם נידון בכל שעה? ואם תאמר שהוא סבור ש\"לרגעים תבחננו\" אינו ראיה כי \u0003בחינה עיוני בעלמא\u0004 \u0005[עיון בלבד]\u0006 \u0003היא\u0004 ולא משפט ממש — אם כן באותו אופן יש לומר כי \u0003פקידה נמי עיוני בעלמא\u0004 \u0005[גם כן עיון בלבד]\u0006 \u0003היא,\u0004 ואם כן אין הוכחה גמורה מכתוב זה.","\u0003אלא אמר רב חסדא: טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' יוסי מהכא\u0004 \u0005[מכאן]\u0006 מכתוב אחר, שנאמר: \u0003\"לעשות משפט עבדו ומשפט עמו ישראל דבר יום ביומו\" (מלכים א' ח, נט), משמע שבכל יום נידון העולם. ועל אותו פסוק\u0004","\u0003אמר רב חסדא:\u0004 כאשר \u0003מלך וצבור\u0004 באין לדין שמים — \u0003מלך נכנס תחלה לדין, שנאמר: \"לעשות משפט עבדו\"\u0004 ואחר כך \u0003\"ומשפט עמו ישראל\". מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לאו אורח ארעא למיתב מלכא אבראי\u0004 \u0005[אין זה דרך ארץ שישב המלך מבחוץ],\u0006 וימתין לאחרים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 מוטב שידון המלך לבדו \u0003מקמי דליפוש\u0004 \u0005[מלפני שירבה]\u0006 \u0003חרון אף\u0004 על חטאי העם, שמא יצא דינו לזכות.","\u0003אמר רב יוסף: כמאן מצלינן האידנא אקצירי ואמריעי\u0004 \u0005[כ\u0006שיטת \u0005מי מתפללים אנו עכשיו על חולים וסובלי יסורים]\u0006 בכל יום כשאדם חולה, \u0003כמאן\u0004 \u0005[כמי]\u0006 — \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 שכיון שלדעתו אדם נידון בכל יום, אם כן יש טעם להתפלל בכל יום ולשנות את דינו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 עושים אנו זאת אפילו \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 שאדם נידון פעם אחת בשנה, אולם מנהגנו הוא על פי דברי \u0003ר' יצחק\u0004 ש\u0003אמר ר' יצחק: יפה צעקה לאדם\u0004 שיתפלל ויצעק לה' \u0003בין קודם גזר דין\u0004 של מעלה \u0003בין לאחר גזר דין.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יהודה משום ר' עקיבא: מפני מה אמרה תורה הביאו עומר בפסח\u0004 — \u0003מפני שהפסח זמן תבואה הוא,\u0004 שאז מתחיל עיקר הקציר, ולכך \u0003אמר הקדוש ברוך הוא: הביאו לפני עומר בפסח, כדי שתתברך לכם תבואה שבשדות. ומפני מה אמרה\u0004 ה\u0003תורה הביאו שתי הלחם בעצרת\u0004 (חג השבועות) — \u0003מפני שעצרת זמן\u0004 התחלת בישול \u0003פירות האילן הוא,\u0004 ולכך \u0003אמר הקדוש ברוך הוא: הביאו לפני שתי הלחם בעצרת, כדי שיתברכו לכם פירות האילן.\u0004","\u0003ומפני מה אמרה\u0004 ה\u0003תורה נסכו מים בחג\u0004 (הסוכות) — \u0003אמר הקדוש ברוך הוא: נסכו לפני מים בחג, כדי שיתברכו לכם גשמי שנה\u0004 המתחילים לאחר חג הסוכות. \u0003ואמרו לפני בראש השנה\u0004 בתפילה \u0003מלכיות זכרונות ושופרות.\u0004 וטעמו של דבר: \u0003מלכיות\u0004 — \u0003כדי שתמליכוני עליכם, זכרונות\u0004 — \u0003כדי שיעלה זכרוניכם לפני לטובה, ובמה\u0004 עולה הזכרון — \u0003בשופר.\u0004","בשיטה דומה \u0003אמר ר' אבהו: למה תוקעין בשופר של איל? אמר הקדוש ברוך הוא: תקעו לפני בשופר של איל, כדי שאזכור לכם עקידת יצחק בן אברהם\u0004 שנשחט תמורתו איל, \u0003ומעלה אני עליכם כאילו\u0004 אתם \u0003עקדתם עצמכם לפני.\u0004","\u0003אמר ר' יצחק: למה תוקעין בראש השנה?\u0004 על שאלה זו תוהים: \u0003למה תוקעין?! רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 \u0003תקעו! אלא\u0004 השאלה היא: \u0003למה מריעין?\u0004 ושוב תוהים: \u0003מריעין?! רחמנא אמר\u0004 \u0005[התורה אמרה]\u0006 \u0003\"בחודש השביעי באחד לחודש יהיה לכם שבתון זכרון תרועה\"\u0004 (ויקרא כג, כד) משמע שיום זה צריך להריע בו; \u0003אלא\u0004 כך היתה השאלה — על מנהג ישראל שאינו מפורש בתורה: \u0003למה תוקעין ומריעין כשהן יושבין\u0004 לפני תפילת שמונה עשרה,"],["\u0003ותוקעין ומריעין כשהן עומדין\u0004 בתפילת שמונה עשרה — \u0003כדי לערבב\u0004 (לבלבל) את \u0003השטן,\u0004 שתקיעה כפולה זו חיבוב מצוה היא ופועלת כנגד יצריו הרעים, וממתיקה את דינו.","\u0003ואמר ר' יצחק: כל שנה שאין תוקעין לה בתחלתה,\u0004 שבשל תקלה כלשהי לא יכלו לתקוע — \u0003מריעין לה\u0004 (עושים לה רע) \u0003בסופה\u0004 בהסתמכות על כפל המשמעות של תקיעה ותרועה. \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר] —\u0006 ש\u0003לא איערבב\u0004 \u0005[בולבל]\u0006 ה\u0003שטן\u0004 והוא מקטרג, וישראל נענשים.","ומכאן ואילך מביאים שרשרת עניינים בשמו של ר' יצחק הקשורים כולם בבעיית דינו של אדם. \u0003ואמר ר' יצחק: כל שנה שרשה\u0004 (ענייה) ויש בה צרות \u0003בתחלתה\u0004 — \u0003מתעשרת בסופה, שנאמר: \"מרשית השנה\u0004 ועד אחרית שנה \u0003\"(דברים יא, יב), \"מרשית\" כתיב\u0004 \u0005[נאמר]\u0006 חסר אל\"ף, לשון רש, עני. ונאמר: \u0003\"ועד אחרית\",\u0004 כלומר, \u0003סופה שיש לה אחרית\u0004 — תקוה ותוחלת.","\u0003ואמר ר' יצחק: אין דנין את האדם אלא לפי מעשיו של אותה שעה\u0004 ולא לפי מה שהוא עתיד לעשות, \u0003שנאמר: \"כי שמע אלהים אל קול הנער באשר הוא שם\"\u0004 (בראשית כא, יז), שאף שעתידים בניו של ישמעאל להרשיע הרבה, כיון שבאותה שעה היה חף מפשע — נשמעה תפילתו.","\u0003ואמר ר' יצחק: שלשה דברים מזכירין עונותיו של אדם\u0004 ו\u0003אלו הן:\u0004 העובר או יושב ליד \u0003קיר נטוי\u0004 או מקום סכנה אחר. \u0003ועיון תפלה,\u0004 שאדם מתפלל ובוטח שתישמע תפילתו. \u0003ומוסר דין על חבירו,\u0004 שמבקש שישפוט ה' ביניהם. ש\u0003אמר ר' אבין: כל המוסר דין על חבירו\u0004 לשמים — \u0003הוא נענש תחלה,\u0004 לפי שבדין שמים מוציאים גם מקצת פגמים שלו, \u0003שנאמר: \"ותאמר שרי אל אברם חמסי עליך\u0004 אנכי נתתי שפחתי בחיקך ותרא כי הרתה ואקל בעיניה ישפוט ה' ביני ובינך \u0003\"(בראשית טז, ה) וכתיב\u0004 \u0005[ונאמר]:\u0006 אחר כך \u0003\"ויבא אברהם לספד לשרה ולבכתה\"\u0004 (בראשית כג, ב), ולמדנו מכאן שכיון שמסרה דינו לשמים — נענשה, ומתה היא תחילה.","\u0003ואמר ר' יצחק: ארבעה דברים מקרעין גזר דינו של אדם\u0004 שנכתב עליו לרע, ומשנים אותו לטובה. ו\u0003אלו הן:\u0004 מתן \u0003צדקה, צעקה\u0004 בתפילה, \u0003שינוי השם, ושינוי מעשה,\u0004 שמשנה את מעשיו לטובה. ולכולם רמז במקרא; \u0003צדקה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וצדקה תציל ממות\"\u0004 (משלי י, ב). \u0003צעקה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצעקו אל ה' בצר להם וממצקתיהם יוציאם\"\u0004 (תהלים קז, כח). \u0003שינוי השם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שרי אשתך לא תקרא את שמה שרי כי שרה שמה\"\u0004 (בראשית יז, טו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"וברכתי אתה וגם נתתי ממנה לך בן\"\u0004 (בראשית יז, טז). \u0003שינוי מעשה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא האלהים את מעשיהם\"\u0004 (יונה ג, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם: \u0003\"וינחם האלהים על הרעה אשר דבר לעשות להם ולא עשה\"\u0004 (יונה ג, י).","\u0003ויש אומרים: אף שינוי מקום\u0004 מבטל דינו של אדם, שנאמר: \u0003\"ויאמר ה' אל אברם לך לך מארצך\"\u0004 (בראשית יב, א), \u0003והדר\u0004 \u0005[ואחר כך]\u0006 נאמר: \u0003\"ואעשך לגוי גדול\"\u0004 (בראשית יב, ב). ומסבירים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלא מנה שינוי מקום, סבור שלא זה היה הטעם, אלא \u0003ההוא זכותא\u0004 \u0005[זכותה]\u0006 של \u0003ארץ ישראל\u0004 שהיא מקום מקודש \u0003הוא דאהניא ליה\u0004 \u0005[היא שהועילה לו].\u0006","\u0003ואמר ר' יצחק: חייב אדם להקביל פני רבו\u0004 לבוא לפוגשו \u0003ברגל\u0004 (בחג), \u0003שנאמר\u0004 ששאל בעל השונמית אותה כשהלכה לנביא: \u0003\"מדוע את הלכת אליו היום לא חדש ולא שבת\"\u0004 (מלכים ב' ד, כג), \u0003מכלל\u0004 (מכאן) \u0003דבחדש\u0004 \u0005[שבראש חודש]\u0006 \u0003ובשבת\u0004 (כלומר, יום חג, יום שבתון) \u0003איבעי לה למיזל\u0004 \u0005[צריכה היתה ללכת].\u0006","\u0003ואמר ר' יצחק: חייב אדם לטהר עצמו ברגל, שנאמר: \"ובנבלתם לא תגעו\"\u0004 (ויקרא יא, ח), ופסוק זה עוסק בענין הרגל.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 בהרחבה; נאמר: \u0003\"ובנבלתם לא תגעו\"\u0004 (ויקרא יא, ח), \u0003יכול יהו ישראל מוזהרין\u0004 ואסורים \u0003על מגע נבילה, תלמוד לומר: \"אמר אל הכהנים בני אהרן\u0004 ואמרת אליהם לנפש לא יטמא בעמיו\u0003\"\u0004 (ויקרא כא, א) ומכאן: \u0003בני אהרן מוזהרין\u0004 מלהיטמא, אולם \u0003בני ישראל אין מוזהרין.\u0004","\u0003והלא דברים קל וחומר: ומה טומאה חמורה\u0004 של מת רק \u0003כהנים מוזהרין, ישראלים אינם מוזהרין. טומאה קלה\u0004 של נבילה — \u0003לא כל שכן\u0004 שאין ישראל מוזהרים עליה? \u0003אלא, מה תלמוד לומר \"ובנבלתם לא תגעו\"\u0004 — \u0003ב\u0004זמן ה\u0003רגל\u0004 שאז חייבים הכל להיות טהורים.","עתה שבים לעסוק בענין יום הדין, \u0003אמר ר' כרוספדאי אמר ר' יוחנן: שלשה ספרים נפתחין בראש השנה\u0004 לפני הקדוש ברוך הוא, \u0003אחד של רשעים גמורין, ואחד של צדיקים גמורין, ואחד של בינוניים\u0004 שמעשיהם שקולים. \u0003צדיקים גמורין\u0004 — \u0003נכתבין ונחתמין לאלתר\u0004 (מיד) \u0003לחיים, רשעים גמורין\u0004 — \u0003נכתבין ונחתמין לאלתר למיתה, בינוניים\u0004 — \u0003תלויין ועומדין מראש השנה ועד יום הכפורים, זכו\u0004 במעשים טובים ובמצוות שהוסיפו בימים אלה — \u0003נכתבין לחיים, לא זכו\u0004 — \u0003נכתבין למיתה.\u0004","\u0003אמר ר' אבין: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על כך — שנאמר: \u0003\"ימחו מספר חיים ועם צדיקים אל יכתבו\"\u0004 (תהלים סט, כט), \u0003\"ימחו מספר\"\u0004 — \u0003זה ספרן של רשעים גמורין,\u0004 שהם נמחקים מן העולם, \u0003\"חיים\"\u0004 — \u0003זה ספרן של צדיקים, \"ועם צדיקים לא יכתבו\"\u0004 — \u0003זה ספרן של בינוניים,\u0004 שנכתבים בספר לעצמם, לא עם הצדיקים.","\u0003רב נחמן בר יצחק אמר, מהכא\u0004 \u0005[מכאן]\u0006 נלמד הדבר, ממה שנאמר: \u0003\"ואם אין מחני נא מספרך אשר כתבת\"\u0004 (שמות לב, לב) \u0003\"מחני נא\"\u0004 — \u0003זה ספרן של רשעים\u0004 שהם נימחים, \u0003\"מספרך\"\u0004 — \u0003זה ספרן של צדיקים\u0004 שהוא מיוחד ומיוחס לה', \u0003\"אשר כתבת\"\u0004 — \u0003זה ספרן של בינוניים.\u0004","בדומה לרעיון זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003בית שמאי אומרים: שלש כתות הן ליום הדין\u0004 הגדול שבאחרית הימים: \u0003אחת של צדיקים גמורין, ואחת של רשעים גמורין, ואחת של בינוניים. צדיקים גמורין\u0004 — \u0003נכתבין ונחתמין לאלתר לחיי עולם, רשעים גמורין\u0004 — \u0003נכתבין ונחתמין לאלתר לגיהנם, שנאמר: \"ורבים מישני אדמת עפר יקיצו אלה לחיי עולם ואלה לחרפות לדראון עולם\"\u0004 (דניאל יב, ב), \u0003בינוניים\u0004 — \u0003יורדין לגיהנם\u0004 שיתמרקו ויתכפרו עונותיהם,"],["\u0003ומצפצפין\u0004 (וצועקים) מכאביהם \u0003ועולין\u0004 משם, \u0003שנאמר: \"והבאתי את השלשית באש וצרפתים כצרף את הכסף ובחנתים כבחן את הזהב הוא יקרא בשמי ואני אענה אתו\"\u0004 (זכריה יג, ט), ואלה הם בני הכת השלישית הצריכים צירוף וניקוי, \u0003ועליהם אמרה חנה \"ה' ממית ומחיה מוריד שאול ויעל\"\u0004 (שמואל א' ב, ו).","\u0003בית הלל אומרים\u0004 לגבי הבינוניים כיון שנאמר במידות ה': \u0003\"ורב חסד\",\u0004 הרי מידה זו \u0003מטה כלפי חסד, ועליהם אמר דוד: \"אהבתי כי ישמע ה' את קולי\u0004 תחנוני \u0003\"(תהלים קטז, א). ועליהם אמר דוד\u0004 את \u0003כל הפרשה כולה \"דלתי ולי יהושיע\"\u0004 (תהלים קטז, ו), שאף שהם דלים במצוות — ה' מושיעם.","\u0003פושעי ישראל\u0004 שפשעו בעבירות \u0003בגופן,\u0004 וכן \u0003פושעי אומות העולם\u0004 שפשעו \u0003בגופן\u0004 — \u0003יורדין לגיהנם ונידונין בה שנים עשר חדש. לאחר שנים עשר חדש\u0004 — \u0003גופן כלה, ונשמתן נשרפת, ורוח מפזרתן תחת כפות רגלי צדיקים, שנאמר: \"ועסותם רשעים כי יהיו אפר תחת כפות רגליכם\"\u0004 (מלאכי ג, כא).","\u0003אבל המינין\u0004 שהם בני כתות כופרות \u0003והמסורות\u0004 (המלשינים) \u0003והאפיקורסים\u0004 המזלזלים בתורה ובחכמיה \u0003שכפרו בתורה, ושכפרו בתחיית המתים, ושפירשו מדרכי צבור\u0004 ולא רצו להשתתף עם כלל ישראל בצרותיהם, \u0003ושנתנו חיתיתם\u0004 (פחדם) \u0003בארץ חיים,\u0004 שהטילו אימה על הבריות, \u0003ושחטאו והחטיאו את הרבים, כגון ירבעם בן נבט וחביריו\u0004 — \u0003יורדין לגיהנם ו\u0004הם אינם יוצאים משם מיד אלא \u0003נידונין בה לדורי דורות, שנאמר: \"ויצאו וראו בפגרי האנשים הפשעים בי\u0004 כי תולעתם לא תמות ואשם לא תכבה והיו דראון לכל בשר","\u0003\"\u0004(ישעיה סו, כד). ועליהם אמרו: \u0003גיהנם כלה והן אינן כלין, שנאמר: \"וצורם לבלות שאול מזבל לו\"\u0004 (תהלים מט, טו), שכביכול שאול תכלה לפני שייגמר עונשם. \u0003וכל כך למה\u0004 הם נענשים — \u0003מפני שפשטו ידיהם בזבול,\u0004 במקדש ובדברים המקודשים, \u0003שנאמר: \"מזבל לו\"\u0004 (תהלים מט, טו) \u0003ואין \"זבול\" אלא בית המקדש, שנאמר: \"בנה בניתי בית זבל לך\"\u0004 (מלכים א' ח, יג) \u0003ועליהם אמרה חנה: \"ה' יחתו מריבו\"\u0004 (שמואל א' ב, י).","\u0003אמר ר' יצחק בר אבין: ופניהם\u0004 בשעת הדין \u0003דומין לשולי\u0004 (לתחתית) \u0003קדירה\u0004 שהיא שחורה ומפוייחת. \u0003ואמר רבא: ואינהו משפירי שפירי\u0004 \u0005[והם מהיפים־יפים]\u0006 מ\u0003בני מחוזא,\u0004 שסבר רבא שבני העיר מחוזא היו רובם רשעים, \u0003ומקריין\u0004 \u0005[ונקראים]\u0006 \u0003בני גיהנם\u0004 משום שהם זוכים להיתקן בגיהנם.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003בית הלל אומרים: \"ורב חסד\"\u0004 (שמות לד, ו), ללמד כי הקדוש ברוך הוא \u0003מטה\u0004 בדינו \u0003כלפי חסד,\u0004 ואם כן, הבינוניים אינם נידונים לגיהנם. ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"והבאתי את השלשית באש\"\u0004 (זכריה יג, ט), משמע שיש כת שלישית הנדונה בגיהנם, אבל לא לעולם! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בפסוק זה, מדובר \u0003בפושעי ישראל בגופן.\u0004","ותוהים: \u0003פושעי ישראל בגופן\u0004 — \u0003והא אמרת לית להו תקנתא\u0004 \u0005[והרי אמרת\u0006 ש\u0005אין להם תקנה]!\u0006 ומשיבים: \u0003כי לית להו תקנתא\u0004 \u0005[כאשר אין להם תקנה],\u0006 הרי זה כשהיו פושעים בגופם נוסף למה שהיה להם \u0003ברוב עונות,\u0004 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003במחצה עונות ובמחצה זכיות, ואית בהו נמי\u0004 \u0005[ויש בהם גם\u0006 בין העוונות \u0005גם כן]\u0006 \u0003עון\u0004 של \u0003פושעי ישראל בגופן,\u0004 ולכן \u0003לא סגיא ליה\u0004 \u0005[מספיק לו]\u0006 לאיש כזה \u0003דלאו\u0004 \u0005[שלא\u0006 יתקיים בו\u0005]\u0006 \u0003\"והבאתי את השלישית באש\". ואם לאו\u0004 \u0005[לא]\u0006 חטא בגופו — \u0003\"ורב חסד\"\u0004 — \u0003מטה כלפי חסד. ועליהן אמר דוד: \"אהבתי כי ישמע ה'\"\u0004 (תהלים קטז, א).","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אהבתי כי ישמע ה'\"\u0004 (תהלים קטז, א) — \u0003אמרה כנסת ישראל לפני הקדוש ברוך הוא: רבונו של עולם, אימתי\u0004 אני יודעת ש\u0003אני אהובה עליך\u0004 — \u0003בזמן שאתה שומע קול תחנוני, \"דלתי ולי יהושיע\"\u0004 (תהלים קטז, ו) — \u0003אף על פי שדלה אני מן המצות\u0004 בכל זאת \u0003לי נאה להושיע.\u0004","ושואלים: \u0003פושעי ישראל בגופן מאי ניהו\u0004 \u0005[מה הם]?\u0006 \u0003אמר רב: קרקפתא דלא מנח\u0004 \u0005[גולגולת שאינה מניחה]\u0006 \u0003תפילין,\u0004 שכל שאינו מניח כלל תפילין הוא הנקרא פושע ישראל בגופו. \u0003פושעי אומות העולם בגופן\u0004 מה הם? \u0003אמר רב:\u0004 שחוטאים \u0003בעבירה\u0004 של זנות.","\u0003ושנתנו חיתיתם בארץ חיים\u0004 שהזכרנו מי הם? \u0003אמר רב חסדא: זה פרנס המטיל אימה יתירה על הצבור שלא לשם שמים. אמר רב יהודה אמר רב: כל פרנס המטיל אימה יתירה על הצבור שלא לשם שמים\u0004 נענש ו\u0003אינו רואה בן תלמיד חכם, שנאמר: \"לכן יראוהו אנשים לא יראה כל חכמי לב\"\u0004 (איוב לז, כד), שמי שגורם ש\"יראוהו\" — יפחדו ממנו אנשים, לא יראה במשפחתו עוד חכמי לב.","שנינו שם, \u0003בית הלל אומרים: \"ורב חסד\"\u0004 — \u0003מטה כלפי חסד.\u0004 ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד עושה]\u0006 הטייה זו? \u0003ר' אליעזר אומר: כובשו,\u0004 כביכול מכביד הקדוש ברוך הוא את כף המאזנים של זכות, \u0003שנאמר: \"ישוב ירחמנו יכבש עונתינו\"\u0004 (מיכה ז, יט). \u0003ר' יוסי בר חנינא אמר: נושא\u0004 ומיקל מן העבירות, \u0003שנאמר: \"נשא עון ועבר על פשע\"\u0004 (מיכה ז, יח).","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מעביר\u0004 וסולח \u0003ראשון ראשון מן העבירות, וכן היא המדה\u0004 של מידות הרחמים שהוא מעביר וסולח על החטא הראשון, ובכך מיקל הוא את כף החובה. \u0003אמר רבא: ו\u0004אותו \u0003עון עצמו\u0004 שאיתו הטה ה' כלפי חסד, \u0003אינו נמחק\u0004 לגמרי. שכן \u0003אי איכא רובא\u0004 \u0005[אם יש לו\u0006 לאדם \u0005רוב]\u0006 \u0003עונות\u0004 — \u0003מחשיב בהדיהו\u0004 \u0005[נחשב אתם],\u0006 אלא שאם הוא שקול מטים את דינו לכף זכות.","אגב הבאת פסוק זה, \u0003רבא אמר: כל המעביר על מדותיו,\u0004 שמוותר על מה שמגיע לו מן הדין — \u0003מעבירין לו\u0004 (סולחים לו) \u0003על כל פשעיו, שנאמר: \"נשא עון ועבר על פשע\".\u0004 וכך הוא מפרש: \u0003למי נושא\u0004 הקדוש ברוך הוא \u0003עון\u0004 — \u0003למי שעובר על פשע\u0004 שעושים כלפיו.","וכעין זה מסופר: \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע חלש\u0004 \u0005[חלה],\u0006 \u0003על\u0004 \u0005[נכנס]\u0006 \u0003רב פפא לשיולי ביה\u0004 \u0005[לשאול בו,\u0006 בשלומו\u0005].\u0006 \u0003חזייה דחליש ליה עלמא\u0004 \u0005[ראה שנחלש עולמו]\u0006 שהוא נוטה למות, \u0003אמר להו\u0004 \u0005[להם]\u0006 למטפלים בו: \u0003צביתו ליה זוודתא\u0004 \u0005[הכינו לו צידה],\u0006 כלומר, תכריכים ושאר צרכי המת. \u0003לסוף איתפח\u0004 \u0005[הבריא]\u0006 רב הונא, \u0003הוה מכסיף\u0004 \u0005[היה מתבייש]\u0006 \u0003רב פפא למיחזייה\u0004 \u0005[לראות אותו],\u0006 שנראה כאילו גזר את דינו של חבירו למיתה. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 ידידי רב הונא לרב הונא: \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 כשהיית באותו מצב של גסיסה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין, הכי הוה\u0004 \u0005[כן, כך היה]\u0006 והייתי באמת קרוב למות, \u0003ואמר להו\u0004 \u0005[להם]\u0006 \u0003הקדוש ברוך הוא\u0004 לבית דין של מעלה: \u0003הואיל ולא מוקים במיליה\u0004 \u0005[ואיננו מעמיד בדבריו]\u0006 ומוותר — \u0003לא תקומו בהדיה\u0004 \u0005[אל תעמדו אתו]\u0006 לדקדק בדינו, \u0003שנאמר: \"נשא עון ועבר על פשע\"\u0004 (מיכה ז, יח), ללמד כי \u0003למי נושא עון\u0004 — \u0003למי שעובר על פשע.\u0004","נאמר שם: \u0003\"לשארית נחלתו\"\u0004 (מיכה ז, יח) \u0003אמר רב אחא בר חנינא: אליה\u0004 — \u0003וקוץ בה\u0004 כלומר, דבר טוב ושמן הוא כמו אליה, אבל יש בה גם קוץ ופגם, שאמנם ה' מוחל וסולח, אבל נוספת הגבלה קשה: \u0003\"לשארית נחלתו\"\u0004 משמע — \u0003ולא לכל נחלתו,\u0004"],["ושארית זו היא — \u0003למי שמשים עצמו כשירים\u0004 כבלתי חשוב, כטפל.","\u0003רב הונא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005];\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"צדיק ה' בכל דרכיו\"\u0004 (תהלים קמה, יז), משמע שהוא נוהג לפי מידת הצדק והמשפט, \u0003וכתיב\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וחסיד בכל מעשיו\",\u0004 משמע שהוא נוהג בחסד, לפנים משורת הדין! והסביר: \u0003בתחלה,\u0004 בשעת הדין — הוא \u0003צדיק, ולבסוף\u0004 כשמגיעה שעת העונש הוא \u0003חסיד.\u0004","\u0003ר' אלעזר רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005];\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ולך ה' חסד\"\u0004 (תהלים סב, יג), משמע שה' נוהג לפנים משורת הדין \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק: \u0003\"כי אתה תשלם\u0004 לאיש \u0003כמעשהו\",\u0004 משמע שהוא משלם מידה כנגד מידה! והשיב: \u0003בתחלה \"כי אתה תשלם\u0004 לאיש \u0003כמעשהו\", ולבסוף\u0004 — \u0003\"ולך ה' חסד\".\u0004","\u0003אילפי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה החכם \u0003אילפא, רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ורב חסד\"\u0004 (שמות לד, ו) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 באותו פסוק \u0003\"ואמת\",\u0004 שהיא לכאורה מידת הדין! והשיב: \u0003בתחלה \"ואמת\",\u0004 שהוא שורת הדין, \u0003ולבסוף\u0004 כשאין האדם יכול לעמוד במשפט שכולו אמת — \u0003\"ורב חסד\".\u0004","נאמר שם לפני רשימת מידות הרחמים \u0003\"ויעבר ה' על פניו ויקרא\"\u0004 (שמות לד, ו). \u0003אמר ר' יוחנן: אלמלא מקרא כתוב\u0004 במפורש \u0003אי אפשר\u0004 היה \u0003לאומרו,\u0004 שיש בו כביכול פחיתות כבוד כלפי מעלה, \u0003מלמד שנתעטף הקדוש ברוך הוא כשליח צבור\u0004 שמתעטף בטליתו, \u0003והראה לו למשה סדר תפלה. אמר לו: כל זמן שישראל חוטאין\u0004 — \u0003יעשו לפני כסדר הזה ואני מוחל להם,\u0004 שיתעטף שליח ציבור ויאמר בציבור שלוש עשרה מידות הרחמים.","באותו ענין נאמר \u0003\"ה' ה'\",\u0004 ופירושו: \u0003אני הוא קודם שיחטא האדם, ואני הוא לאחר שיחטא האדם ויעשה תשובה,\u0004 שאין ה' זוכר לו את חטאיו הראשונים, תמיד הוא \u0003\"אל רחום וחנון\".\u0004","\u0003אמר רב יהודה: ברית כרותה לשלש עשרה מדות שאינן חוזרות ריקם שאם אדם מזכיר אותן בודאי נענה, שנאמר\u0004 באותו עניין: \u0003\"הנה אנכי כרת ברית\"\u0004 (שמות לד, י).","\u0003אמר ר' יוחנן: גדולה תשובה שמקרעת גזר דינו של אדם. שנאמר: \"השמן לב העם הזה ואזניו הכבד ועיניו השע פן יראה בעיניו ובאזניו ישמע ולבבו יבין ושב ורפא לו\"\u0004 (ישעיה ו, י), משמע שאם ישוב — ירפא לו מכל מה שחטא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ודלמא\u0004 \u0005[ושמא]\u0006 נאמר הדבר \u0003לפני גזר דין,\u0004 אבל לאחר גזר דין אין התשובה מועלת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 \"ושב \u0003ורפא לו\" כתיב\u0004 \u0005[נאמר\u0006 שם\u0005],\u0006 \u0003איזהו דבר שצריך רפואה\u0004 — משמע שכבר היתה מכה הצריכה רפואה, \u0003הוי אומר זה גזר דין,\u0004 ומשישוב — אזי \"ושב ורפא לו\".","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה שנאמר בברייתא: \u0003השב בינתים,\u0004 בין ראש השנה ליום הכיפורים — \u0003מוחלין לו, לא שב בינתים, אפילו הביא כל אילי נביות\u0004 (שהם מובחרים) \u0003שבעולם\u0004 והביאם לקרבנות — \u0003אין מוחלין לו!\u0004 הרי שלאחר שנגזר הדין אינו האדם יכול לשנותו אף בתשובה גדולה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שזמן תשובתו דווקא בעשרת ימי תשובה — \u0003ביחיד, הא\u0004 \u0005[זה]\u0006 שמוחלים להם בכל עת שהם חוזרים — \u0003בצבור.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים],\u0006 נאמר: \u0003\"\u0004ארץ אשר ה' אלוקיך דורש אותה תמיד \u0003עיני ה' אלהיך בה\"\u0004 (דברים יא, יב) — \u0003עתים\u0004 שהשגחה תמידית של ה' בארץ ישראל היא דבר \u0003לטובה,\u0004 ו\u0003עתים לרעה. עתים לטובה כיצד? הרי שהיו ישראל רשעים גמורין בראש השנה ופסקו להם\u0004 לפי הראוי להם \u0003גשמים מועטים\u0004 באותה שנה, ול\u0003בסוף חזרו בהן\u0004 למוטב, \u0003להוסיף עליהן\u0004 על הגשמים \u0003אי אפשר\u0004 — \u0003ש\u0004הרי \u0003כבר נגזרה גזרה, אלא הקדוש ברוך הוא מורידן,\u0004 לאותם גשמים מועטים שנגזרו \u0003בזמנן\u0004 הראוי להם \u0003על הארץ הצריכה להן,\u0004 בשדות ובכרמים ובגינות — \u0003הכל לפי הארץ,\u0004 ונמצא שהגשמים המעטים מועילים כגשמים מרובים.","ולהיפך, \u0003עתים לרעה כיצד? הרי שהיו ישראל צדיקים גמורין בראש השנה ופסקו עליהן גשמים מרובין לבסוף חזרו בהן\u0004 והרשיעו, \u0003לפחות מהן\u0004 ממה שנגזר \u0003אי אפשר ש\u0004הרי \u0003כבר נגזרה גזרה, אלא הקדוש ברוך הוא מורידן\u0004 לאותם הגשמים \u0003שלא בזמנן, על הארץ שאינה צריכה להן,\u0004 ביערות ובמדבריות.","ושואלים: כיון שיש עתים \u0003לטובה, מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003לקרעיה לגזר דנייהו ולוסיף להו\u0004 \u0005[שיקרע את גזר דינם ויוסיף להם]\u0006 ולכאורה משמע שאין גזר דין נקרע, אפילו עשה כל הציבור תשובה! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אפשר בהכי\u0004 \u0005[בכך],\u0006 כלומר, כדי להפוך את תוצאת הגזר דין לטובה, אין צורך שתשתנה גזירת המקום, ואפשר שייעשה הדבר בלא שינוי.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממקום אחר ראיה לדבר: נאמר, \u0003\"יורדי הים באניות עשי מלאכה במים רבים. המה ראו מעשי ה'\u0004 ונפלאותיו במצולה. \u0003ויאמר ויעמד רוח סערה ותרומם גליו. יחוגו וינועו כשכור\u0004 וכל חכמתם תתבלע. \u0003ויצעקו אל ה' בצר להם\u0004 וממצוקותיהם יוציאם. \u0003יודו לה' חסדו\u0004 ונפלאותיו לבני אדם\u0003\"\u0004 (תהלים קז, כג-כח. ותהלים קז, לא)","\u0003עשה להן\u0004 לפרשיות אלה בין קטע לקטע \u0003סימניות כאכין ורקין שבתורה,\u0004 לומר לנו על ידי סימניות אלה שכמו שהביטויים בתורה הם מדוייקים ואי אפשר לשנות מהם — כך אלה אין לשנות מהם. \u0003לומר לך:\u0004 אם \u0003צעקו קודם גזר דין\u0004 — הרי הם \u0003נענין, צעקו לאחר גזר דין\u0004 — \u0003אינן נענין!\u0004","ומשיבים: מכאן אין קושיה, \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 יורדי הים \u0003כיחידין דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שאף שמדובר באנשים רבים, הרי אינם ציבור שלם, אלא רק קבוצה מצומצמת ומוגדרת.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003שאלה בלוריא הגיורת את רבן גמליאל, כתיב\u0004 \u0005[נאמר]\u0006 \u0003בתורתכם: \"אשר לא ישא פנים\"\u0004 (דברים י, יז) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ישא ה' פניו אליך\"\u0004 (במדבר ו, כו), כיצד מיישבים סתירה זו?","\u0003נטפל לה ר' יוסי הכהן\u0004 להשיב לה. \u0003אמר לה: אמשול לך משל, למה הדבר דומה? לאדם שנושה בחבירו מנה וקבע לו זמן\u0004 לפרעון \u0003בפני המלך, ונשבע לו בחיי המלך\u0004 שיפרע, ו\u0003הגיע זמן ולא פרעו. בא לפייס את המלך\u0004 על שנשבע בשמו ולא קיים את השבועה, \u0003ואמר לו\u0004 המלך: \u0003עלבוני מחול לך, לך ופייס את חבירך. הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כאן בעבירות שבין אדם למקום\u0004 — ישא ה' פניו וימחול, \u0003כאן בעבירות שבין אדם לחבירו\u0004 — לא ישא פנים. עד שיפייס את חבירו.","זו היתה הסברה ראשונה, \u0003עד שבא ר' עקיבא ולימד,\u0004 והסביר את הסתירה באופן אחר:"],["\u0003כאן קודם גזר דין\u0004 — ישא ה' פניו, \u0003כאן לאחר גזר דין\u0004 — לא ישא פנים. ואם כן משמע שלאחר גזר דין אין עוד מקום לתשובה! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003ביחיד,\u0004 אבל ציבור נמחל להם אפילו לאחר גזר דין.","ומעירים: כי גם לגבי \u0003גזר דין\u0004 של \u0003יחיד תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: שנים שעלו למטה\u0004 מפני החולי \u0003וחוליין שוה, וכן שנים שעלו לגרדום\u0004 למקום הדין הרומי \u0003לידון ודינן שוה, זה ירד\u0004 מן המיטה והבריא \u0003וזה לא ירד, זה ניצל\u0004 מן הדין \u0003וזה לא ניצל,\u0004","\u0003מפני מה זה ירד וזה לא ירד, זה ניצל וזה לא ניצל?\u0004 כי \u0003זה\u0004 שהבריא או ניצל — \u0003התפלל\u0004 וביקש על נפשו \u0003ונענה, וזה התפלל ולא נענה.\u0004 ו\u0003מפני מה זה נענה וזה לא נענה? זה התפלל תפלה שלימה\u0004 בכל לב, ולכן \u0003נענה, וזה לא התפלל תפלה שלימה ולכן\u0004","\u0003לא נענה. ר' אלעזר אמר:\u0004 לא כן, אלא \u0003כאן\u0004 שמתפלל על נפשו \u0003קודם גזר דין\u0004 — הריהו נענה, \u0003כאן\u0004 שמתפלל \u0003לאחר גזר דין\u0004 — אינו נענה. \u0003ר' יצחק אמר: יפה צעקה לאדם בין קודם גזר דין בין לאחר גזר דין.\u0004 שאף לאחר גזר דין יכול הוא להיענות.","ושואלים מצד אחר: \u0003וגזר דין\u0004 של \u0003צבור מי מיקרע\u0004 \u0005[האם\u0006 הוא \u0005נקרע]\u0006 תמיד על ידי תשובה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כתוב אחד אומר: \"כבסי מרעה לבך\u0004 ירושלים למען תיושעי\" (ירמיה ד, יד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בכתוב אחר: \u0003\"כי אם תכבסי בנתר ותרבי לך ברית נכתם עונך לפני\"\u0004 (ירמיה ב, כב), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 צריך להבין את הסתירה בין הכתובים כך: \u0003כאן קודם גזר דין\u0004 — יש תקנה בכיבוס הלב שבתשובה, \u0003כאן לאחר גזר דין\u0004 — אף זה אינו מועיל!","ודוחים: \u0003לא, אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר \u0003לאחר גזר דין, ולא קשיא\u0004 \u0005[ואין זה קשה]:\u0006 \u0003כאן\u0004 — \u0003בגזר דין שיש עמו שבועה\u0004 שנשבע הקדוש ברוך הוא שלא יבטל דינו, שאף אם עושה תשובה אין גזר דינו מתבטל, \u0003כאן בגזר דין שאין עמו שבועה\u0004 — יש לו ביטול על ידי תשובה,","\u0003וכ\u0004פי שאמר \u0003רב שמואל בר אמי.\u0004 ש\u0003אמר רב שמואל בר אמי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב שמואל בר נחמני אמר ר' יונתן: מנין לגזר דין שיש עמו שבועה\u0004 של הקדוש ברוך הוא שלא יתבטל, \u0003שאינו נקרע\u0004 — \u0003שנאמר: \"ולכן נשבעתי לבית עלי אם יתכפר עון בית עלי בזבח ובמנחה\u0004 עד עולם\u0003\"\u0004 (שמואל א' ג, יד).","אגב פסוק זה \u0003אמר רבא: בזבח ובמנחה אינו מתכפר\u0004 — \u0003אבל מתכפר בתורה. אביי אמר: בזבח ובמנחה אינו מתכפר, אבל מתכפר\u0004 על ידי \u0003תורה וגמילות חסדים.\u0004 מסופר: \u0003רבה ואביי מדבית\u0004 \u0005[מבית,\u0006 ממשפחת\u0005]\u0006 \u0003עלי קאתו\u0004 \u0005[באו],\u0006 וקללת בית עלי היתה שמרבית בני משפחתו ימותו אנשים, כלומר, עוד בהיותם צעירים מאד. \u0003רבה\u0004 ש\u0003עסק\u0004 בעיקר \u0003בתורה חיה ארבעין שנין\u0004 \u0005[חי ארבעים שנה],\u0006 ואילו \u0003אביי\u0004 ש\u0003עסק בתורה וגמילות חסדים חיה שיתין שנין\u0004 \u0005[חי שישים שנה],\u0006 שהועיל לו הדבר לדחות יותר את גזר דינו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003משפחה אחת היתה בירושלים שהיו מתיה מתין בני שמונה עשרה שנה\u0004 ולא ידעו מה גרם להם. \u0003באו והודיעו את רבן יוחנן בן זכאי. אמר להם: שמא ממשפחת עלי אתם, דכתיב ביה\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל מרבית ביתך ימותו אנשים\"\u0004 (שמואל א' ב, לג), ואם אכן כך, תקנתכם היא — \u0003לכו ועסקו בתורה ו\u0004בזכות זאת \u0003חיו. הלכו ועסקו בתורה וחיו\u0004 יותר. \u0003והיו קורין אותה משפחת ר' יוחנן על שמו\u0004 ולכבודו.","\u0003אמר רב שמואל בר איניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: מניין לגזר דין של צבור שאינו נחתם,\u0004 ותוהים: \u0003אינו נחתם?! והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"נכתם עונך לפני\"\u0004 (ירמיה ב, כב), משמע שלעוון הציבור אין מחילה ומחיקה! \u0003אלא\u0004 כך יש לומר: \u0003אף על גב שנחתם\u0004 — \u0003נקרע\u0004 לאחר מכן ומתהפך לטובה. \u0003שנאמר: \"כה' אלהינו בכל קראנו אליו\"\u0004 (דברים ד, ז), משמע שתמיד יש דרך להתקרב לה'.","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"דרשו ה' בהמצאו קראהו בהיותו קרוב\"\u0004 (ישעיה נה, ו), משמע שיש זמן שאינו קרוב ואינו נענה!","ומשיבים: \u0003התם [שם\u0004 מדובר\u0005]\u0006 \u0003ביחיד,\u0004 שיש זמנים מיוחדים שה' קרוב אליו, \u0003הכא\u0004 \u0005[כאן\u0006 מדובר\u0005]\u0006 \u0003בצבור,\u0004 שבכל זמן שיקראוהו, הריהו קרוב. ושואלים: \u0003ביחיד אימת\u0004 הזמן שה' קרוב בו? \u0003אמר רבה בר אבוה: אלו עשרה ימים שבין ראש השנה ליום הכפורים.\u0004 נאמר: \u0003\"ויהי כעשרת הימים ויגף ה' את נבל\u0004 וימת\" (שמואל א' כה, לח), ושואלים: \u0003עשרה ימים\u0004 אלה \u0003מאי עבידתייהו\u0004 \u0005[מה מעשיהם]\u0006 כלומר, מה טיבם של עשרה ימים דווקא? \u0003אמר רב יהודה אמר רב: כנגד עשר לגימות שנתן נבל לעבדי דוד\u0004 שבאו לבקרו, שמפני הנימוס נתן לעשרת עבדי דוד לשתות דבר מה, ולכן נדחה גזר דינו בעשרה ימים. \u0003 אמר רב נחמן\u0004 בשם \u0003רבה בר אבוה: אלו עשרה ימים שבין ראש השנה ליום הכפורים,\u0004 שנותנים לכל אדם לעשות בהם תשובה.","שנינו במשנה: \u0003בראש השנה כל באי העולם עוברין לפניו כבני מרון.\u0004 ושאלו \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כבני מרון\"? הכא\u0004 \u0005[כאן\u0006 בבבל\u0005]\u0006 \u0003תרגימו\u0004 \u0005[תרגמו,\u0006 הסבירו זאת\u0005]:\u0006 \u0003כבני אמרנא\u0004 \u0005[כבני צאן],\u0006 \u0003ריש לקיש אמר: כמעלות בית מרון\u0004 ששם היה מעלה תלול וצר מאד ולא היה ברוחבו אלא כדי מעבר אדם אחד בלבד, והעומד בראש ההר היה יכול לראות את כל העולים להר במבט אחד. \u0003אמר רב יהודה אמר שמואל: כחיילות\u0004 כאנשי צבא \u0003של בית דוד\u0004 למשל, שהם נסקרים בבת אחת.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: וכולן נסקרין בסקירה אחת\u0004 (במבט אחד\u0005).\u0006 \u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 מעין זה בברייתא, שנאמר: \u0003היצר יחד לבם המבין אל כל מעשיהם\"\u0004 (תהלים לג, טו). ודנים: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 פסוק זה? \u0003אילימא הכי קאמר\u0004 \u0005[אם תאמר כך אמר]\u0006 הפסוק: \u0003דברנהו לכולי עלמא ומייחד לבייהו כהדדי\u0004 \u0005[שברא את כל העולם ומייחד את לבם זה כזה]\u0006 — \u0003והא קא חזינן דלאו הכי\u0004 \u0005[והרי אנו רואים שאין זה כך]\u0006 שהרי אין לבם של כל האנשים כאחד ואינם דומים זה לזה. \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר]:\u0006 \u0003היוצר רואה יחד\u0004 את \u0003לבם ומבין אל כל מעשיהם\u0004 בסקירה אחת.","\u0003על\u0004 קביעת וקידוש \u0003ששה חדשים\u0004 בשנה \u0003השלוחין יוצאין\u0004 מבית דין הגדול לכל מקום בארץ ובגולה להודיע מתי קדשו את החודש, ואלו הם: יוצאים \u0003על\u0004 חודש \u0003ניסן מפני הפסח\u0004 שידעו מתי לחוג אותו, \u0003על\u0004 חודש \u0003אב מפני התענית\u0004 שבתשעה באב, \u0003על אלול\u0004 יוצאים \u0003מפני ראש השנה\u0004 שחל חודש לאחר ראש חודש אלול, \u0003על תשרי\u0004 יוצאים \u0003מפני תקנת המועדות\u0004 (יום הכיפורים וסוכות), \u0003על כסליו מפני חנוכה, ועל אדר מפני הפורים.\u0004","\u0003וכשהיה בית המקדש קיים\u0004 — \u0003יוצאין\u0004 השלוחים \u0003אף על\u0004 חודש \u0003אייר מפני פסח קטן\u0004 (פסח שני) שזמנו בארבעה עשר באייר, כדי שיקריבו בו אלו שהיו בשעת הקרבת הפסח הראשון טמאים או בדרך רחוק ולא יכלו להקריבו.","שואלים: כיון שיוצאים בחודש אב מפני התענית \u0003וליפקו נמי\u0004 \u0005[ושייצאו גם כן]\u0006 על חודש \u0003תמוז ו\u0004על חודש \u0003טבת\u0004 שגם בהם יש ימי תענית ציבור!"],["שכן \u0003אמר רב חנא בר ביזנא אמר ר' שמעון חסידא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כה אמר ה' צבאות צום הרביעי וצום החמישי וצום השביעי וצום העשירי יהיה לבית יהודה לששון ולשמחה\u0004 ולמועדים טובים \u0003\"(זכריה ח, יט), קרי להו\u0004 \u0005[קורא להם]\u0006 ימי \u0003\"צום\" וקרי להו\u0004 \u0005[וקורא להם]\u0006 \u0003\"ששון ושמחה\",\u0004 כיצד? \u0003בזמן שיש שלום\u0004 בעולם — \u0003יהיו לששון ולשמחה\u0004 ואסורים יהיו במספד ובתענית, \u0003אין שלום\u0004 — יהיו אלה ימי \u0003צום.\u0004 בכל אופן מדבריו למדים כי גם הצום הרביעי והעשירי בכלל התעניות, ומדוע אם כן לא נשלחו שליחים להודיע על החודשים בהם הם חלים?","\u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להסיק מפסוק זה: \u0003בזמן שיש שלום\u0004 ובית המקדש בנוי ואין הגוים שולטים על ישראל — \u0003יהיו\u0004 הימים האלו \u0003לששון ולשמחה,\u0004 אולם אם \u0003יש שמד\u0004 (צרות על ישראל) יהיו אלה ימי \u0003צום, אין שמד ואין שלום\u0004 כשאין צרות מיוחדות ולא הגיעה נחמה ישראל, \u0003רצו\u0004 הקהל — \u0003מתענין, רצו\u0004 — \u0003אין מתענין.\u0004 וכיון שאין חובה גמורה להתענות, אין שולחים שליחים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שהדבר תלוי ברצון הציבור בלבד, \u0003תשעה באב נמי\u0004 \u0005[גם כן]\u0006 יהיה כשאר ימי הצום, שפעמים יצומו ופעמים לא יצומו, כפי רצון הציבור באותו זמן, ומדוע נאמר במשנה שעל תשעה באב יוצאים השלוחים? \u0003אמר רב פפא: שאני\u0004 \u0005[שונה]\u0006 \u0003תשעה באב, הואיל והוכפלו בו צרות.\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בתשעה באב חרב הבית ב\u0004פעם ה\u0003ראשונה וב\u0004פעם ה\u0003שניה, ו\u0004ביום זה \u0003נלכדה ביתר, ו\u0004בו \u0003נחרשה העיר\u0004 ירושלים בידי השונאים, שרצו לעשות סימן שלא תבנה עוד ולכן החמירו בו ביותר.","בענין הצומות הללו הרמוזים בדברי הנביא, נחלקו חכמים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' שמעון: ארבעה דברים היה ר' עקיבא\u0004 (רבו) \u0003דורש, ואני אין דורש כמותו,\u0004 אלא דורש באופן אחר. ואחד השינויים הוא בענין זה, וכך פירש ר' עקיבא: \u0003\"צום הרביעי\"\u0004 — זה \u0003תשעה בתמוז שבו הובקעה העיר, שנאמר: \"\u0004בחודש \u0003הרביעי בתשעה לחדש ויחזק הרעב בעיר ולא היה לחם לעם הארץ ותבקע העיר\"\u0004 (ירמיה נב, ו-ז). \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 הנביא \u0003\"\u0004צום ה\u0003רביעי\"\u0004 — מפני שהוא בתמוז, \u0003רביעי לחדשים\u0004 מניסן.","\u0003\"צום החמישי\"\u0004 — \u0003זה תשעה באב, שבו נשרף בית אלהינו. ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"\u0004צום ה\u0003חמישי\"\u0004 — כי הוא ב\u0003חמישי לחדשים. \"צום השביעי\"\u0004 — \u0003זה שלשה בתשרי שבו נהרג גדליה בן אחיקם. ומי הרגו\u0004 — \u0003ישמעאל בן נתניה הרגו, ללמדך\u0004 על ידי קביעת התענית ביום זה \u0003ששקולה מיתתן של צדיקים כשריפת בית אלהינו\u0004 שאף על כך קבעו תענית לדורות. \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 הנביא \u0003\"\u0004צום ה\u0003שביעי\"\u0004 — שהוא תשרי \u0003שביעי לחדשים.\u0004","\u0003\"צום העשירי\"\u0004 — \u0003זה עשרה בטבת שבו סמך מלך בבל על ירושלים\u0004 והתחיל לצור עליה, \u0003שנאמר: \"ויהי דבר ה' אלי בשנה התשיעית בחדש העשירי בעשור לחדש לאמר. בן אדם כתב לך את שם היום את עצם היום הזה סמך מלך בבל אל ירושלים\"\u0004 (יחזקאל כד, א-ב). \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 הנביא \u0003\"\u0004צום ה\u0003עשירי\"\u0004 — כי הוא בחודש טבת ה\u0003עשירי לחדשים. והלא היה ראוי זה לכתוב ראשון\u0004 שהרי תחילת המצור על העיר היא ראשונה לכל המאורעות האחרים \u0003ולמה נכתב כאן\u0004 בסוף הרשימה — \u0003כדי להסדיר חדשים כתיקנן\u0004 שמתחיל ברביעי ומסיים בעשירי, אלו דברי ר' עקיבא.","ואמר ר' שמעון: \u0003ואני איני אומר כן, אלא: \"צום העשירי\"\u0004 — \u0003זה חמשה בטבת שבו באת שמועה לגולה שהוכתה העיר, שנאמר: \"ויהי בשתי עשרה שנה בעשרי בחמשה לחדש לגלותנו בא אלי הפליט מירושלים לאמר הכתה העיר\"\u0004 (יחזקאל לג, כא) \u0003ועשו\u0004 אבל ב\u0003יום שמועה\u0004 על החורבן \u0003כיום שריפה\u0004 שלו.","והוסיף ר' שמעון: \u0003ונראין דברי מדבריו, שאני\u0004 לפי שיטתי \u0003אומר על ראשון ראשון ועל אחרון אחרון,\u0004 שלדעת ר' שמעון הצומות מנויים לפי סדר המאורעות, \u0003והוא\u0004 ר' עקיבא, רבי, \u0003אומר על ראשון אחרון ועל אחרון ראשון. אלא שהוא מונה לסדר החדשים\u0004 ואינו מתחשב במאורעות עצמם \u0003ואני מונה\u0004 אף \u0003לסדר\u0004 ה\u0003פורעניות.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בשאלה הבאה. \u0003רב ור' חנינא אמרי\u0004 \u0005[אומרים]\u0006 שניהם: \u0003בטלה מגילת תענית,\u0004 שכל הימים המיוחדים שנקבעו כימי שמחה ומנויים במגילת תענית — כולם בטלו לאחר החורבן, והותרו בהם ההספד והתענית. שבזמן הגלות אין טעם לחוג לזכר מאורעות שמחה שהיו במשך הדורות. \u0003ר' יוחנן ור' יהושע בן לוי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא בטלה מגילת תענית.\u0004","ומסבירים: \u0003רב ור' חנינא אמרי\u0004 \u0005[אומרים]\u0006 ש\u0003בטלה מגילת תענית, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 כיון שאמר הנביא \u0003בזמן שיש שלום\u0004 — \u0003יהיו\u0004 ימי הצום \u0003לששון ולשמחה, אין שלום\u0004 — יהיו אלה ימי \u0003צום. והנך נמי כי הני\u0004 \u0005[ואלה גם כן כמו אלה],\u0006 כלומר, ימי השמחה המנויים במגילת תענית גם הם בטלים בזמן שאין שלום.","\u0003ר' יוחנן ור' יהושע בן לוי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא בטלה מגילת תענית,\u0004 וטעמם: \u0003הני הוא\u0004 \u0005[אלה הם]\u0006 ימי הצום הכתובים במקרא \u0003דתלינהו רחמנא\u0004 \u0005[שתלתה אותם התורה]\u0006 \u0003בבנין בית המקדש, אבל הנך\u0004 \u0005[אלה]\u0006 ימי החג שבמגילת תענית — \u0003כדקיימי קיימי\u0004 \u0005[כפי שהם עומדים, הם עומדים]\u0006 ולא בטלו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא\u0004 לשיטת רב ור' חנינא. שנינו: \u0003מעשה וגזרו\u0004 חכמים \u0003תענית בחנוכה בלוד, וירד ר' אליעזר\u0004 באותו יום \u0003ורחץ\u0004 במרחץ להראות שאינו מקבל תענית זו. \u0003ור' יהושע\u0004 ירד \u0003וסיפר\u0004 שערותיו. ולא עוד, אלא \u0003אמרו להם\u0004 שני חכמים אלה: \u0003צאו והתענו\u0004 לאות חרטה ותשובה \u0003על מה שהתעניתם.\u0004 לפי שימי החנוכה הם ימי שמחה ואסור להתענות בהם. והרי חנוכה היא מן הימים שנקבעו במגילת תענית, מכאן שאף לאחר חורבן הבית ממשיכים לחוג את ימי החנוכה, הרי שלא בטלה מגילת תענית!","\u0003אמר ר' יוסף: שאני\u0004 \u0005[שונה]\u0006 \u0003חנוכה דאיכא\u0004 \u0005[שיש]\u0006 בה \u0003מצוה\u0004 של הדלקת נרות. ולכן לא בטל חג זה. ובניגוד לשאר ימים שבמגילת תענית. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 ומה טיבה של ראיה זו? \u0003ותיבטיל איהי\u0004 \u0005[שתבטל היא\u0006 חנוכה עצמה\u0005]\u0006 \u0003ותיבטל\u0004 גם \u0003מצותה\u0004 בהדלקת נרות!","\u0003אלא אמר רב יוסף\u0004 יש לחזור מההסבר הקודם, ולומר כי \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חנוכה דמיפרסם ניסא\u0004 \u0005[שמפורסם\u0006 הוא \u0005הנס\u0006 שלה\u0005],\u0006 כיון שנתפרסם ונתקבל בכל ישראל כיום של שמחה אין לבטל אותו.","\u0003מותיב\u0004 \u0005[מקשה]\u0006 \u0003רב אחא בר הונא:\u0004 נאמר במגילת תענית \u0003בתלתא\u0004 \u0005[בשלושה]\u0006 \u0003בתשרי\u0004 יום שמחה הוא כי בו \u0003בטילת אדכרתא מן שטריא\u0004 \u0005[בטלה אזכרת\u0006 שם שמים \u0005מן השטרות].\u0006 ומבואר שם, \u0003שגזרה מלכות יון גזרה\u0004 על היהודים, \u0003שלא להזכיר שם שמים על פיהם, וכשגברה מלכות חשמונאי ונצחום התקינו שיהו מזכירין שם שמים אפילו בשטרות. וכך היו כותבים: בשנת כך וכך ליוחנן כהן גדול לאל עליון.\u0004","\u0003וכששמעו חכמים בדבר אמרו: למחר זה\u0004 בעל החוב \u0003פורע את חובו\u0004 ואז אין צורך עוד בשטר \u0003ונמצא שטר מוטל באשפה,\u0004 ושם שמים הכתוב בו מתבזה, \u0003וביטלום\u0004 לתקנת הזכרת שם שמים בשטרות, \u0003ואותו היום\u0004 שביטלו \u0003עשאוהו יום טוב. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003בטלה מגילת תענית,\u0004 וכי \u0003קמייתא בטול אחרנייתא\u0004 \u0005[את\u0006 התקנות \u0005הראשונות מבטלים ואחרונות\u0006 תקנות חדשות\u0005]\u0006 \u0003מוסיפין?\u0004","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003בזמן שבית המקדש קיים\u0004 ואז נשמרו כל הימים המנויים במגילת תענית. ואף הוסיפו מפעם לפעם ימי זכרון נוספים. ומה שאמרנו שבטלה — זה לאחר החורבן."],["ומקשים: אם היה זה בזמן שבית המקדש היה קיים \u0003ותיפוק ליה\u0004 \u0005[ויצא לו]\u0006 דין זה שהוא יום שמחה מטעם אחר כי \u0003דהוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003יום שנהרג בו גדליה בן אחיקם,\u0004 והרי אמרנו שבזמן בית המקדש עשו את ימי הצום לימי שמחה! \u0003אמר רב: לא נצרכה\u0004 תקנה זו של שמחה בשלישי בתשרי \u0003אלא לאסור את\u0004 יום \u0003שלפניו.\u0004 כי ימי השמחה הקבועים לחגים במגילת תענית לא רק הם עצמם אסורים בתענית אלא גם היום שלפניהם ושלאחריהם, ודין זה לא היה קיים קודם, גם כאשר בטל צום גדליה.","ומקשים: \u0003שלפניו נמי\u0004 \u0005[גם כן],\u0006 \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו ממקום אחר \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003יום שלאחר ראש חדש,\u0004 ואמרנו שיום אחד לפני כל חג ואחרי כל חג אין מתענים בו! ודוחים: \u0003ראש חדש דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא \u0003ודאורייתא לא בעי\u0004 \u0005[\u0006וחגים \u0005מן התורה אינם צריכים]\u0006 \u0003חיזוק\u0004 ולכן לא קבעו בהם תקנה שגם בימים שלפניהם ולאחריהם אסור יהיה להתענות.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הימים האלה הכתובין במגילת תענית אסורין\u0004 בתענית, \u0003בין לפניהם בין לאחריהן.\u0004 ואילו \u0003שבתות וימים טובים\u0004 — \u0003הם\u0004 עצמם \u0003אסורים\u0004 בתענית, \u0003לפניהן ולאחריהן מותרין. מה הפרש בין זה לזה? הללו,\u0004 שבתות וימים טובים, חיובם הוא מ\u0003דברי תורה, ואין דברי תורה צריכין חיזוק\u0004 ולכן גם אם יהיה יום צום לפניהם או אחריהם — יום החג עצמו לא ייבטל, ואילו \u0003הללו דברי סופרים, ודברי סופרים צריכין חיזוק.\u0004","ומקשים שוב: \u0003ותיפוק ליה\u0004 \u0005[ושתצא לו]\u0006 הלכה זו לגבי איסור תענית בשני בתשרי משום \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003יום שלפני יום שנהרג בו גדליה בן אחיקם,\u0004 וכיון שנקבע יום זה ליום שמחה, הרי גם ביום שלפניו אסור להתענות! \u0003אמר רב אשי:\u0004 צום \u0003גדליה בן אחיקם דברי קבלה\u0004 (דבר האמור בדברי הנביאים) \u0003הוא, ודברי קבלה כדברי תורה דמו\u0004 \u0005[נחשבים]\u0006 לענין זה, שאף הם אינם צריכים חיזוק.","ועוד \u0003מתיב [מקשה] רב טובי בר מתנה,\u0004 על ההנחה שבטלה מגילת תענית, שבמגילה זו נאמר: \u0003בעשרים ותמניא ביה אתת בשורתא טבתא ליהודאי דלא יעידון מאורייתא\u0004 \u0005[בעשרים ושמונה בו\u0006 באדר \u0005באה בשורה טובה ליהודים שלא יסורו מן התורה]\u0006 ומסופר הענין במגילת תענית: \u0003שגזרה מלכות הרשעה גזרה שלא יעסקו בתורה, ושלא ימולו את בניהם, ושיחללו שבתות. מה עשה יהודה בן שמוע וחביריו? הלכו ונטלו עצה ממטרוניתא\u0004 \u0005[גבירה]\u0006 \u0003אחת שכל גדולי רומי מצויין אצלה\u0004 וסביר להניח כי תדע כיצד לבטל גזירה זו.","\u0003אמרה להם\u0004 כעצה: \u0003בואו והפגינו\u0004 (צעקו) \u0003בלילה\u0004 ואז ישמעו השרים את דבריכם, ויבטלו את הגזירה. \u0003הלכו והפגינו בלילה, אמרו: אי\u0004 (אוי) \u0003שמים! לא אחיכם אנחנו, ולא בני אב אחד אנחנו, ולא בני אם אחת אנחנו\u0004 היהודים כמותכם? \u0003מה נשתנינו מכל אומה ולשון שאתם גוזרין עלינו גזירות קשות? וביטלום\u0004 לגזירות אלה. \u0003ואותו היום\u0004 שביטלום \u0003עשאוהו\u0004 חכמים \u0003יום טוב. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003בטלה מגילת תענית,\u0004 אם כן תמוה: \u0003קמייתא בטול\u0004 \u0005[\u0006את התקנות \u0005הראשונות ביטלו],\u0006 \u0003אחרנייתא\u0004 \u0005[האחרונות]\u0006 \u0003מוסיפין?!\u0004","\u0003וכי תימא הכא נמי\u0004 \u0005[ואם תאמר כאן גם כן]\u0006 מדובר \u0003בזמן שבית המקדש קיים\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 \u0003יהודה בן שמוע תלמידו של ר' מאיר, ור' מאיר בתר הכי\u0004 \u0005[אחר כך]\u0006 אחר זמן החורבן \u0003הוה\u0004 \u0005[היה]!\u0006 וראיה שהוא מאוחר, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלי זכוכית ש\u0004נטמאו ואחר כך \u0003ניקבו\u0004 כדי לטהרן מטומאתן \u0003והטיף לתוכן אבר\u0004 (עופרת) כדי לחבר את השברים — נחלקו בכך אם עתה נחשב כלי זה לכלי מתכת שדינו הוא שמשנסתם הנקב שבו, הריהו חוזר לטומאתו הראשונה אף על פי שלא נגע בטומאה בשנית, או שמא עדיין הוא בכלל כלי זכוכית שמשניקבו שוב אינם חוזרים לטומאתם הראשונה לעולם. \u0003אמר רבן שמעון בן גמליאל: יהודה בן שמוע מטמא משום\u0004 (בשם) \u0003ר' מאיר,\u0004"],["\u0003וחכמים מטהרין\u0004 שלדעתם, כיון שבעיקרו הוא כלי זכוכית, אין ביציקת העופרת כדי להחשיבו ככלי מתכת. וכיון שר' מאיר עצמו היה כמה דורות לאחר החורבן, ועדיין תיקן ר' יהודה בן שמוע תלמידו ימי שמחה. אם כן ברור שלא בטלה מגילת תענית.","ומסכמים \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 אם בטלה, או לא בטלה המגילה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: הימים האלו הכתובין במגילת תענית, בין בזמן שבית המקדש קיים בין בזמן שאין בית המקדש קיים\u0004 — \u0003אסורין\u0004 בתענית ובהספד, אלו \u0003דברי ר' מאיר. ר' יוסי אומר: בזמן שבית המקדש קיים\u0004 — \u0003אסורין, מפני ששמחה היא להם. אין בית המקדש קיים\u0004 — \u0003מותרין, מפני שאבל הוא להם.\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא כי \u0003בטלו\u0004 הימים, ועוד אמרו \u0003והלכתא\u0004 \u0005[וההלכה]\u0006 היא ש\u0003לא בטלו\u0004 הימים. ותוהים: \u0003קשיא הלכתא אהלכתא\u0004 \u0005[קשה מהלכה על הלכה]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 כי \u0003כאן בחנוכה ופורים\u0004 — לא בטלו חגים אלה, אף שחנוכה היא מהימים הכלולים במגילת תענית. \u0003כאן בשאר יומי\u0004 \u0005[בשאר ימים]\u0006 הכתובים בה — כולם בטלו.","שנינו במשנה כי יוצאים השליחים ומודיעים \u0003על\u0004 קידוש חודש \u0003אלול מפני ראש השנה, ו\u0004יוצאים \u0003על\u0004 חודש \u0003תשרי מפני תקנת המועדות.\u0004 ושואלים: \u0003כיון דנפקי להו\u0004 \u0005[שהם יוצאים]\u0006 על חודש \u0003אלול\u0004 ומודיעים מתי היה ראש החודש, על חודש \u0003תשרי למה להו\u0004 \u0005[להם]\u0006 להודיע? הרי יודעים אנו כי ראש חודש תשרי חל ביום השלושים לאחר ראש חודש אלול.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שיש להודיע שנית \u0003דלמא עברוה\u0004 \u0005[שמא עיברו]\u0006 את חודש \u0003אלול\u0004 וראש השנה יחול רק ביום השלושים ואחד אחר ראש חודש אלול, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חיננא בר כהנא אמר רב: מימות עזרא ואילך לא מצינן\u0004 \u0005[מצאנו]\u0006 שיהא חודש \u0003אלול מעובר,\u0004 ואם כן אפשר בקלות לחשב את ימי המועדים שבתשרי, ואין צורך איפוא להודיע בשנית!","ומשיבים: מה שאמרו \u0003\"לא מצינו\"\u0004 אין משמעו שאין לעשות אלול מעובר — אלא כך היה מעשה ש\u0003לא אצטריך\u0004 \u0005[הוצרכו]\u0006 לעשות, \u0003הא אצטריך\u0004 \u0005[הרי\u0006 אם \u0005הצטרכו]\u0006 — \u0003מעברינן ליה\u0004 \u0005[מעברים אותו],\u0006 ומתוך שקיימת אפשרות שיתעבר חודש אלול, אף שהיא רחוקה, לפיכך יש סיבה לשלוח שלוחים בשנית כדי להודיע על זמנו של חודש תשרי\u0005.\u0006","ושואלים: \u0003אם יעשו כן הא מיקלקל\u0004 \u0005[הרי מתקלקל]\u0006 \u0003ראש השנה,\u0004 שהרי כל אלה שהודיעו להם על מועד ראש חודש אלול יחוגו את ראש השנה ביום השלושים לאלול, בעוד שזמנו האמיתי הוא ביום השלושים ואחד! ומשיבים: \u0003מוטב תיקלקל ראש השנה ולא יתקלקלו כולהו\u0004 \u0005[כל]\u0006 ה\u0003מועדות\u0004 — יום הכיפורים, סוכות ושמיני עצרת הבאים אחר כך.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 שיוצאים שלוחים להודיע \u0003על\u0004 חודש \u0003תשרי מפני תקנת המועדות, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שזוהי אכן הסיבה והטעם לכך.","שנינו במשנה שיוצאים \u0003על כסליו מפני חנוכה, ועל אדר מפני הפורים.\u0004 ומעירים: \u0003ואילו\u0004 אם \u0003נתעברה השנה\u0004 ש\u0003יוצאין\u0004 שלוחים להודיע \u0003אף על אדר שני מפני הפורים\u0004 שחל אז באדר השני — \u0003לא קתני\u0004 \u0005[שנינו].\u0006 משמע כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005],\u0006 \u0003רבי אומר: אם נתעברה השנה\u0004 — \u0003יוצאין אף על אדר השני מפני הפורים.\u0004","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 שבענין עקרוני \u0005זה נחלקו]:\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 התנא של משנתנו\u0005]\u0006 \u0003סבר,\u0004 כי \u0003כל מצות הנוהגות בשני\u0004 שעיקרן קריאת הפרשות המיוחדות בתורה, ופורים \u0003נוהגות בראשון\u0004 ואם קיימו אותן בראשון ולא בשני — יצאו ידי חובה. \u0003ומר\u0004 \u0005[וחכם זה],\u0006 רבי \u0003סבר\u0004 כי \u0003כל מצות הנוהגות בשני\u0004 — \u0003אין נוהגות בראשון,\u0004 ולכן צריך להודיע גם על השני כדי לקיים בו את מצוות חודש אדר.","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מצות הנוהגות בשני\u0004 — \u0003אין נוהגות בראשון, והכא\u0004 \u0005[וכאן]\u0006 \u0003בעיבור שנה קמיפלגי\u0004 \u0005[חלוקים]\u0006 הם, מה שיעורו של חודש העיבור. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: כמה עיבור שנה\u0004 — \u0003שלשים יום, רבן שמעון בן גמליאל אומר: חדש.\u0004 וכיון שלדעת רבן שמעון בן גמליאל אין קביעות במספר ימי חודש העיבור — צריך להודיע גם מתי יחול חג הפורים.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שלשים יום דידעי\u0004 \u0005[\u0006שאנשים \u0005יודעים]\u0006 ומוסיפים שלושים יום, ויודעים לחשב מתי יחול פורים. \u0003חדש נמי ידעי\u0004 \u0005[גם כן יודעים]\u0006 הם, שהוא עשרים ותשעה יום. ומחשבים מתי פורים! \u0003אמר רב פפא: מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שמוסיפים \u0003חדש,\u0004 לאו דווקא חודש (בן עשרים ותשעה יום) אלא: \u0003רצה\u0004 — \u0003חדש, רצה\u0004 — \u0003שלשים\u0004 ולכן צריך להודיע כיצד קבעו.","\u0003העיד ר' יהושע בן לוי משום קהלא קדישא דירושלים\u0004 \u0005[בשם הקהל הקדוש\u0006 של \u0005בירושלים]\u0006 \u0003על שני אדרים שמקדשין אותם ביום עיבוריהן,\u0004 כלומר, ביום השלושים לחודש הקודם.","ומעירים: \u0003למימרא\u0004 \u0005[\u0006דבר זה בא \u0005לומר]:\u0006 שחודשים \u0003חסרין עבדינן\u0004 \u0005[עושים אנו]\u0006 את שני האדרים\u0005,\u0006 אולם חודשים \u0003מלאין לא עבדינן\u0004 \u0005[עושים אנו]\u0006 אותם, שיהיו בני שלושים יום! ו\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004מה ש\u0003דרש רב נחמן בר חסדא,\u0004 שאמר: \u0003העיד ר' סימאי משום חגי זכריה ומלאכי על שני אדרים\u0004 שבשנה מעוברת, \u0003שאם רצו לעשותן שניהן מליאין\u0004 — \u0003עושין, שניהן חסרין\u0004 — \u0003עושין, אחד מלא ואחד חסר\u0004 — \u0003עושין, וכך היו נוהגין בגולה,\u0004 שכאשר לא ידעו את המועד שנקבע בבית דין כך היו עושים. \u0003ומשום רבינו\u0004 (רב) \u0003אמרו: לעלם\u0004 נוהגים \u0003אחד מלא ואחד חסר\u0004 בשני אדרים, \u0003עד שיוודע לך שהוקבע ראש חדש בזמנו,\u0004 כלומר, שגם אדר ראשון הוא חסר.","\u0003שלחו ליה\u0004 \u0005[לו]\u0006 \u0003למר עוקבא\u0004 ראש הגולה מכתב מארץ ישראל: \u0003אדר הסמוך לניסן\u0004 — \u0003לעולם\u0004 הוא חודש \u0003חסר\u0004 בן עשרים ותשעה יום, בין בשנה פשוטה בין בשנה מעוברת, אולם אדר הראשון שאינו סמוך לניסן לפעמים הוא מלא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן,\u0004 ממה ששנינו: \u0003על שני חדשים מחללין את השבת\u0004 שמותר לעדים לחלל את השבת כדי להגיע בזמן למקום בית הדין — \u0003על\u0004 חודש \u0003ניסן ועל תשרי\u0004 מפני המועדים החשובים שבהם. \u0003אי אמרת בשלמא\u0004 \u0005[נניח\u0006 אם \u0005אומר אתה]\u0006 שחודש אדר \u0003זמנין\u0004 \u0005[פעמים]\u0006 \u0003מלא זמנין\u0004 \u0005[פעמים]\u0006 \u0003חסר\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מחללינן\u0004 \u0005[מחללים אנו],\u0006 שצריך להודיע מתי ראש חודש ניסן, כדי שידעו לעשות את הפסח בזמנו."],["\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שחודש אדר \u0003לעולם חסר, אמאי מחללינן\u0004 \u0005[מדוע מחללים אנו]\u0006 את השבת? הרי יודעים מראש מתי בדיוק יחול ראש חודש ניסן! ומשיבים: \u0003משום\u0004 ש\u0003מצוה לקדש\u0004 את החודש \u0003על\u0004 פי \u0003הראייה\u0004 ולא לסמוך רק על החשבון והתקנות.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 לא בנוסח זה, אלא \u0003אמר רב נחמן: אף אנן נמי תנינא\u0004 \u0005[אנחנו גם כן שנינו]\u0006 סיוע לדברים ששלחו למר עוקבא, שכן שנינו: \u0003על שני חדשים מחללין את השבת\u0004 — \u0003על ניסן ועל תשרי. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003לעולם\u0004 עושים את אדר הסמוך לניסן \u0003חסר\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מחללינן\u0004 \u0005[מחללים אנו]\u0006 את השבת משום ש\u0003מצוה לקדש על הראייה.\u0004","\u0003אלא אי אמרת זמנין\u0004 \u0005[אם אומר אתה\u0006 ש\u0005לפעמים]\u0006 הוא \u0003מלא זמנין\u0004 \u0005[\u0006ו\u0005לפעמים]\u0006 הוא \u0003חסר\u0004 ואין קביעות בדבר — \u0003אמאי מחללינן\u0004 \u0005[מדוע מחללים אנו]?\u0006 \u0003נעבריה האידנא\u0004 \u0005[נעבר אותו היום],\u0006 כלומר, לא יקבעו ראש חודש וישאר אדר מעובר (בן שלושים יום) \u0003ונקדשיה\u0004 \u0005[ויקדשוהו]\u0006 \u0003למחר,\u0004 וכיון שאין עושים כן, אלא מחללים את השבת כדי לקבוע את החודש על פי הראייה, הרי זו הוכחה שמצוה לקדש על פי הראייה דווקא.","ודוחים: \u0003אי דאקלע\u0004 \u0005[אם\u0006 היה מקרה \u0005שהזדמן]\u0006 \u0003יום שלשים\u0004 עצמו \u0003בשבת הכי נמי\u0004 \u0005[כך גם כן]\u0006 עושים, שאם נראה הירח בשבת ביום שלושים — אין מחללים את השבת להעיד ומעברים את חודש אדר, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 במקרה \u0003דאקלע\u0004 \u0005[שהזדמן]\u0006 ש\u0003יום\u0004 ה\u0003שלשים ואחד\u0004 הוא \u0003בשבת\u0004 וראו אז את הירח, שהכרח הוא לקדש את ראש החודש ביום שבת, שהרי אין חודש יותר משלושים יום ואי אפשר לדחות את קידושו, וזאת משום ש\u0003מצוה לקדש על הראייה\u0004 ולעשות זאת על פי העדים.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב כהנא,\u0004 שנינו: \u0003כשהמקדש קיים מחללין\u0004 את השבת לצורך קידוש החודש, \u0003אף על כולן\u0004 (על כל החודשים), \u0003מפני תקנת הקרבן\u0004 שיקריבו את קרבן ראש החודש בזמנו.","\u0003מדכולהו לאו\u0004 \u0005[מ\u0006כיון \u0005שבכולם\u0006 מחללים את השבת \u0005לא]\u0006 \u0003משום\u0004 ש\u0003מצוה לקדש על הראייה,\u0004 אלא מפני טעם אחר — משמע ש\u0003ניסן ותשרי נמי\u0004 \u0005[גם כן]\u0006 \u0003לאו משום\u0004 ש\u0003מצוה לקדש על הראייה.\u0004","ולכן, \u0003אי אמרת בשלמא\u0004 \u0005[נניח\u0006 אם \u0005אומר אתה]\u0006 \u0003זמנין\u0004 \u0005[פעמים]\u0006 שחודש אדר \u0003מלא וזמנין\u0004 \u0005[ופעמים]\u0006 שהוא \u0003חסר, משום הכי\u0004 \u0005[כך]\u0006 \u0003מחללינן\u0004 \u0005[מחללים אנו],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי חודש אדר \u0003לעולם חסר,\u0004 אם כן \u0003אמאי מחללינן\u0004 \u0005[מדוע מחללים אנו]?\u0006 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא, ונדחו דברי רב נחמן.","ומוסרים שפעם אחת \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא, אמר:\u0004 בשנה זו \u0003עברוה\u0004 \u0005[עיברו]\u0006 את חודש \u0003אלול\u0004 והיה בן שלושים יום. \u0003אמר עולא: ידעי חברין בבלאי מאי טיבותא עבדינן בהדיהו\u0004 \u0005[\u0006האם \u0005יודעים חברינו הבבליים מה טובה עשינו איתם]\u0006 על ידי כך, שדחו את ראש השנה ביום אחד ואין יום הכיפורים חל סמוך לשבת.","ושואלים: \u0003מאי טיבותא\u0004 \u0005[מה הטובה]\u0006 שיש בדבר? \u0003עולא אמר: משום ירקיא\u0004 \u0005[הירקות]\u0006 שלא יתייבשו במהלך שני ימי השבתון. \u0003ר' אחא בר חנינא אמר: משום מתיא\u0004 \u0005[המתים],\u0006 שאם מת אדם ביום שבתון חמור אחד (כשבת) יצטרכו לדחות את קבורתו עד מוצאי יום הכיפורים, ויש חשש שמא יסריח.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה, אם זה או זה הוא הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל הלכה למעשה בדבר זה: \u0003יום הכפורים שחל להיות אחר השבת\u0004 ולא ביום שישי. \u0003מאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום מתיא\u0004 \u0005[המתים]\u0006 \u0003מעברינן\u0004 \u0005[מעברים אנו],\u0006 שלענין זה אין הבדל אם יום הכיפורים הוא לפני השבת או אחרי השבת. אולם \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהטעם הוא \u0003משום ירקיא\u0004 \u0005[הירקות],\u0006 שלא יכמשו — אין צריך לעבר, כי \u0003לאימת קא בעי להו\u0004 \u0005[למתי הוא צריך אותם\u0006 את הירקות\u0005]\u0006 — \u0003לאורתא\u0004 \u0005[לערב]\u0006 שלאחר יום הכיפורים, ואם חל ביום ראשון, הרי \u0003לאורתא טרח ומייתי\u0004 \u0005[לערב\u0006 הוא יכול \u0005לטרוח ולהביא]\u0006 מן השדה ירקות טריים.","ואומרים: \u0003ולמאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום ירקיא\u0004 \u0005[הירקות],\u0006 \u0003לעבריה\u0004 \u0005[שיעברו אותו]\u0006 \u0003משום מתיא\u0004 \u0005[המתים],\u0006 שהרי גם זה הוא שיקול חשוב! \u0003אלא,\u0004 לכל הדעות שני הטעמים תופסים, ויש להסביר באופן אחר: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לא לגבי יום הכיפורים אלא לגבי \u0003יום טוב\u0004 של ראש השנה \u0003הסמוך לשבת בין מלפניה בין מלאחריה.\u0004 כיצד? \u0003מאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום ירקיא\u0004 \u0005[הירקות]\u0006 \u0003מעברינן\u0004 \u0005[מעברים אנו]\u0006 \u0003ומאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום מתיא\u0004 \u0005[המתים],\u0006 הרי \u0003אפשר בעממי\u0004 \u0005[אפשר ב\u0006בני \u0005העמים,\u0006 בגויים\u0005]\u0006 שהרי מותר לקבור את המת ביום טוב על ידי גויים.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 שהטעם הוא \u0003משום מתיא\u0004 \u0005[המתים],\u0006 \u0003לעבריה\u0004 \u0005[שיעברו אותו]\u0006 גם \u0003משום ירקיא\u0004 \u0005[הירקות]!\u0006 ומשיבים: לדעתו אין הדבר חשוב כל כך, כי \u0003אפשר\u0004 להשרותם \u0003בחמימי\u0004 \u0005[בחמים]\u0006 ואז יהיו ראויים לאכילה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם זה]\u0006 הטעם, יכולים לשאול בני בבל: \u0003מאי שנא לדידן\u0004 \u0005[מה שונה לנו]\u0006 שעשו בכך טובה לנו, הלא \u0003אפילו לדידהו נמי\u0004 \u0005[להם גם כן]\u0006 הרי זאת טובה\u0005!\u0006 ומשיבים: \u0003לדידן חביל לן עלמא\u0004 \u0005[לנו\u0006 בבבל \u0005חם לנו העולם],\u0006 וכיון שהחום מרובה יותר הכל מתקלקל מהר יותר, \u0003לדידהו לא חביל להו עלמא\u0004 \u0005[להם,\u0006 לבני ארץ ישראל \u0005אין העולם חם להם],\u0006 כלומר, אין מזג האויר חם כל כך, ובשל שני הטעמים אינם מוכרחים לעבר.","בדברים שנאמרו עד כה הוזכר שמטעמים שונים מעברים את החודש, ושואלים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רבה בר שמואל: יכול כשם שמעברין את השנה לצורך,\u0004 שהרי בעיבור השנה מביאים בחשבון שיקולים שונים, וביניהם צרכי החג וצרכי הציבור, \u0003כך מעברין את החדש לצורך? תלמוד לומר: \"החדש הזה לכם ראש חדשים\"\u0004 (שמות יב, ב), לומר: \u0003כזה ראה וקדש.\u0004 לומר לנו, שכאשר רואים את הירח במולדו (\"כזה\") — מקדשים!","\u0003אמר רבא: לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן\u0004 — \u0003לעברו\u0004 ולדחות את ראש החודש הבא — מותר, כאן — \u0003לקדשו. והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003יכול כשם שמעברין את השנה ואת החדש לצורך כך מקדשין את החדש לצורך\u0004 ומכריזים ומקדשים את החודש ביום שלושים עוד לפני ראיית הירח החדש? \u0003תלמוד לומר \"החדש הזה לכם\"\u0004 — \u0003כזה ראה\u0004 ורק אחר כך \u0003קדש.\u0004","\u0003וכי הא\u0004 \u0005[וכמו זו]\u0006 ש\u0003אמר ר' יהושע בן לוי: מאיימין על העדים על החדש שנראה בזמנו,\u0004 שחוקרים אותם חקירה קשה עד שהם מתבלבלים ואין עדותם מתקבלת כדי \u0003לעברו\u0004 את החודש הזה מפני הצורך. \u0003ואין מאיימין על העדים על החדש שלא נראה בזמנו\u0004 כדי שיוכלו בסופו של דבר \u0003לקדשו\u0004 בזמנו, אלא אין מקדשים אלא על פי הראייה.","ותוהים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]?!\u0006 \u0003והא שלח ליה\u0004 \u0005[והרי שלח לו]\u0006 \u0003ר' יהודה נשיאה\u0004 (נשיא הסנהדרין) \u0003לר' אמי: הוו יודעין שכל ימיו של ר' יוחנן היה מלמדנו: מאיימין על העדים על החדש שלא נראה בזמנו לקדשו, אף על פי שלא ראוהו\u0004 — \u0003יאמרו \"ראינו\"!\u0004","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 \u0003בניסן ותשרי\u0004 כיון שהמועדים תלויים בהם ויש להתחשב גם בימים בהם נקבעים המועדים — מקדשים אותם לצורך, \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בשאר ירחי\u0004 \u0005[חודשים],\u0006 אין מקדשים אפילו לצורך.","\u0003רבא אמר: הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003רבה בר שמואל\u0004 שאין מעברים ומקדשים חודש לצורך — הוא לדעת \u0003אחרים היא. דתניא\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: אין בין עצרת לעצרת,\u0004 בין חג שבועות שבשנה אחת לחג שבועות שבשנה שנייה, \u0003ואין בין ראש השנה לראש השנה אלא ארבעה ימים בלבד,\u0004 שאת החודשים קובעים חודש מלא וחודש חסר כסדרם תמיד, ולכן סך כל העודף של ימות השבוע משנה לשנה מצטבר כדי ארבעה ימים בלבד. \u0003ואם היתה שנה מעוברת\u0004 שנתווסף עוד יום אחד (בגלל חודש אדר הנוסף) הרי הם \u0003חמשה\u0004 ימים של הבדל.","\u0003רב דימי מנהרדעא מתני איפכא\u0004 \u0005[היה שונה להיפך]:\u0006 \u0003מאיימין על העדים על החדש שלא נראה בזמנו\u0004 כדי \u0003לקדשו, ואין מאיימין על העדים על החדש שנראה בזמנו\u0004 כדי שלא יעידו, ואפשר יהיה \u0003לעברו.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של רב דימי — שלכאורה קשה וחמור יותר לאיים על העדים להעיד על דבר שלא ראו, מאשר לגרום להם להעיד על דבר שראו,"],["\u0003האי מיחזי כשקרא\u0004 \u0005[זה,\u0006 כשמאחרים ומעכבים \u0005נראה כשקר]\u0006 שאם לא קידשו את החודש בזמנו, הרי רבים רואים את הירח ותוהים מדוע לא קידשו קודם. \u0003האי לא מיחזי כשקרא\u0004 \u0005[וזה\u0006 כשמקדימים \u0005אינו נראה כשקר]\u0006 שהרי תולים הם את אי ראייתם בכך שאף שהם עצמם לא ראו, מכל מקום אנשים אחרים ראו את מולד הירח החודש והשאר לא ראוהו.","\u0003אמר שמואל: יכילנא לתקוני לכולה\u0004 \u0005[יכול אני לתקן\u0006 לוח שנה \u0005לכל]\u0006 ה\u0003גולה\u0004 (כי בקי היה היטב במהלך הכוכבים ובעקרונות החישוב והעיבור, והיה יכול לחשב הכל).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' שמלאי לשמואל: ידע מר האי מילתא דתניא\u0004 \u0005[\u0006האם \u0005יודע אדוני\u0006 מה פירוש \u0005הדבר הזה ששנינו\u0006 בברייתא\u0005]\u0006 של \u0003סוד העיבור,\u0004 העוסקת בעקרונות חישובי המועדות: \u0003נולד קודם חצות או נולד אחר חצות? אמר ליה\u0004 \u0005[לו]\u0006 \u0003: לא,\u0004 אין אני יודע. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מדהא לא ידע מר\u0004 \u0005[מכיון ש\u0006את \u0005זה אין אדוני יודע]\u0006 — \u0003איכא מילי אחרנייתא דלא ידע מר\u0004 \u0005[יש\u0006 עוד \u0005דברים אחרים שאין אדוני יודע],\u0006 וכיון שכך — אין לסמוך על החשבונות הנעשים בלי שכל הנושא כולו ידוע וברור לעורך החשבון בכל פרטיו.","לגופה של אותה ברייתא סתומה, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל מבבל, \u0003שלח להו\u0004 \u0005[להם]\u0006 במכתב לחביריו בבבל: \u0003צריך שיהא לילה ויום מן החדש,\u0004 כלומר, כדי שאפשר יהיה לקדש את החודש צריך שיהא מולדו ביום הקודם, כך שיהיה לילה ויום של החודש הבא לאחר שכבר נראה מולד הירח החדש,","\u0003וזו שאמר אבא אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' שמלאי\u0004 לפני שמואל ולא ידע שמואל לפרש את החילוק בין נולד לפני חצות לנולד אחר חצות — אני אפרשה, וכך יש להבין: כלל הוא שאין הירח מתכסה לאחר מולדו בארץ ישראל אלא למשך שש שעות, ולפי חשבון זה \u0003מחשבין את תולדתו\u0004 (מולדו) של הירח, אם \u0003נולד\u0004 (זמן המולד) היה \u0003קודם חצות\u0004 היום ועדיין יש יותר משש שעות ביום — \u0003בידוע שנראה\u0004 הירח החדש עוד ביום \u0003סמוך לשקיעת החמה. לא נולד קודם חצות\u0004 אלא לאחריו ואין עוד שש שעות ביום עד לשקיעה — \u0003בידוע שלא נראה סמוך לשקיעת החמה.\u0004","ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם אנו יודעים את הדבר, שהרי ממילא אנו תלויים בהעדאת עדים? \u0003אמר רב אשי: לאכחושי סהדי\u0004 \u0005[\u0006כדי \u0005להכחיש את העדים],\u0006 שכיון שיודעים אנו עובדה זו, הרי אם העידו העדים שראו את הירח החדש בזמן שלפי החשבון אי אפשר לראותו — ברור שהם עדי שקר.","\u0003אמר ר' זירא אמר רב נחמן: עשרים וארבעה שעי\u0004 \u0005[שעות]\u0006 \u0003מכסי סיהרא\u0004 \u0005[מכוסה הירח]\u0006 בין הירח הישן והחדש. וחלוקת זמן הכיסוי בין הירח הישן והחדש — \u0003לדידן שית מעתיקא ותמני סרי מחדתא\u0004 \u0005[לנו,\u0006 לבני בבל, מכוסה \u0005שש\u0006 שעות \u0005מן\u0006 הירח \u0005הישן ושמונה עשרה\u0006 שעות \u0005מן החדש],\u0006 \u0003לדידהו שית מחדתא ותמני סרי מעתיקא\u0004 \u0005[להם,\u0006 לבני ארץ ישראל, \u0005שישה מן החדש ושמונה עשרה מן הישן].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 \u0003אמר רב אשי: לאכחושי סהדי\u0004 \u0005[\u0006כדי \u0005להכחיש את העדים],\u0006 שאם העידו שראו את שני הירחים, הישן והחדש, בתוך עשרים וארבע שעות — ודאי שקר העידו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003צריך שיהא לילה ויום מן החדש,\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 הדבר? \u0003ר' יוחנן אמר:\u0004 נאמר: \u0003\"מערב עד ערב\u0004 תשבתו שבתכם \u0003\"(ויקרא כג, לב), ואם כן היום בא אחר הלילה לענין חשבון החגים.\u0004","\u0003ריש לקיש אמר:\u0004 דבר זה נלמד ממה שנאמר: \u0003\"עד יום האחד ועשרים לחדש בערב\"\u0004 (שמות יב, יח), לומר, שהחג מסתיים בסוף היום, ובערב מתחיל יום אחר, הרי שהיום הולך אחר הלילה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 \u0003אביי אמר: משמעות דורשין איכא בינייהו\u0004 \u0005[הבדל בדרשה יש ביניהם].\u0006","\u0003רבא אמר:\u0004 ענין זה, למה חושבים את \u0003חצות לילה איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם],\u0006 שאם למדים מן הפסוק המדבר ביום הכיפורים (\"מערב עד ערב\"), הרי יש ללכת אחר תחילת הלילה, ואם נראה עדיין הירח הישן בתחילת ליל השלושים, שוב אין מקדשים את היום השלושים. ואם למדים מן הפסוק העוסק בפסח ובמצות (\"עד יום האחד ועשרים לחודש בערב\"), הרי כשם שלענין הזמן שבו אכילת מצה היא רשות, יש לחשב זאת מחצות ליל ראשון של הפסח, כך גם לענין ראיית הירח לענין קידוש החודש, שאף אם נראה בתחילת הלילה, כל שהוא לפני חצות הלילה, עדיין הוא נחשב כסופו של היום הקודם, ומונים לילה ויום מחצות הלילה ואילך\u0005.\u0006","ועוד בענין המועדות, \u0003אמר ר' זירא אמר רב נחמן: כל ספיקא\u0004 \u0005[ספק]\u0006 שיש בקביעת זמנים \u0003לקמיה שדינן\u0004 \u0005[לפניו,\u0006 כלומר: הלאה, \u0005אנחנו משליכים\u0006 אותו\u0005],\u0006 שמחמת הספק לעולם אנו מאחרים ביום אחד. \u0003למימרא דחמיסר ושיתסר עבדינן, ארביסר לא עבדינן\u0004 \u0005[לומר, שחמישה עשר ושישה עשר עושים אנו\u0006 בגלויות מחמת הספק, \u0005ארבעה עשר אין אנו עושים]\u0006 ואין אנו חוששים שמא יש להקדים ביום אחד.","ושואלים: \u0003וליעבד נמי ארביסר\u0004 \u0005[ושיעשו גם כן ארבעה עשר]\u0006 מפני הספק, כיצד? \u0003דלמא חסרוה לאב וחסרוה לאלול\u0004 \u0005[שמא\u0006 נמצא חודש \u0005אב חסר, וגם\u0006 חודש \u0005אלול חסר]\u0006 ואם כן, חל חג הסוכות בארבעה עשר בתשרי (אם נחשב את החודשים כסדרם הרגיל; אחד מלא ואחד חסר)!"],["ומשיבים: \u0003תרי ירחי חסירי קלא אית להו\u0004 \u0005[שני חודשים חסרים\u0006 רצופים, \u0005קול יש להם],\u0006 שדבר זה נדיר ביותר ובודאי יוודע הדבר בינתיים.","מסופר: \u0003לוי אקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל בחדסר\u0004 \u0005[ב\u0006יום \u0005אחד עשר]\u0006 \u0003בתשרי\u0004 לפי החשבון שם. \u0003אמר: בסים תבשילא דבבלאי ביומא רבה דמערבא\u0004 \u0005[טעים הוא התבשיל של הבבליים ביום הגדול,\u0006 יום הכיפורים, \u0005של ארץ ישראל],\u0006 שעיברו בארץ ישראל את חודש אלול והיה יום זה עשירי בתשרי לחשבונם\u0005.\u0006 \u0003אמרי ליה:\u0004 \u0005[אמרו לו]:\u0006 \u0003אסהיד\u0004 \u0005[העד]\u0006 שהיום יום הכיפורים וננהג אף אנו כך! \u0003אמר להו\u0004 \u0005[אמר להם]:\u0006 \u0003לא שמעתי מפי בית דין \"מקודש\".\u0004 וכיון שאני לא שמעתי במפורש אף שאני יודע מתי נקבע החודש אין אני יכול להעיד במישרין ולשנות את חשבונכם.","מסופר, היה \u0003מכריז ר' יוחנן: כל היכא דמטו שלוחי\u0004 \u0005[כל מקום שמגיעים\u0006 אליו \u0005שלוחים]\u0006 של חודש \u0003ניסן,\u0004 להודיע מתי נתקדש החודש שיקבעו לפי זה את חג הפסח. \u0003ולא מטו שלוחי\u0004 \u0005[מגיעים השלוחים]\u0006 של חודש \u0003תשרי\u0004 להודיע מתי יום הכיפורים וסוכות שכן בתשרי אינם הולכים בראש השנה וביום הכיפורים, ונמצא שלעולם יש להם פחות שני ימים כדי ללכת להודיע לתפוצות — \u0003ליעבדו תרי יומי\u0004 \u0005[שיעשו\u0006 גם את הפסח \u0005שני ימים].\u0006 \u0003גזירה\u0004 עשו על חודש \u0003ניסן אטו\u0004 \u0005[משום]\u0006 חודש \u0003תשרי,\u0004 שאם יעשו בניסן רק יום אחד יבואו לעשות כן גם בחודש תשרי, למרות שאינם רשאים לעשות כן.","מסופר: \u0003ר' אייבו בר נגרי ור' חייא בר אבא,\u0004 תלמידיו של ר' יוחנן \u0003איקלעו לההוא אתרא דהוה מטו\u0004 \u0005[הזדמנו למקום אחד שאליו היו מגיעים]\u0006 \u0003שלוחי ניסן ולא מטו\u0004 \u0005[היו מגיעים]\u0006 \u0003שלוחי תשרי, ועבדי חד יומא, ולא אמרו להו ולא מידי\u0004 \u0005[והיו עושים\u0006 בני המקום \u0005יום\u0006 חג \u0005אחד\u0006 בניסן, \u0005ולא אמרו להם\u0006 חכמים אלה \u0005דבר].\u0006 \u0003שמע ר' יוחנן\u0004 רבם את הדבר \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 עליהם, שעושים בניגוד למה ששמעו מפיו. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לאו אמרי לכו\u0004 \u0005[האם לא אמרתי לכם]\u0006 \u0003היכא דמטו\u0004 \u0005[במקום שמגיעים]\u0006 \u0003שלוחי ניסן ולא מטו\u0004 \u0005[מגיעים]\u0006 \u0003שלוחי תשרי ליעבדו תרי יומי\u0004 \u0005[שיעשו\u0006 אף בניסן \u0005שני ימים],\u0006 \u0003גזירה ניסן אטו\u0004 \u0005[משום]\u0006 \u0003תשרי!\u0004","מסופר: \u0003רבא הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה יתיב בתעניתא תרי יומי\u0004 \u0005[שהיה יושב בתענית\u0006 יום הכיפורים \u0005שני ימים\u0006 רצופים\u0005]\u0006 שמא נקבע יום הכיפורים למחרת ולא היום. מספרים: \u0003זימנא חדא אשתכח כוותיה\u0004 \u0005[פעם אחת נמצא\u0006 שאכן היה הדבר \u0005כמותו],\u0006 שבאמת טעו הכל והוא היה היחיד שצם בזמן.","בדומה לזה מסופר: \u0003רב נחמן יתיב בתעניתא כוליה יומי דכיפורי\u0004 \u0005[ישב בתענית בכל יום הכיפורים]\u0006 כרגיל, \u0003לאורתא אתא ההוא גברא\u0004 \u0005[לעת ערב\u0006 בא \u0005אדם אחד]\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003למחר יומא רבה במערבא\u0004 \u0005[מחר הוא היום הגדול,\u0006 יום הכיפורים, \u0005בארץ ישראל]\u0006 וצריך איפוא לצום למחר, ונמצא שהוצרכו לצום שני ימים רצופים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מהיכא את\u0004 \u0005[מאיזה מקום אתה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מ\u0004ן המקום \u0003דמהריא. אמר ליה\u0004 \u0005[לו,\u0006 עליו\u0005]\u0006 בלשון נופל על לשון: בגללך \u0003דם תהא אחריתו,\u0004 וכיוון על עצמו, שבגלל אותו אדם עליו לצום במשך יומיים ויכול למות בשל כך. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 את הפסוק: \u0003\"קלים היו רדפינו\u0004 מנשרי שמים \u0003\"(איכה ד, יט), שהרי אם היה שליח זה מאחר קצת, היו בינתיים אוכלים ושותים, ואילו הוא הקדים ובא בדיוק בזמן שלא יוכלו עוד לאכול ולשתות.\u0004","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר אבין לרבא: כד חזית דמשכה\u0004 \u0005[כאשר רואה אתה שנמשכת]\u0006 \u0003תקופת טבת עד שיתסר\u0004 \u0005[שישה עשר]\u0006 \u0003בניסן,\u0004 שלפי החשבון נמשכת תקופת טבת עד שישה עשר בניסן (שבו אורך היום והלילה משתווים), ואם רואה אתה שתמשך תקופת טבת עד לאחר שישה עשר בניסן — \u0003עברה לההיא שתא\u0004 \u0005[עבר את השנה הזאת]\u0006 \u0003ולא תחוש\u0004 \u0005[ואל תחשוש]\u0006 \u0003לה\u0004 לחפש עוד טעם אחר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שמור את חדש האביב\"\u0004 (דברים טז, א), כלומר, \u0003שמור אביב של תקופה\u0004 שהוא תקופת ניסן \u0003שיהא בחדש ניסן\u0004 לפני הפסח.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן להנהו נחותי ימא\u0004 \u0005[לאותם יורדי הים]:\u0006 \u0003אתון דלא ידעיתו בקביעא דירחא\u0004 \u0005[אתם שאין אתם יודעים בקביעות החודש]\u0006 לפי ראיית הירח, \u0003כי חזיתו סיהרא דמשלים ליומא\u0004 \u0005[כאשר רואים אתם את הירח שהוא משלים ליום],\u0006 כלומר שהירח נראה משעת שקיעה עד הנץ החמה דעו לכם שאז אמצע חודש ניסן ו\u0003בעירו חמירא\u0004 \u0005[ובערו\u0006 את \u0005החמץ].\u0006","ושואלים: \u0003הלא אימת\u0004 \u0005[מתי]\u0006 \u0003משלים\u0004 הוא — \u0003בחמיסר\u0004 \u0005[בחמישה עשר\u0006 בחודש\u0005]\u0006 \u0003והא אנן מארביסר מבערינן\u0004 \u0005[והרי אנו מארבעה עשר מבערים אנו]\u0006 את החמץ, ואם כן לא יעשו אז כראוי! ומשיבים: \u0003לדידהו דמגלו להו עלמא\u0004 \u0005[להם,\u0006 ליורדי הים, \u0005שמגולה להם העולם],\u0006 כלומר, שהאופק פתוח ונראה, \u0003מארביסר\u0004 \u0005[מ\u0006יום \u0005ארבעה עשר]\u0006 הוא \u0003משלים\u0004 כל הלילה ואינו מחשיך עד הזריחה, ולכן יכולים הם לסמוך על סימן זה לקביעת הפסח, ולבער בו את החמץ."],["\u0003על שני חדשים מחללין\u0004 העדים שראו את מולד הירח \u0003את השבת,\u0004 אם צריכים לכך, בדרכם להעיד; \u0003על\u0004 חודש \u0003ניסן ועל\u0004 חודש \u0003תשרי, שבהן שלוחין יוצאין\u0004 במצות בית הדין \u0003לסוריא\u0004 להודיע על קביעת החודש \u0003ובהן מתקנין את המועדות\u0004 החשובים של השנה — יום הכיפורים וסוכות וחג הפסח ושבועות, ועל פיהם נקבע זמנם המדוייק. \u0003וכשהיה בית המקדש קיים\u0004 — \u0003מחללין אף על כולן, מפני תקנת הקרבן\u0004 שיוכלו להקריב במקדש את קרבן מוסף ראש החודש בזמנו הראוי.","נאמר שעל שני חודשים בשנה היו השליחים יוצאים. ותוהים: \u0003על שני חדשים ותו לא\u0004 \u0005[ולא עוד]?!\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מהמשנה הקודמת, שנאמר בה: \u0003על ששה חדשים השלוחין יוצאין,\u0004 ולא רק על שנים!","\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין: \u0003על כולן שלוחין יוצאין מבערב,\u0004 כאשר הדבר ברור שהיה המולד וברור שבית דין יקבעו את יום המחרת כראש חודש, ואילו \u0003על ניסן ועל תשרי\u0004 אין השלוחים יוצאים \u0003עד שישמעו מפי בית דין\u0004 במפורש את המילים \u0003\"מקודש\u0004 החודש\", כדי שיוכלו להעיד עדות שלימה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003על\u0004 החודשים \u0003כולן יוצאין\u0004 השלוחים כבר \u0003מבערב\u0004 כדי להודיע לגולה על שנתקדש החודש\u0003,\u0004 ואולם \u0003על\u0004 חודש \u0003ניסן ועל\u0004 חודש \u0003תשרי\u0004 אינם יוצאים \u0003עד שישמעו מפי בית דין: \"מקודש\".\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שמחללין עליהן\u0004 (על עדות החודשים) \u0003את השבת?\u0004 — \u0003תלמוד לומר: \"אלה מועדי ה'\u0004 מקראי קודש \u0003אשר תקראו אתם במועדם\"\u0004 (ויקרא כג, ד), והדגיש הכתוב שצריך לקובעם במועדם בכל מקרה, ולכן מותר לעבור לשם כך על איסורי שבת.","\u0003יכול כשם שמחללין עד שיתקדשו\u0004 בהבאת עדי הראיה, \u0003כך מחללין\u0004 את השבת \u0003עד שיתקיימו\u0004 שאף השליחים האמורים לצאת לרחבי הארץ וחוצה לה כדי להודיע על שנתקדש החודש רשאים לחלל לשם כך את השבת — \u0003תלמוד לומר: \"אשר תקראו אתם\"\u0004 ללמדנו: \u0003על קריאתם\u0004 כלומר, קביעתם — \u0003אתה מחלל\u0004 את השבת, \u0003ואי אתה מחלל על קיומן.\u0004","\u0003שנינו במשנה: וכשהיה בית המקדש קיים, מחללין\u0004 היו את השבת \u0003אף על\u0004 החודשים \u0003כולן מפני תקנת הקרבן. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו מחללין אף על כולן. משחרב בית המקדש אמר להן רבן יוחנן בן זכאי\u0004 לחכמים: \u0003וכי יש\u0004 עתה איזשהו \u0003קרבן\u0004 שבשבילו יצטרכו לחלל? \u0003התקינו שלא יהו מחללין אלא על ניסן ועל תשרי בלבד.\u0004","\u0003בין שנראה\u0004 מולד הירח \u0003בעליל\u0004 בגלוי לעיני כל, \u0003בין שלא נראה בעליל\u0004 אלא על ידי יחידים בלבד — \u0003מחללין עליו את השבת. ר' יוסי אומר: אם נראה בעליל\u0004 — \u0003אין מחללין עליו את השבת,\u0004 שאם נראה במקום אחד בגלוי בודאי נראה גם סמוך לירושלים, ואין צורך להרחיק ללכת כדי להודיע על דבר שנודע ממילא.","מסופר: \u0003מעשה שעברו יותר מארבעים זוג\u0004 להודיע שראו את מולד הירח \u0003ועיכבם ר' עקיבא בלוד\u0004 שאמר להם שאין צורך לחלל את השבת לצורך זה. \u0003שלח לו רבן גמליאל: אם מעכב אתה את הרבים\u0004 — \u0003נמצאת מכשילן לעתיד לבא,\u0004 שגם בפעם אחרת יאמרו: מה לנו ללכת אם אין עדותנו נחוצה, וכשיידרשו — לא יימצאו העדים.","\u0003מאי\u0004 \u0005[מה,\u0006 כיצד\u0005]\u0006 \u0003משמע דהאי \"עליל\" לישנא דמיגלי הוא\u0004 \u0005[ש\"עליל\" זה לשון גלוי הוא]?\u0006 \u0003אמר ר' אבהו אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אמרות ה' אמרות טהרות כסף צרוף בעליל לארץ מזקק שבעתים\"\u0004 (תהלים יב, ז) שהוא מפרשו — כסף הגלוי לעין כל.","כיון שהובא פסוק זה מביאים מדברי \u0003רב ושמואל\u0004 שנחלקו בדברים הקשורים באותו פסוק. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חמשים שערי בינה\u0004 (שהוא מפרש \"שבעתיים\" — שבע פעמים שבע) \u0003נבראו בעולם, וכולן ניתנו למשה, חסר\u0004 שער \u0003אחד. שנאמר: \"ותחסרהו מעט מאלהים\"\u0004 (תהלים ח, ו) ונאמר:","\u0003\"בקש קהלת למצא דברי חפץ\"\u0004 (קהלת יב, י) שמשמעו שביקש וניסה ולא יכול — \u0003בקש קהלת להיות כמשה, יצתה בת קול ואמרה לו: \"וכתוב ישר דברי אמת\"\u0004 (קהלת יב, י) הם הדברים הכתובים בתורה, ומה כתוב שם — \u0003\"ולא קם נביא עוד בישראל כמשה\"\u0004 (דברים לד, י) אלה דבריו של חכם אחד.","\u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: בנביאים לא קם\u0004 כמשה, \u0003במלכים קם\u0004 והוא שלמה שהיה חכם כמשה. \u0003אלא מה אני מקיים\u0004 את דברי הכתוב \u0003\"בקש קהלת למצא דברי חפץ\"\u0004 (קהלת יב, י) — ש\u0003בקש קהלת לדון דינין שבלב\u0004 ולקבוע על פי המסתבר לו, \u0003שלא בעדים ושלא בהתראה\u0004 ולסמוך על הבנתו שהוא יכול לגלות את האמת. \u0003יצתה בת קול ואמרה לו: \"וכתוב ישר דברי אמת\"\u0004 (קהלת יב, י) ומה הוא — \u0003\"על פי שנים עדים\u0004 או שלשה עדים יומת המת לא יומת על פי עד אחד \u0003\"(דברים יז, ו). שאין דנים למוות או למלקות אלא על פי שני עדים ולא פחות.\u0004"],["שנינו במשנה: \u0003\"מעשה שעברו יותר מארבעים זוג ועיכבן ר' עקיבא\u0004 בלוד \u0003\". תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה: חס ושלום שר' עקיבא עיכבן,\u0004 שבודאי לא היה עושה טעות מעין זו. \u0003אלא שזפר\u0004 שהיה \u0003ראשה של\u0004 העיר \u0003גדר עיכבן, ושלח רבן גמליאל והורידוהו מגדולתו\u0004 משום שעשה שלא כדין.","\u0003אב ובנו שראו את החדש\u0004 — \u0003ילכו\u0004 שניהם כאחד להעיד. \u0003לא שמצטרפין זה עם זה\u0004 לעדות אחת, שהרי קרובים פסולים לעדות, \u0003אלא שאם יפסל אחד מהם\u0004 — \u0003יצטרף השני עם אחר\u0004 ויוכלו להעיד על החודש, שהרי יתכן שיש עוד רק עד כשר אחד. \u0003ר' שמעון אומר: אב ובנו וכל הקרובין כשרין לעדות החדש.\u0004 \u0003אמר ר' יוסי: מעשה בטוביה הרופא שראה את החדש בירושלים, הוא ובנו ועבדו משוחרר\u0004 ובאו שלושתם להעיד, \u0003וקבלו הכהנים אותו ואת בנו ופסלו את עבדו,\u0004 שהקפידו לקדש את החודש רק על פי עדות יהודים מיוחסים. \u0003וכשבאו לפני בית דין\u0004 — \u0003קבלו אותו ואת עבדו, ופסלו את בנו\u0004 משום קירבה. \u0003אמר ר' לוי: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 המתיר עדות החודש בקרובים שלא כשאר העדויות שבתורה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' אל משה ואל אהרן בארץ מצרים לאמר. החדש הזה לכם\u0004 ראש חודשים ראשון הוא לכם לחדשי השנה\u0003\"\u0004 (שמות יב, א-ב), והמלה \"לכם\" באה לומר: \u0003עדות זו\u0004 של ראש החודש \u0003תהא כשרה בכם,\u0004 ומכאן למד שכשם שעדות החודש כשרה במשה ואהרן אף על פי שהם אחים, כך יכולים גם שאר אחים להעיד על החודש.","","","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מתירים עדות החודש בקרובים, כיצד מבינים הם כתוב זה? ומשיבים, שהם מפרשים: \u0003עדות זו תהא מסורה לכם\u0004 ולשכמותכם, שגדולי הדור הם שיהיו הדיינים הקובעים את החודש בזמנו. שנינו במשנה: \u0003\"אמר ר' יוסי מעשה בטוביה הרופא כו'\". אמר רב חנן בר רבא: הלכתא\u0004 \u0005[ההלכה\u0006 היא\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 שיש להתיר עדות החודש בקרובים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא לרב חנן בר רבא:\u0004 הלא כנגדו יש \u0003ר' יוסי\u0004 שכרגיל הלכה כמותו כנגד כל אחד מחבריו \u0003ו\u0004גם \u0003מעשה\u0004 שסיפר שכך עשו בפועל ופסקו כשיטתו \u0003ואת אמרת הלכתא\u0004 \u0005[ואתה אומר\u0006 כי \u0005הלכה]\u0006 \u0003כר' שמעון\u0004 נגד נימוקים אלה?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והא זמנין סגיאין אמרית קמיה\u0004 \u0005[והרי פעמים הרבה אמרתי לפני]\u0006 \u0003רב\u0004 כי \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' שמעון\u0004 בענין זה \u0003ולא אמר לי ולא מידי\u0004 \u0005[דבר],\u0006 משמע שהלכה כן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היכי תנית\u0004 \u0005[היאך\u0006 אתה \u0005שונה]\u0006 את הדעות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אפכא\u0004 \u0005[להיפך],\u0006 כלומר, הדעה שבנוסח שלפנינו היא דעת ר' יוסי ששנה אותה בשם ר' שמעון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא אמר לך ולא מידי\u0004 \u0005[דבר],\u0006 שהרי לפי גרסתך שהפכת פסקת איפוא הלכה כראוי. \u0003אמר טבי בריה\u0004 \u0005[בנו]\u0006 של \u0003מרי טבי אמר מר עוקבא אמר שמואל: הלכתא\u0004 \u0005[ההלכה\u0006 היא\u0005]\u0006 \u0003כר' שמעון.\u0004","","","\u0003אלו הן הפסולין\u0004 להעיד: \u0003המשחק בקוביא\u0004 ושאר משחקי מזל, \u0003ומלוי ברבית, ומפריחי יונים\u0004 שמהמרים על יונים בתחרות מעוף, \u0003וסוחרי שביעית\u0004 העושים סחורה בפירות שנת השמיטה, \u0003ועבדים. זה הכלל: כל עדות שאין האשה כשירה לה\u0004 (שכן אשה רשאית להעיד על מיתת אדם, ועוד כיוצא באלה) \u0003אף הן\u0004 הפסולין הללו \u0003אינן כשירין לה.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי כל עדות ש\u0003אשה כשירה לה\u0004 — \u0003אף הן\u0004 הקרובים \u0003כשירין לה. אמר רב אשי: זאת אומרת גזלן\u0004 שאינו נחשב ככזה אלא מ\u0003דבריהם\u0004 של חכמים, אף שלשאר עדויות פסלו אותם חכמים, מכל מקום \u0003כשירין לעדות אשה\u0004 (להעיד שמת הבעל).","\u0003מי שראה את החדש ואינו יכול להלך\u0004 מפני שהוא חולה או שיש מום ברגליו — \u0003מוליכים אותו על החמור, אפילו במטה\u0004 ומחללים שבת אם יש צורך בכך. \u0003ואם צודה להם\u0004 (מארב של שודדים) בדרך, והם חוששים מפניו — \u0003לוקחין בידן מקלות,\u0004 או שאר כלי נשק אם יש צורך בהם, אפילו בשבת.","\u0003ואם היתה דרך רחוקה\u0004 — \u0003לוקחין בידם מזונות\u0004 ואינם חוששים לאיסור הוצאה בשבת. \u0003שעל מהלך לילה ויום,\u0004 כלומר, בתוך מרחק כדי מהלך זה \u0003מחללין\u0004 העדים \u0003את השבת ויוצאין לעדות החדש, שנאמר: \"אלה מועדי ה' אשר תקראו אתם במועדם\"\u0004 (ויקרא כג, ד). לומר שבכל מקרה, אף אם מצריך הדבר לעבור על דברי תורה — חייבים לדאוג לקביעת המועדים בזמנם.","","\u0003אם אינן מכירין אותו,\u0004 שאין בית דין מכירים בטיבו של העד אם כשר הוא — בית הדין שבעירו \u0003משלחין עמו אחר להעידו\u0004 (להעיד עליו) שאדם זה המעיד על החודש אדם כשר הוא ואפשר לסמוך עליו. ומסבירים: \u0003בראשונה היו מקבלין עדות החדש מכל אדם,\u0004 שהרי סתם אדם כשר לעדות, \u0003משקלקלו הבייתוסים\u0004 בני כת זו שיש להם שיטה אחרת לגבי קביעת המועדים, ורצו לשבש את דברי חכמים ולשנות את קביעות המועדים והיו מביאים עדי שקר \u0003התקינו שלא יהו מקבלין\u0004 עדות החודש \u0003אלא מן המכירין\u0004 בלבד.","על לשון המשנה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש הדבר\u0005]\u0006 ששולחים עמו \u0003אחר?\u0004 אם נאמר כי אחר זה הוא \u0003חד\u0004 \u0005[\u0006אדם \u0005אחד],\u0006"],["ותוהים: \u0003וחד מי\u0004 \u0005[ו\u0006עד \u0005אחד האם]\u0006 הוא \u0003מהימן?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה שבא הוא ועדיו עמו להעיד עליו\u0004 משמע שצריך שנים! \u0003אמר רב פפא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחר\"\u0004 שנאמר במשנה — \u0003זוג אחר\u0004 של עדים.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך],\u0006 אם כן מה פירוש \u0003\"אם אינן מכירין אותו\"\u0004 האמור במשנה? \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אותו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003\"אותו\"\u0004 פירושו \u0003חד\u0004 \u0005[אחד] —\u0006 \u0003וחד מי\u0004 \u0005[ואחד האם]\u0006 הוא \u0003מהימן?\u0004 הלא \u0003\"משפט\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 בענין קביעת השנה החודשים וראש השנה (\"כי חוק לישראל הוא משפט לאלהי יעקב\". תהלים פא, ה) \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אותו\"\u0004 — \u0003אותו הזוג, הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחר\"\u0004 — \u0003זוג אחר.\u0004","ושואלים: \u0003וחד\u0004 \u0005[ו\u0006עד \u0005אחד]\u0006 האם הוא \u0003לא מהימן\u0004 בזה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003מעשה בר' נהוראי שהלך אצל העד להעיד עליו בשבת באושא,\u0004 לומר שהוא איש שאפשר לסמוך על עדותו, משמע שר' נהוראי לבדו העיד!","ודוחים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ר' נהוראי סהדא אחרינא הוה בהדיה\u0004 \u0005[עד אחר היה עמו]\u0006 \u0003והא דלא חשיב ליה\u0004 \u0005[וזה שלא מנה אותו]\u0006 ולא הזכירוהו — \u0003משום כבודו של ר' נהוראי,\u0004 שעיקר הלימוד הוא ממנהגו של ר' נהוראי. אבל באמת צריך שניים. \u0003רב אשי אמר:\u0004 במקרה של \u0003ר' נהוראי סהדא אחרינא הוה\u0004 \u0005[עד אחד היה]\u0006 כבר \u0003באושא\u0004 עצמה שהכיר את עד המולד \u0003ואזל\u0004 \u0005[והלך]\u0006 \u0003ר' נהוראי לאצטרופי בהדיה\u0004 \u0005[להצטרף עמו]\u0006 ושואלים:","\u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך מה\u0006 יש \u0005לומר],\u0006 שאם היו שני עדים מה החידוש בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מספיקא\u0004 \u0005[מספק]\u0006 \u0003לא מחללינן שבתא\u0004 \u0005[מחללים אנו שבת],\u0006 שמא העד שבאושא איננו מצוי שם באותו יום ונמצא שחילל ר' נהוראי את השבת לחינם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 חידוש זה, שלצורך חשוב זה מחללים את השבת אף מספק.","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל לבבל, \u0003אמר: קדשוה לירחא במערבא\u0004 \u0005[קידשו את החודש בארץ ישראל]\u0006 בתאריך מסויים. \u0003אמר רב כהנא: לא מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר דווקא ב\u0003עולא, דגברא רבה\u0004 \u0005[שאדם גדול]\u0006 \u0003הוא,\u0004 ובודאי הוא \u0003מהימן\u0004 על מה שהעיד. \u0003אלא אפילו איניש דעלמא נמי\u0004 \u0005[אדם סתם גם כן]\u0006 \u0003מהימן\u0004 בעדות זו ואין צריך לכך שני עדים. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כל מילתא דעבידא לאגלויי\u0004 \u0005[דבר שעתיד להגלות]\u0006 לאחר זמן שדבריו היו שקר — \u0003לא משקרי בה אינשי\u0004 \u0005[אין אנשים משקרים בו],\u0006 ואין צריכים לעדות של שנים אלא בדבר שאינו עשוי להתגלות לרבים. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בא אחד מסוף העולם ואמר קדשו בית דין את החדש\u0004 — \u0003נאמן\u0004 ואין צורך בשני עדים.","שנינו במשנה ש\u0003בראשונה היו מקבלין עדות החדש מכל אדם\u0004 עד שקילקלו הבייתוסים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בפרוטרוט כיצד אירע הדבר; \u0003מה קלקול קלקלו הבייתוסין? פעם אחת בקשו בייתוסין להטעות את\u0004 ה\u0003חכמים\u0004 בענין קביעת החודש, \u0003שכרו שני בני אדם בארבע מאות זוז\u0004 שיעידו שקר, \u0003אחד\u0004 מהם היה \u0003משלנו,\u0004 כלומר, נוטה אחרי הפרושים וחכמי ישראל \u0003ואחד\u0004 מהם היה \u0003משלהם.\u0004","משנכנסו להעיד עדותם, \u0003שלהם העיד\u0004 את \u0003עדותו\u0004 שראה את הירח \u0003ויצא. שלנו,\u0004 כשבא להעיד, \u0003אמרו לו\u0004 כפי הנהוג: \u0003אמור כיצד ראית את הלבנה! אמר להם: עולה הייתי במעלה אדומים, וראיתיו שהוא רבוץ בין שני סלעים, ראשו דומה לעגל, אזניו דומין לגדי, קרניו דומות לצבי, וזנבו מונחת לו בין ירכותיו, והצצתי בו ונרתעתי ונפלתי לאחורי. ואם אין אתם מאמינים לי\u0004 שכך ראיתי — \u0003הרי מאתים זוז צרורין לי בסדיני\u0004 ששילמו לי כשוחד. כיון ששמעו כך הבינו חכמים שהיתה כאן עדות מדומה של העד הראשון, ושלא ראו כלל את המולד.","\u0003אמרו לו: מי הזקיקך לכך,\u0004 מי הביא אותך שתבוא גם אתה להעיד כאשר בסופו של דבר אתה מספר שלא ראית דבר? \u0003אמר להם: שמעתי שבקשו בייתוסים להטעות את חכמים, אמרתי: אלך אני\u0004 ואשכיר עצמי להם כעד \u0003ו\u0004משישכרוני אלך ו\u0003אודיע להם\u0004 לחכמים את האמת, \u0003שמא יבואו בני אדם שאינם מהוגנין\u0004 ויעידו עדות שקר כפי שביקשו מהם, \u0003ויטעו את\u0004 ה\u0003חכמים.\u0004","\u0003אמרו לו: מאתים זוז\u0004 — \u0003נתונין לך במתנה\u0004 אף שלא עשית את השליחות שקיבלת על עצמך, שכן כוח בבית דין להפקיע ממון, \u0003והשוכרך ימתח על העמוד\u0004 להלקותו. \u0003באותה שעה התקינו שלא יהו מקבלין\u0004 עדות החודש \u0003אלא מן ה\u0004אנשים שבית הדין \u0003מכירין\u0004 אותם ואת טיבם, כדי שלא יכשלו שוב בעד שבא להעיד עדות שקר.","\u0003בראשונה היו משיאין משואות\u0004 (מדליקים מדורות) כסימנים, כדי להודיע באמצעותם לתפוצות ישראל על שנתקדש החודש. \u0003משקלקלו הכותים\u0004 (השומרונים) והיו הם משיאים משואות שלא בזמן כדי לקלקל לישראל, \u0003התקינו שיהו שלוחין יוצאין.\u0004","ובכל אותו הזמן שעדיין היו עושים כן, \u0003כיצד היו משיאין משואות? מביאין\u0004 דברים העשויים לבעור יפה, כגון \u0003כלונסאות של ארז ארוכין, וקנין, ועצי שמן, ונעורת של פשתן. וכורך\u0004 כולם \u0003במשיחה\u0004 (בחוט) \u0003ועולה לראש ההר ומצית בהן את האור\u0004 (האש). ואת המוט הגדול של ארז היה \u0003מוליך ומביא\u0004 ימינה ושמאלה \u0003ומעלה\u0004 למעלה \u0003ומוריד\u0004 למטה, \u0003עד שהוא רואה את חבירו\u0004 שהיה \u0003עושה כן בראש ההר השני,\u0004 ובכך ידע שגם ההוא קיבל ומסר את הידיעה \u0003וכן בראש ההר השלישי,\u0004 וכך היתה הידיעה עוברת.","\u0003ומאין היו משיאין משואות\u0004 — באלו הרים עשו כן? \u0003מהר המשחה\u0004 (מהר הזיתים) היו מעבירים את הידיעה מירושלים עד \u0003לסרטבא, ומסרטבא\u0004 עד \u0003לגרופינא, ומגרופינא לחוורן, ומחוורן לבית בלתין, ומבית בלתין לא זזו משם\u0004 ולא עשו מקום קבוע להדלקת מדורות אחרות, \u0003אלא\u0004 היה האיש הממונה על כך \u0003מוליך ומביא ומעלה ומוריד\u0004 את המשואה שבידו \u0003עד שהיה רואה\u0004 את \u0003כל הגולה לפניו כמדורת האש,\u0004 שאף הם היו מדליקים כנגדו להמשיך להעביר את ההודעה ממקום למקום.","תחילה שואלים שאלה לשונית: \u0003מאי\u0004 \u0005[מהיכן]\u0006 \u0003משמע\u0004 ש\u0003\"משיאין\" לישנא דיקוד\u0004 \u0005[לשון של הדלקת אש]\u0006 \u0003הוא? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישאם דוד ואנשיו\"\u0004 (שמואל ב' ה, כא), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]\u0006 כתוב זה: \u0003ואוקדינן\u0004 \u0005[ושרף אותם]\u0006 \u0003דוד.\u0004","ולעצם הדברים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין משיאין משואות אלא על החדש שנראה בזמנו לקדשו\u0004 ביום שלושים. \u0003ואימתי משיאין\u0004 — \u0003לאור עיבורו\u0004 שאם נקבע החודש ביום השלושים לחודש הקודם, הרי בלילה אור ליום שלושים ואחד מדליקים אז את המדורה.","ומעירים: \u0003למימרא\u0004 [האם לומר] מכאן שעל חודש \u0003חסר עבדינן\u0004 \u0005[עושים,\u0006 מדליקים \u0005אנו]\u0006 משואות, ואולם על חודש \u0003מלא לא עבדינן\u0004 \u0005[אין אנו עושים,\u0006 מדליקים\u0005]\u0006 משואות. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר ר' זירא: גזירה משום ראש חדש חסר שחל להיות בערב שבת. אימת עבדי\u0004 \u0005[מתי עושים]\u0006 את הדלקת המדורות — \u0003באפוקי שבתא\u0004 \u0005[ביציאת השבת],\u0006 שהרי בליל שבת אסור להדליק אש. \u0003דאי אמרת נעביד נמי\u0004 \u0005[שאם אומר אתה שנעשה,\u0006 נדליק \u0005גם כן]\u0006 על חודש \u0003מלא,\u0004 אם כן \u0003אתו\u0004 \u0005[יבואו]\u0006"],["\u0003אמרי האי\u0004 \u0005[יאמרו\u0006 האנשים, כי \u0005זה]\u0006 חודש \u0003חסר הוא והאי דלא עביד\u0004 \u0005[וזה שלא עשו]\u0006 \u0003מאתמול\u0004 בליל שבת, \u0003משום\u0004 ש\u0003לא אפשר\u0004 בשל קדושת השבת. \u0003או דלמא\u0004 \u0005[שמא]\u0006 חודש \u0003מלא הוא ובזמנו\u0004 עשו אותו. ולכן תיקנו שאין משיאין משואות אלא בחודש חסר, וחודש שלא הדליקו בו משואות — הבינו מעצמם שהוא מלא.","ושואלים: \u0003וליעביד\u0004 \u0005[ושיעשו,\u0006 ידליקו\u0005]\u0006 משואות \u0003בין\u0004 על חודש \u0003מלא ובין\u0004 על חודש \u0003חסר,\u0004 אולם \u0003וכי מקלע\u0004 \u0005[וכאשר יזדמן]\u0006 \u0003ראש חדש\u0004 להיות \u0003בערב שבת\u0004 שאז צריכים להדליק בליל שבת אז \u0003לא ליעביד\u0004 \u0005[יעשו,\u0006 ידליקו\u0005]\u0006 \u0003כלל. וכיון דלא עבדינן\u0004 \u0005[שאין עושים אנו]\u0006 ב\u0003מוצאי שבת\u0004 בחודש זה \u0003ועבדינן\u0004 \u0005[ועושים,\u0006 מדליקים \u0005אנו]\u0006 בכל זאת בחודש \u0003מלא\u0004 — ממילא \u0003מידע ידעי\u0004 \u0005[ידעו]\u0006 שחודש \u0003חסר הוא\u0004 חודש זה, ואז אפשר יהיה להדליק משואות בכל שאר החודשים חוץ ממקרה יוצא דופן זה!","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003אתו למיטעי\u0004 \u0005[יבואו לטעות],\u0006 כי \u0003אמרי\u0004 \u0005[אומרים\u0006 הם\u0005]:\u0006 \u0003האי\u0004 \u0005[\u0006חודש \u0005זה]\u0006 \u0003מלא הוא והאי דלא עבדי\u0004 \u0005[וזה שלא עשו,\u0006 הדליקו\u0005]\u0006 בו משואות — \u0003איתנוסי הוא דאיתנוסי\u0004 \u0005[\u0006משום \u0005שנאנסו],\u0006 שאירע להם שנשתכרו בסעודת השבת, ולכן לא יהיה סימן מובהק בדבר.","ומקשים: \u0003וליעביד\u0004 \u0005[ושיעשו,\u0006 ידליקו\u0005]\u0006 משואות על חודש מלא \u0003ולא ליעביד\u0004 \u0005[יעשו\u0006 כן\u0005]\u0006 על חודש \u0003חסר כלל,\u0004 ויועיל הסימן גם במקרה זה! ומשיבים, \u0003אמר אביי: משום בטול מלאכה לעם שני ימים,\u0004 שהרי אם עושים על החסר יודעים הכל שמאותו לילה שבו השיאו משואות כבר התחיל החודש הבא, ואין זה עוד ראש חודש. אבל אם היו מדליקים משואות רק על החודש המלא — היו צריכים ביום השלושים לחודש הקודם לעשותו מספק ראש חודש וגם ביום שבא אחריו. וכיון שבכמה דברים נהגו העם להבטל מכמה מלאכות בראש חודש, ייגרם ביטול מלאכה יום נוסף שלא לצורך, ומשום כך תיקנו את הסימן בחודש חסר דווקא.","שנינו במשנה: \u0003כיצד היו משיאין משואות\u0004 — \u0003מביאין כלונסות של\u0004 ארז ודברים נוספים הבוערים יפה וקשרום כאחד והדליקו בהם אש. \u0003אמר רב יהודה, ארבעה מיני ארזים הם: ארז, קתרום, עץ שמן, וברוש.\u0004 המלה \u0003קתרום\u0004 לא היתה ידועה ולכן \u0003אמר רב:\u0004 זהו העץ הקרוי \u0003אדרא. דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אמרו]:\u0006 זה העץ הקרוי \u0003מבליגא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שזהו העץ הקרוי \u0003גולמיש.\u0004","ומעירים כי שיטת רב יהודה \u0003פליגא\u0004 \u0005[חלוקה]\u0006 על שיטת \u0003רבה בר רב הונא,\u0004 ש\u0003אמר רבה בר רב הונא: אמרי בי\u0004 \u0005[אומרים בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: עשרה מיני ארזים הם, שנאמר: \"אתן במדבר ארז שטה והדס ועץ שמן אשים בערבה ברוש תדהר ותאשור יחדו\"\u0004 (ישעיה מא, יט), ולדעתו כל אלה כולם הם מיני ארז. ומזהים אותם: \u0003ארז\u0004 הוא קרוי בארמית \u0003ארזא, שטה\u0004 היא זו הקרויה \u0003תורניתא, הדס\u0004 הוא \u0003אסא, עץ שמן\u0004 הוא \u0003אפרסמא, ברוש\u0004 הוא הקרוי בארמית \u0003ברתא, תדהר\u0004 הוא העץ הקרוי בארמית \u0003שאגא, תאשור\u0004 הוא הקרוי בארמית \u0003שוריבנא.\u0004","ותוהים: גם אם מונים אותם את כולם, הלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003שבעה\u0004 בלבד \u0003הוו\u0004 \u0005[הם],\u0006 ולא עשרה! \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: הוסיפו עליהם\u0004 עוד שלושה מינים הקרויים אף הם ארז: \u0003אלונים, אלמונים, אלמוגים.\u0004 ומזהים אותם: \u0003אלונים\u0004 הם הקרויים \u0003בוטמי, אלמונים\u0004 קרויים \u0003בלוטי, אלמוגין\u0004 הם \u0003כסיתא\u0004 \u0005[אלמוגים].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי אלה השלושה שהוסיפו עליהם, הם: \u0003ארונים, ערמונים, אלמוגין.\u0004 ומזהים אותם: \u0003ארונים\u0004 הם הקרויים בארמית \u0003ערי, ערמונים\u0004 הם \u0003דולבי, אלמוגין\u0004 הם \u0003כסיתא.\u0004","אגב הזכרת האלמוגים (כסיתא) מספרים בענין זה: נאמר, \u0003\"וצי אדיר לא יעברנו\"\u0004 (ישעיה לג, כא), שאף צי אדיר לא יוכל לעבור את הנחל העתיד לצאת מבית המקדש. ומהו אותו \"צי אדיר\"? \u0003אמר רב: זו בורני\u0004 \u0005[אניה]\u0006 \u0003גדולה.\u0004","ומסבירים: \u0003היכי עבדו\u0004 \u0005[כיצד עושים]\u0006 בעלי האניות הללו שהיו עשויות לשליית אלמוגים מקרקעית הים, כדי להוציא את האלמוגים? \u0003מייתי שית אלפי גברי בתריסר ירחי שתא\u0004 \u0005[מביאים ששת אלפים אנשים\u0006 שיעבדו \u0005בשנים עשר חודשי השנה]\u0006 \u0003ואמרי לה תריסר אלפי גברי בשיתא ירחי שתא\u0004 \u0005[ויש אומרים\u0006 שהיו מביאים \u0005שנים עשר אלפים איש שיעבדו בשישה חודשי השנה]\u0006 \u0003וטעני לה חלא עד דשכנא\u0004 \u0005[וטוענים עליה\u0006 על אניה זו \u0005חול עד שהיא יורדת,\u0006 שוקעת\u0005]\u0006 בתוך המים עד סמוך למקום המצאם \u0003ונחית בר אמוראי\u0004 \u0005[ויורד אמודאי]\u0006 \u0003וקטר אטוני דכיתנא בכסיתא\u0004 \u0005[וקושר חבלי פשתן באלמוגים]\u0006 \u0003וקטר להו בספינתא\u0004 \u0005[וקושר אותם,\u0006 את החבלים, \u0005בספינה]\u0006 \u0003ונטל חלא ושדו לבראי\u0004 \u0005[ולוקחים את החול וזורקים החוצה]\u0006 ומכיון שמוציאים החול האניה שוב צפה ועולה, \u0003וכמה דמדליא, עקרא ומתיא\u0004 \u0005[וכמה ש\u0006היא \u0005עולה,\u0006 היא \u0005עוקרת ומביאה]\u0006 מעצי האלמוגים.","ומעירים: ואלמוגים אלה יקרים כל כך עד שבעליהם \u0003מחליף\u0004 אותם לפי משקל \u0003על חד תרין בכספא\u0004 \u0005[אחד על שנים בכסף].\u0006 ומעירים: \u0003תלת פרוותא הויין\u0004 \u0005[שלושה נמלים יש]\u0006 באותם מקומות \u0003תרתי בי רומאי וחדא דבי פרסאי\u0004 \u0005[שנים שייכים לבית\u0006 למחוז \u0005הרומאי ואחד לבית\u0006 למחוז \u0005הפרסי],\u0006 \u0003דבי רומאי מסקן כסיתא\u0004 \u0005[של בית הרומאים מעלים אלמוגים]\u0006 \u0003דבי פרסאי מסקן מרגנייתא\u0004 \u0005[של בית הפרסיים מעלים מרגליות],\u0006 \u0003ומקרייא\u0004 \u0005[וקוראים\u0006 להם\u0005]\u0006 לנמלי הפרסיים: \u0003פרוותא דמשמהיג\u0004 \u0005[נמלי המלוכה].\u0006","כיון שהבאנו קודם אותו פסוק, \u0003אמר ר' יוחנן: כל שיטה ושיטה שנטלו גוים מירושלים, עתיד הקדוש ברוך הוא להחזירן לה. שנאמר: \"אתן במדבר ארז שטה\u0004 והדס ועץ שמן אשים בערבה ברוש תדהר ותאשור יחדיו\" (ישעיה מא, יט), \u0003ואין מדבר אלא\u0004 כינוי ל\u0003ירושלים, שנאמר: \"ציון מדבר היתה\"\u0004 (ישעיה סד, ט).","\u0003ואמר ר' יוחנן: כל הלומד תורה ואינו מלמדה\u0004 לאחרים, \u0003דומה להדס במדבר.\u0004 שהרי אף שהדס יש לו ריח ערב, אין מי שיכול להנות ממנו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמועה זו באופן אחר, לחיוב: \u0003כל הלומד תורה ומלמדה במקום שאין תלמידי חכמים\u0004 אחרים — \u0003דומה להדס במדבר\u0004 שהוא \u0003חביב,\u0004 שכאשר מוצאים הדס במדבר השמם בודאי נהנים מריחו.","\u0003ואמר ר' יוחנן: אוי להם לגוים שאין להם תקנה\u0004 על חטאותיהם כנגד ישראל, \u0003שנאמר: \"תחת הנחשת אביא זהב ותחת הברזל אביא כסף ותחת העצים נחשת ותחת האבנים ברזל\"\u0004 (ישעיה ס, יז), ואם כן, לכל דבר יש תקנה, להחזיר כיוצא בו או יותר ממנו. אולם \u0003תחת ר' עקיבא וחביריו\u0004 שהרגום הגוים \u0003מאי מביאין\u0004 \u0005[מה\u0006 הם יכולים \u0005להביא]\u0006 כתרומה וכפרה? \u0003ועליהם הוא אומר \"ונקיתי דמם לא נקיתי\"\u0004 (יואל ד, כא).","שנינו במשנה: \u0003מאין היו משיאין משואות\u0004 — מהר המשחה לסרטבא ומסרטבא לגרופינא ומגרופינא לחוורן ומחוורן לבית בלתין \u0003ומבית בלתין\u0004 והלאה שוב לא היו משיאים משואות\u0003.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 המקום הקרוי \u0003\"בית בלתין\"? אמר רב:\u0004"],["\u0003זה\u0004 העיירה הקרויה \u0003בירם.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"גולה\"\u0004 זו שנזכרה כאן, שהרי ודאי אין הכוונה לכל הגולה שבכל העולם, \u0003אמר רב יוסף: זו\u0004 העיר \u0003פומבדיתא\u0004 שבבבל. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 וכיצד נעשה הכל \u0003כמדורת האש? תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בברייתא: \u0003כל אחד ואחד נוטל אבוקה בידו ועולה לראש גגו\u0004 ומדליק. ועל ידי כך נעשית כל העיר כולה כמדורת אש.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: אף\u0004 הערים \u0003חרים וכייר וגדר וחברותיה\u0004 כיוצא בהן, שהיו מדליקים משואות שם. \u0003איכא דאמרי: ביני וביני הוו קיימי\u0004 \u0005[יש שאומרים: בין אותם\u0006 המקומות המוזכרים במשנה \u0005היו עומדות]\u0006 אלה שהזכיר ר' שמעון בן אלעזר. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003להך גיסא\u0004 \u0005[\u0006ש\u0005לצד זה]\u0006 של \u0003ארץ ישראל הוו קיימי\u0004 \u0005[היו\u0006 מקומות אלה \u0005עומדים].\u0006 \u0003מר חשיב דהאי גיסא, ומר חשיב דהאי גיסא\u0004 \u0005[חכם\u0006 אחד \u0005מנה\u0006 מה שיש \u0005בצד אחד והחכם\u0006 השני \u0005מנה\u0006 מה שיש \u0005בצד האחר].\u0006","\u0003אמר ר' יוחנן: בין כל אחת ואחת\u0004 מהמקומות שהוזכרו יש מרחק \u0003שמונה פרסאות.\u0004 ומחשבים: \u0003כמה הוו להו\u0004 \u0005[הריהם]\u0006 בסך הכל \u0003תלתין ותרתין\u0004 \u0005[שלושים ושתים]\u0006 פרסות, \u0003והא האידנא טובא הוו\u0004 \u0005[והרי עכשיו\u0006 המרחק הוא \u0005יותר]\u0006 משלושים ושתים פרסה! \u0003אמר אביי: אסתתומי אסתתום להו דרכי\u0004 \u0005[נסתתמו להם הדרכים]\u0006 הישרות בארץ, וכיום הולכים האנשים בדרכי עקלתון המאריכים את הדרך.","\u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"לכן הנני שך את דרכך בסירים\u0004 וגדרתי את גדרה ונתיבותיה לא תמצא \u0003\"(הושע ב, ח). רב נחמן בר יצחק אמר מהכא\u0004 \u0005[מכאן]\u0006 יש ללמוד זאת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נתיבתי עוה\"\u0004 (איכה ג, ט), משמע שהדרכים התעקמו והתארכו במשך זמן הגלות.","\u0003חצר גדולה היתה בירושלים ובית יעזק היתה נקראת, ולשם\u0004 היו \u0003כל העדים\u0004 הבאים להעיד על החודש \u0003מתכנסין. ובית\u0004 ה\u0003דין\u0004 היו \u0003בודקין אותם שם. וסעודות גדולות\u0004 היו \u0003עושים להן, בשביל שיהו רגילין\u0004 ורוצים \u0003לבא\u0004 להעיד.","\u0003בראשונה\u0004 אם היה זה בשבת \u0003לא היו זזין משם כל היום,\u0004 שהרי הגיעו מחוץ לתחום ואף שהגיעו בהיתר, מכל מקום אסור להם ללכת יותר מארבע אמות לכל צד מהמקום שהגיעו אליו. ומתוך החשש שמא דווקא בשל הגבלה זו יימנעו העדים מלבוא, \u0003התקין רבן גמליאל הזקן שיהו מהלכין אלפים אמה לכל רוח\u0004 (צד) כאילו היו בתוך תחומם,","\u0003ולא אלו בלבד\u0004 התירו להם לצאת מחוץ לתחום ונתנו להם רשות לנוע במקום שהגיעו אליו ואלפים אמה ממנו, \u0003אלא אף חכמה\u0004 (מילדת) \u0003הבאה ליילד\u0004 תינוק, \u0003והבא להציל מן הדליקה ומן הגייס\u0004 (התנפלות צבא) \u0003ומן הנהר\u0004 השוטף שמימיו גאו, \u0003ומן המפולת\u0004 — שכל אלו אם באו ממרחק גדול, לאחר שסיימו את תפקידם — \u0003הרי אלו\u0004 נחשבים \u0003כאנשי העיר\u0004 שהגיעו אליה, \u0003ויש להם\u0004 אפשרות ללכת \u0003אלפים\u0004 אמות \u0003לכל רוח.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 מה היא הגירסה המדוייקת: \u0003\"בית יעזק\" תנן\u0004 \u0005[שנינו]\u0006 \u0003או \"בית יזק\" תנן\u0004 \u0005[שנינו]?\u0006 ומסבירים את ההבדל בין הלשונות: האם \u0003\"בית יעזק\" תנן\u0004 \u0005[שנינו]\u0006 והרי זה \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 יפה\u0005]\u0006 \u0003הוא,\u0004 לומר שמקום טוב היה זה, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויעזקהו ויסקלהו\"\u0004 (ישעיה ה, ב) ועיזוק הוא איפוא לשון תיקון, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"בית יזק\" תנן\u0004 \u0005[שנינו]\u0006 והרי זה \u0003לישנא דצערא\u0004 \u0005[\u0006ש\u0005לשון צער]\u0006 \u0003הוא, כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"והוא אסור באזקים\"\u0004 (ירמיה מ, א)?","\u0003אמר אביי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003סעודות גדולות היו עושין להם שם\u0004 באותו מקום, \u0003כדי שיהו רגילים לבוא\u0004 ואם כן נראה שהוא לשון תיקון, לומר שהוא מקום נעים להיות בו. ודוחים: מכאן אין ראיה \u0003דלמא תרתי הוו עבדי בהו\u0004 \u0005[שמא שני\u0006 דברים \u0005היו עושים בהם],\u0006 שהיה צער מפני שאסרו להם לזוז ממקומם והיו רואים את הדבר כאילו הם אסורים שם (\"בית יזק\"), אף שדאגו שתהא גם הנאה בדבר.","\u0003כיצד בודקין את העדים\u0004 הבאים להעיד על החודש? \u0003זוג\u0004 עדים \u0003שבא ראשון בודקין אותו ראשון. ומכניסין את הגדול שבהן\u0004 שבזוג עדים זה, \u0003ואומרין לו: אמור כיצד ראית את הלבנה: לפני החמה, או לאחר החמה? לצפונה, או לדרומה? כמה היה\u0004 הירח \u0003גבוה\u0004 מעל האופק \u0003ולאין היה נוטה, וכמה היה רחב.\u0004 ולמשל, \u0003אם אמר\u0004 כי \u0003לפני החמה\u0004 ראה את הירח — \u0003לא אמר כלום\u0004 שדבר זה אינו אפשרי והרי זו הוכחה שטעה או ששיקר.","\u0003ואחר כך\u0004 לאחר שסיימו לשמוע את העדות כפי שהיתה, \u0003היו מכניסים את השני ובודקין אותו. אם נמצאו דבריהם מכוונים\u0004 — \u0003עדותן קיימת\u0004 ודי בה כדי לקדש את החודש. ומאחר שכבר קיימו את העדות הראשונה שוב אין צורך בעדות נוספת, ולכך \u0003שאר כל הזוגות שואלין אותן ראשי דברים\u0004 בלא לחקור אותם בפרטות. \u0003לא שהיו צריכים להם\u0004 לשאר הזוגות \u0003אלא כדי שלא יצאו בפחי נפש\u0004 (באכזבה, בעצבות) שטרחו כל כך ואפילו לא נתבקשו להעיד, וכל זאת עשו \u0003בשביל שיהו העדים רגילים לבוא\u0004 ולא יחשבו שאין זקוקים להם.","ושואלים: \u0003היינו\u0004 \u0005[זהו]\u0006 אותו דבר, הוא הביטוי \u0003לפני החמה היינו\u0004 \u0005[זהו]\u0006 \u0003לצפונה, היינו\u0004 \u0005[זהו]\u0006 \u0003לאחר החמה היינו\u0004 \u0005[זהו]\u0006 \u0003לדרומה! אמר אביי:\u0004 לא לענין מקום הלבנה שאלו אותם, אלא השאלה היתה האם \u0003פגימתה\u0004 של הלבנה, כלומר, הצד הקעור שבה, האם היה מכוון \u0003לפני החמה,\u0004 אל השמש, \u0003או\u0004 שמא היה מכוון \u0003לאחר החמה? אם אמר לפני החמה\u0004 — \u0003לא אמר כלום.\u0004","ש\u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"המשל ופחד עמו עשה שלום במרומיו\"\u0004 (איוב כה, ב), לומר כי \u0003מעולם לא ראתה\u0004 ה\u0003חמה\u0004 את \u0003פגימתה של\u0004 ה\u0003לבנה,\u0004 שכן צידה הקעור של הלבנה תמיד הוא בצד ההפוך לשמש ואף \u0003לא\u0004 רואה החמה את \u0003פגימתה של\u0004 ה\u0003קשת\u0004 אלא תמיד צידה הקמור של הקשת הוא הפונה לצד השמש. וטעם הדבר שאת \u0003פגימתה של\u0004 ה\u0003לבנה\u0004 אינה רואה — משום \u0003דחלשה\u0004 \u0005[שנחלשת]\u0006 \u0003דעתה,\u0004 מתביישת הלבנה אם החמה רואה אותה חסרה, ולכן רואה החמה תמיד את עיגולה המלא של הלבנה. ואינה רואה \u0003פגימתה של קשת\u0004 — משום ש\u0003לא לימרו\u0004 \u0005[יאמרו]\u0006 \u0003עובדי החמה\u0004"],["שקשת זו היא של החמה ו\u0003גירי קא משדייא\u0004 \u0005[חיצים היא שולחת]\u0006 שכן דרך ירייה בקשת להחזיקה כאשר הקימור מכוון כלפי חוץ, ולכן הקשת מכוונת בדיוק להיפך כדי שלא תיראה כקשתה של השמש.","שנינו במשנה שבחקירתם, היו שואלים את העדים שאלות אלה: \u0003כמה היה\u0004 הירח \u0003גבוה, ולאין היה נוטה. תנא חדא\u0004 \u0005[שנה\u0006 החכם בברייתא \u0005אחת]:\u0006 אם אמר כי ראה את הירח כשהוא \u0003לצפונה\u0004 של חמה — \u0003דבריו קיימין,\u0004 ואולם אם אמר שראהו כשהוא \u0003לדרומה\u0004 — \u0003לא אמר כלום,\u0004 שאין הדבר אפשרי. ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנינו\u0006 בברייתא \u0005להיפך]:\u0006 \u0003לדרומה\u0004 — \u0003דבריו קיימין, לצפונה\u0004 — \u0003לא אמר כלום.\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן,\u0004 בברייתא שמשמע מדבריה שמקום הירח בדרומה של השמש, מדובר \u0003בימות החמה,\u0004 שמהלך השמש ארוך יותר, שהיא זורחת בקרן צפונית מזרחית ומהלכת על כל פני המזרח הדרום והמערב, ולעת שקיעתה הריהי בקרן צפונית מערבית, כשהירח כנגדה בצד דרום, וכשמעיד שראה את הירח לדרומה של השמש — אמת העיד. ואילו \u0003כאן\u0004 במשנה, שמשמע מדבריה שמקום הירח לצפונה של השמש, הרי זה מדובר \u0003בימות הגשמים,\u0004 שמהלך השמש בזמן זה קצר ביותר, שהיא זורחת בקרן מזרחית דרומית ומהלכת על פני הדרום ולעת שקיעתה הריהי בקרן דרומית מערבית והירח כנגדה בצד צפון, וכשמעיד שראה את הירח בצד צפון — אמת העיד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 עד \u0003אחד אומר\u0004 הירח היה \u0003גבוה\u0004 למראית העין כמו \u0003שני מרדעות\u0004 (מוט שמכוונים בו את הבהמות) מעל האופק, \u0003ואחד אומר\u0004 היה גבוה כגובה \u0003שלשה\u0004 מרדעות — \u0003עדותן קיימת.\u0004 שאנו מניחים שבשיעור כזה יכולה להיות טעות קלה, ושניהם ראו דבר אחד. אבל אם \u0003אחד אומר שלשה, ואחד אומר חמשה\u0004 — \u0003עדותן בטילה\u0004 שוודאי אינם מעידים על אותו דבר. \u0003אבל מצטרפין לעדות אחרת\u0004 שאם יימצא עד נוסף המעיד אף הוא כדברי אחד מהם, שראה בשלושה או בחמישה — הרי העד מבני הזוג וגם השני יכולים להצטרף לעדות שלימה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם אמרו העדים \u0003ראינוהו במים,\u0004 שאת הירח עצמו לא ראו, אלא רק את השתקפותו במים, או \u0003ראינוהו בעששית\u0004 (דרך זכוכית), \u0003ראינוהו בעבים\u0004 (דרך העננים) — \u0003אין מעידין עליו\u0004 שאין מעידים אלא על ראיה בלתי אמצעית, של הירח עצמו. ראוהו \u0003חציו במים,\u0004 או שראו את \u0003חציו בעבים,\u0004 או \u0003חציו בעששית\u0004 — \u0003אין מעידין עליו.\u0004","ותוהים: \u0003השתא\u0004 \u0005[הרי]\u0006 כשראו הירח \u0003כולו אמרת\u0004 ש\u0003לא,\u0004 אם כן על \u0003חציו\u0004 של הירח \u0003מבעיא\u0004 \u0005[צריך\u0006 לומר\u0005],\u0006 שאם ראה רק את חציו באופן זה שאין זו עדות?! \u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 ראה את \u0003חציו במים\u0004 ואת \u0003חציו\u0004 ראה \u0003ברקיע, חציו בעבים\u0004 ואת \u0003חציו ברקיע, חציו בעששית\u0004 ואת \u0003חציו ברקיע,\u0004 אף על פי שראה את חציו ברקיע — \u0003אין מעידין\u0004 עליו עד שיראוהו כולו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמרו העדים \u0003ראינוהו\u0004 רגע אחד \u0003ושוב לא ראינוהו\u0004 — \u0003אין מעידים עליו.\u0004 ותוהים: \u0003כל הכי חזו לה ואזלי\u0004 \u0005[כל כך רואים אותו והולכים]?!\u0006 שודאי אין צריך לעמוד ולראותו כל הזמן!","ומסבירים, \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר],\u0006 אם העידו העדים ואמרו: \u0003ראינוהו מאלינו,\u0004 כלומר, העפנו מבט מבלי להתבונן במיוחד ובתוך כך ראינו את הירח, \u0003ושבנו לראותו\u0004 מאוחר יותר \u0003מדעתנו,\u0004 שנזכרנו במולד ורצינו לראותו בדיוק ובהבחנה \u0003ולא ראינוהו\u0004 — \u0003אין מעידין עליו,\u0004 שבודאי ראייתם הראשונה לא היתה אלא דמיון, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003אימור כוביתא דעיבא בעלמא הוא דחזי\u0004 \u0005[פיסת עיגול של ענן בלבד הוא שראו]\u0006 והיה נדמה להם כירח, ולכן כשהתבוננו אחר כך שוב לא ראו.","לאחר שנחקרה העדות והתקבלה, \u0003ראש בית\u0004 ה\u0003דין אומר: \"מקודש\" וכל העם עונין אחריו: \"מקודש מקודש\". בין שנראה\u0004 הירח \u0003בזמנו\u0004 ביום השלושים לחודש הקודם, \u0003בין שלא נראה בזמנו\u0004 ולא הוצרכו לעדיו — \u0003מקדשין אותו\u0004 את החודש, ומודיעים שמקודש חודש זה.","\u0003ר' אלעזר בר' צדוק אומר: אם לא נראה\u0004 מולד הירח \u0003בזמנו,\u0004 שוב \u0003אין מקדשין אותו\u0004 בבית דין, \u0003שכבר קידשוהו\u0004 ב\u0003שמים,\u0004 שהרי רואים הכל את הירח ואין צורך בקידוש מיוחד.","שנינו במשנה ש\u0003ראש בית\u0004 ה\u0003דין\u0004 אומר \"מקודש\" וכל העם עונה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין\u0006 נלמדים \u0005דברים אלה]?\u0006 \u0003אמר ר' חייא בר גמדא אמר ר' יוסי בן שאול אמר רבי: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וידבר משה את מועדי ה'\"\u0004 (ויקרא כג, מד) — \u0003מכאן שראש בית\u0004 ה\u0003דין אומר \"מקודש\".\u0004","שנינו במשנה כי לאחר שאמר ראש בית הדין \"מקודש\", היו \u0003כל העם עונין אחריו \"מקודש מקודש\". מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רב פפא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אשר תקראו אתם\u0004 מקראי קודש\" (ויקרא כג, ב), \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 באותו פסוק כאילו נאמר \"אשר תקראו \u0003אתם\". רב נחמן בר יצחק אמר:\u0004 לומדים זאת ממה שנאמר: \u0003\"אלה הם מועדי\"\u0004 (ויקרא כג, ב), כלומר: \u0003הם יאמרו מועדי.\u0004","ושואלים: \u0003\"מקודש מקודש\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003למה לי\u0004 שיאמרו, ומדוע לא יסתפקו בפעם אחת? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"מקראי קדש\"\u0004 (ויקרא כג, ב) בלשון רבים, משמע שתי קריאות, ולכן לכפול את הקריאה, ולומר \"מקודש מקודש\".","שנינו במשנה: \u0003ר' אלעזר בר' צדוק אומר אם לא נראה\u0004 מולד הירח \u0003בזמנו\u0004 — \u0003אין מקדשין אותו.\u0004 ומביאים דעות נוספות; \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 החכם \u0003פלימו אומר:\u0004 אם נראה \u0003בזמנו\u0004 — \u0003אין מקדשין אותו,\u0004 שכן זה הזמן הראוי לו ואין צורך בקידוש מיוחד, אולם אם נראה \u0003שלא בזמנו\u0004 — \u0003מקדשין אותו.\u0004","\u0003ר' אלעזר בר' שמעון אומר: בין כך ובין כך אין מקדשין אותו. שנאמר: \"וקדשתם את שנת החמשים\u0004 שנה\" (ויקרא כה, י), ללמד: \u0003שנים אתה מקדש, ואי אתה מקדש חדשים.\u0004 ובראשי חודשים מסתפקים בהודעה לציבור שנקבע ראש חודש זה, אבל אין צורך לומר \"מקודש\". \u0003אמר ר' יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' אלעזר בר' צדוק,\u0004 שבזמנו — מקדשים אותו, ושאינו בזמנו — אין מקדשים אותו.","\u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 דבר זה במשנה, האומרת: \u0003ראוהו בית דין וכל ישראל, נחקרו העדים ולא הספיקו לומר \"מקודש\" עד שחשיכה\u0004 — \u0003הרי זה מעובר\u0004 החודש הקודם, והוא בן שלושים יום, ומעתה נלמד: \u0003מעובר\u0004 החודש הקודם — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מקודש\u0004 החודש הבא — \u0003לא,\u0004 הרי שאין מקדשים אלא חודש חסר.","ודוחים: מכאן אין ראיה, כי לענין חודש \u0003מעובר איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 ללמד משנה זו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וראוהו\u0004 כבר \u0003בית דין וכל ישראל,\u0004 אם כן \u0003איפרסמא\u0004 \u0005[\u0006כבר \u0005התפרסם\u0006 הדבר\u0005]\u0006 שהגיע כבר החודש החדש \u0003ולא ליעברוה\u0004 \u0005[ואין\u0006 צורך \u0005לעברו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכל עוד לא קידשוהו — אינו מקודש.","\u0003דמות צורות לבנה היו לו לרבן גמליאל\u0004 מצויירות \u0003בטבלא\u0004 שהיתה מצויה \u0003בכותל\u0004 ש\u0003בעלייתו, שבהן מראה את ההדיוטות\u0004 שאינם יודעים להסביר את דבריהם במילים, \u0003ואומר\u0004 לעד: ראה דוגמאות הללו ואמור לי \u0003הכזה ראית או כזה?\u0004","שנינו במשנה שהיו לו לרבן גמליאל צורות לבנה. ותוהים: \u0003ומי שרי\u0004 \u0005[והאם מותר]\u0006 הדבר? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא תעשון אתי\u0004 אלוהי כסף ואלוהי זהב לא תעשו לכם\" (שמות כ, כ), ודרשו: \u0003לא תעשון כדמות שמשיי,\u0004 דברים העשויים לשמש את הקדוש ברוך הוא ובכללם שמש וירח.","\u0003אמר אביי: לא אסרה תורה אלא שמשין שאפשר\u0004 לו לאדם \u0003לעשות כמותן,\u0004 ושמש וירח כיון שאי אפשר לאדם לעשות מאורות כמותן ממילא אינו אסור. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא יעשה אדם בית\u0004 שהוא כ\u0003תבנית היכל\u0004 בכל מידותיו, או \u0003אכסדרה\u0004 (מבנה כעין מרפסת) בדיוק כמו \u0003תבנית אולם\u0004 שבמקדש, \u0003חצר\u0004 בבית \u0003כנגד עזרה, שלחן\u0004 בדיוק \u0003כנגד שלחן\u0004 שבמקדש, \u0003מנורה\u0004 בדיוק \u0003כנגד מנורה. אבל עושה\u0004"],["אדם מנורה \u0003של חמשה ושל ששה ושל שמונה\u0004 קנים, אבל \u0003של שבעה\u0004 קנים — \u0003לא יעשה, אפילו\u0004 היו \u0003משל שאר מיני מתכות\u0004 ולא של זהב, שכן בשעת הדחק עושים גם במקדש מנורה מחומרים אחרים. \u0003ר' יוסי בר' יהודה אומר: אף\u0004 מנורה \u0003של עץ לא יעשה, כדרך שעשו מלכי בית חשמונאי\u0004 כשטיהרו את הבית בראשונה ומפני דחקם הוזקקו לעשות מנורה מעץ, וכיון שהיא כשרה במקדש — אסור לעשות כיוצא בה בחוץ.","\u0003אמרו לו: משם\u0004 מביא אתה \u0003ראייה?!\u0004 הלא לא כך היה, שהרי \u0003שפודין של ברזל היו\u0004 להם \u0003וחיפום\u0004 (וציפו אותם) \u0003בבעץ\u0004 (בבדיל) ומהם עשו מנורה. לאחר מכן כש\u0003העשירו\u0004 ויכלו לעשות מנורה מחומר איכותי יותר, \u0003עשאום\u0004 מנורה \u0003של כסף, חזרו\u0004 ו\u0003העשירו\u0004 — \u0003עשאום של זהב.\u0004 ולענייננו הוכיח מכאן אביי שהדברים שאסור לעשות כמותם הם דווקא כדמות השמשים שאפשר לעשות כמותם, כגון כלי הקודש.","ושואלים: \u0003ושמשין שאי אפשר לעשות כמותן מי שרי\u0004 \u0005[האם מותר]\u0006 לעשות כדוגמתם? \u0003והתניא\u0004 \u0005[והלא שנינו\u0006 בברייתא\u0005]\u0006 במפורש: מה שנאמר \u0003\"לא תעשון אתי\"\u0004 (שמות כ, כ), בא ללמד: \u0003לא תעשון כדמות שמשיי המשמשין לפני במרום! אמר אביי:\u0004 אין הכוונה לשמש וירח ו\u0003לא אסרה תורה אלא\u0004 לעשות \u0003דמות ארבעה פנים\u0004 של חיות שבמרכבה \u0003בהדי הדדי\u0004 \u0005[יחד],\u0006 אבל כל צורה אחרת מותר, לפי שאינה כדמות המלאכים המשמשים במרום.","ומקשים: \u0003אלא מעתה פרצוף אדם לחודיה תשתרי\u0004 \u0005[לבדו יהא מותר]\u0006 בעשייה? \u0003אלמה תניא\u0004 \u0005[מדוע\u0006 איפוא \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל הפרצופות מותרין\u0004 לעשות אותן לשם נוי \u0003חוץ מפרצוף אדם! אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מפרקיה\u0004 \u0005[מדרשתו]\u0006 של \u0003אביי שמיעא לי\u0004 \u0005[שמעתי]\u0006 דבר זה: שאסור לעשות כדוגמת פרצוף אדם, מפני טעם אחר, ששנינו ללמוד ממה שנאמר: \u0003\"לא תעשון אתי\"\u0004 (שמות כ, כ) — \u0003לא תעשון אותי,\u0004 שכיון שנברא האדם בצלם אלוקים, אסור לעשות דמות כמראה אדם.","ושואלים: \u0003ושאר שמשין מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מה שנאמר \u0003\"לא תעשון אתי\"\u0004 בא ללמד: \u0003לא תעשון כדמות שמשיי המשמשין לפני במרום, כגון אופנים ושרפים וחיות הקודש ומלאכי השרת! אמר אביי: לא אסרה תורה אלא שמשין שבמדור העליון,\u0004 כלומר, אלה שהם מלאכי עליון, ברקיע עליון. אבל לא גרמי השמיים אף כי משכנם במרום.","ומקשים עוד: \u0003ושבמדור התחתון מי שרי\u0004 \u0005[האם מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \"לא תעשה לך פסל וכל תמונה אשר בשמים ממעל ואשר בארץ מתחת ואשר במים מתחת לארץ\" (שמות כ, ד), ומפרשים: \u0003\"אשר בשמים\"\u0004 — \u0003לרבות חמה ולבנה כוכבים ומזלות, \"ממעל\"\u0004 — \u0003לרבות מלאכי השרת.\u0004 הרי שאסור לעשות אף כדוגמת גרמי השמים שבמדור התחתון! ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 בענין מה שבשמים ממעל — הכוונה היא לאסור \u0003לעבדם,\u0004 אבל לא נאסר לעשות כתבניתם.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 לענין \u0003לעבדם,\u0004 אם כן \u0003אפילו שלשול קטן נמי\u0004 \u0005[גם כן]\u0006 אסור לעבדו! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על המשך הכתוב \u0003\"\u0004ו\u0003אשר בארץ\"\u0004 — \u0003לרבות הרים וגבעות ימים ונהרות אפיקים וגאיות, \"מתחת\"\u0004 — \u0003לרבות שלשול קטן.\u0004 ואם כן כל מדרש־הלכה זה כולו נאמר לענין איסור עבודה זרה שאסור לעבוד לכל דבר.","ושוב מקשים: \u0003ועשייה גרידתא\u0004 \u0005[לבדה]\u0006 של גרמי השמים \u0003מי שרי\u0004 \u0005[האם\u0006 היא \u0005מותרת]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: מה שנאמר \u0003\"לא תעשון אתי\"\u0004 בא ללמד: \u0003לא תעשון כדמות שמשיי המשמשין לפני, כגון חמה ולבנה כוכבים ומזלות.\u0004 והרי זו הוכחה ברורה שאף תבניות שמש וירח אסורות בעשייה! ונדחו איפוא דברי אביי.","ויש להסביר באופן אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רבן גמליאל דאחרים\u0004 (גויים) \u0003עשו לו\u0004 תבניות אלה, ולא נאסר לישראל אלא רק לעשות כדוגמתם, אולם לא נאסר עליו להחזיק בהם. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יהודה\u0004 ש\u0003אחרים עשו לו\u0004 חותמת בדמות אדם, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה\u0004 תלמידו: \u0003שיננא\u0004 \u0005[\u0006גדול \u0005השיניים],\u0006 \u0003סמי עיניה דדין\u0004 \u0005[עור\u0006 את \u0005עיניו\u0006 של \u0005זה]\u0006 כלומר, השחת את הצורה הזו. הרי שאסור אף להחזיק צורת אדם!","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 במעשה של ר' יהודה, \u0003חותמו בולט הוה\u0004 \u0005[היה],\u0006 שהיתה זו צורת אדם בולטת \u0003ומשום חשדא\u0004 \u0005[חשד]\u0006 הוא, שלא יאמרו עבודה זרה היא בידו. ו\u0003כדתניא\u0004 \u0005[כפי ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003טבעת\u0004 שיש בה צורה, אם \u0003חותמו בולט\u0004 — \u0003אסור להניחה\u0004 על אצבעו משום חשד, \u0003ומותר לחתום בה,\u0004 משום שיוצרת צורה שוקעת, ובזו לא נאמר איסור. אולם אם היה \u0003חותמו שוקע\u0004 — \u0003מותר להניחה,\u0004 אולם \u0003אסור לחתום בה,\u0004 משום שהוא יוצר על ידי כך צורה בולטת.","ושואלים מצד אחר: \u0003ומי חיישינן לחשדא\u0004 \u0005[האם חוששים אנו לחשד]\u0006 בכגון זה? \u0003והא ההיא בי כנישתא דשף ויתיב\u0004 \u0005[והרי אותו בית כנסת שנפל והוקם]\u0006 \u0003בנהרדעא, דהוה ביה\u0004 \u0005[שהיתה בו]\u0006 \u0003אנדרטא,\u0004 פסל אדם בדמות המלך, \u0003והוו עיילי\u0004 \u0005[והיו נכנסים]\u0006 \u0003רב ושמואל ואבוה\u0004 \u0005[ואביו]\u0006 של \u0003שמואל ולוי ומצלו התם\u0004 \u0005[ומתפללים שם]\u0006 \u0003ולא חיישי לחשדא\u0004 \u0005[חששו לחשד]!\u0006 ומשיבים: כשנמצאים שם יהודים \u0003רבים\u0004 באותו המקום, \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר, שאין חושדים ברבים שכוונתם לעבודה זרה, ויודעים שהוא לנוי בלבד.","ושואלים עוד: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבן גמליאל יחיד הוא\u0004 ויש מקום איפוא לחשוד בו, ואם כן כיצד עשה את צורות הלבנה? ומשיבים: \u0003כיון\u0004 ש\u0003נשיא הוא\u0004 — \u0003שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רבים גביה\u0004 \u0005[אצלו],\u0006 והריהו נחשב כרבים. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 צורות אלו לא היו שלימות אלא של \u0003פרקים הוה\u0004 \u0005[חלקים היתה]\u0006 ודבר העשוי חלקים חלקים אינו נחשב כצורה אסורה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 כי כדי \u0003להתלמד\u0004 וללמד \u0003עבד\u0004 \u0005[עשה]\u0006 ובענין זה אין איסור כלל, \u0003וכתיב\u0004 \u0005[ו\u0006הרי \u0005נאמר]:\u0006 \u0003\"לא תלמד לעשות\u0004 כתועבת הגויים ההם\" (דברים יח, ט). \u0003אבל אתה למד להבין ולהורות,\u0004 הרי שלצורך לימוד והוראה מותר לעשות דברים שונים שאסור לעשותם לצורך עצמם.","\u0003מעשה שבאו שנים\u0004 להעיד על החודש, \u0003ואמרו: ראינוהו\u0004 את הירח הישן \u0003שחרית ב\u0004צד \u0003מזרח,\u0004"],["\u0003וערבית\u0004 ראינו את הירח החדש \u0003ב\u0004צד \u0003מערב. אמר ר' יוחנן בן נורי: עדי שקר הם,\u0004 שלא יתכן שראו המולד זמן קצר כל כך לאחר סוף החודש הקודם, ואין לסמוך עליהם. ו\u0003כשבאו ליבנה קיבלן רבן גמליאל\u0004 כעדים, ולא חשש.","\u0003ועוד\u0004 מעשה, ש\u0003באו שנים ואמרו: ראינוהו בזמנו,\u0004 כלומר, בליל שלושים של החודש הקודם, \u0003ובליל עיבורו,\u0004 כלומר, בלילה שלאחר מכן — \u0003לא נראה, וקיבלן רבן גמליאל\u0004 וסמך עליהם לקדש את החודש בזמנו.","\u0003אמר ר' דוסא בן הורכינס: עדי שקר הן\u0004 עדים אלה, ומשל לדבר \u0003היאך\u0004 יכול להיות שיהיו עדים \u0003מעידים על האשה שילדה ולמחר\u0004 היא נראית כש\u0003כריסה בין שיניה,\u0004 שהיא בהריון? שהרי אם נראה כבר הירח החדש בזמנו, כיצד לא נראה יום לאחר מכן? \u0003אמר לו ר' יהושע: רואה אני את דבריך,\u0004 שעדי שקר הם, ויש לקבוע את ראש החודש יום אחד מאוחר יותר. כיון שנודעו דברי ר' יהושע אלה, \u0003שלח לו רבן גמליאל: גוזרני\u0004 (גוזר אני) \u0003עליך שתבא אצלי במקלך ובמעותיך ביום הכפורים שחל להיות\u0004 לפי \u0003חשבונך,\u0004 שהוא לפי חשבוננו אחד עשר בתשרי.","\u0003הלך ומצאו ר' עקיבא\u0004 לר' יהושע כשהוא \u0003מיצר\u0004 (מצטער) על שמאלצו הנשיא לחלל את יום הכיפורים לפי חשבונו, \u0003אמר לו\u0004 ר' עקיבא לר' יהושע: \u0003יש לי ללמוד שכל מה שעשה רבן גמליאל\u0004 בקידוש החודש הריהו \u0003עשוי, שנאמר: \"אלה מועדי ה' מקראי קדש אשר תקראו אתם\u0004 במועדם \u0003\"(ויקרא כג, ד), כלומר: קביעת המועדים תלויה בקריאה, בקידוש, על ידי ישראל בין בזמנן בין שלא בזמנן\u0004 — \u0003אין לי מועדות אלא אלו\u0004 שקבעו ישראל.","\u0003בא לו\u0004 ר' יהושע \u0003אצל ר' דוסא בן הורכינס, אמר לו\u0004 ר' דוסא: \u0003אם באין אנו לדון אחר בית דינו של רבן גמליאל\u0004 ולפקפק בהחלטותיו, הרי \u0003צריכין אנו לדון אחרי כל בית דין ובית דין שעמד מימות משה\u0004 רבינו \u0003ועד עכשיו,\u0004 שמא טעה בהחלטותיו. \u0003שנאמר: \"ויעל משה ואהרן נדב ואביהוא ושבעים מזקני ישראל\"\u0004 (שמות כד, ט) \u0003ולמה לא נתפרשו שמותן של זקנים\u0004 אלה שזכו עד כדי כך? \u0003אלא ללמד\u0004 מפסוק זה \u0003שכל שלשה ושלשה שעמדו בית דין על ישראל\u0004 — \u0003הרי הוא כבית דינו של משה,\u0004 שהרי אין אנו יודעים מי היה באותו בית דין, ודי לנו בכך שהיו דייני ישראל.","כיון ששמע ר' יהושע שאף ר' דוסא בן הורכינס סבור שיש לסמוך על דברי רבן גמליאל, \u0003נטל מקלו ומעותיו בידו, והלך ליבנה אצל רבן גמליאל ביום שחל יום הכפורים להיות\u0004 על פי \u0003חשבונו.\u0004 כשראהו \u0003עמד רבן גמליאל ונשקו על ראשו, אמר לו: בוא בשלום רבי ותלמידי! רבי\u0004 — \u0003בחכמה\u0004 שר' יהושע גדול היה בחכמה מבני דורו, \u0003ותלמידי\u0004 — \u0003שקבלת את דברי\u0004 אף על פי שלא היו אלה נראים בעיניך.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר להם רבן גמליאל לחכמים\u0004 להסביר את דבריו, שיתכן שהיה זמן קצר כל כך בין סוף החודש הקודם והמולד הבא. \u0003כך מקובלני מבית אבי אבא: פעמים שבא\u0004 הירח בדרך \u0003ארוכה ופעמים שבא בקצרה\u0004 וממהר לבוא.","\u0003אמר ר' יוחנן: מאי טעמיה דבי\u0004 \u0005[מה טעמם של בית]\u0006 \u0003רבי,\u0004 כלומר, של הנשיאים (בית אביו של רבן גמליאל) — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עשה ירח למועדים שמש ידע מבואו\"\u0004 (תהלים קד, יט) ומן הפסוק נלמד: \u0003שמש הוא\u0004 ש\u0003ידע מבואו,\u0004 לפי שמועדי זריחתה ותקופותיה — קבועים הם, ואילו \u0003ירח לא ידע מבואו,\u0004 ואין מהלכו שוה בכל חודש.","מסופר: \u0003ר' חייא חזייא לסיהרא דהוה קאי בצפרא\u0004 \u0005[ראה\u0006 את \u0005הירח שהיה עומד\u0006 בשמים \u0005בבוקר]\u0006 של \u0003עשרים ותשעה, שקל קלא פתק ביה\u0004 \u0005[לקח רגב\u0006 אדמה \u0005זרק בו],\u0006 \u0003אמר\u0004 לו: \u0003לאורתא בעינן לקדושי בך\u0004 \u0005[לערב אנו צריכים לקדש אותך]\u0006 שייראה מולד הירח ונוכל לקדש את החודש ביום שלושים, \u0003ואת קיימת הכא\u0004 \u0005[ואתה עומד כאן]?!\u0006 \u0003זיל איכסי\u0004 \u0005[לך\u0006 ו\u0005התכסה],\u0006 שאפשר יהיה לראות את המולד החודש בלילה. מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לר' חייא: זיל ל\u0004מקום \u0003עין טב וקדשיה לירחא\u0004 \u0005[וקדש\u0006 את \u0005הירח],\u0006 \u0003ושלח לי סימנא\u0004 \u0005[ושלח לי סימן]\u0006 שאדע שקידשת אותו, וסימן זה יהא המשפט \u0003\"דוד מלך ישראל חי וקים\".\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת נתקשרו שמים בעבים ונראית\u0004 כעין \u0003דמות לבנה בעשרים ותשעה לחדש, כסבורים העם לומר\u0004 לאור זה כי \u0003ראש החדש\u0004 הוא, \u0003ובקשו בית\u0004 ה\u0003דין לקדשו. אמר להם רבן גמליאל: כך מקובלני מבית אבי אבא: אין חדושה של לבנה פחותה מעשרים ותשעה יום ומחצה ושני שלישי שעה ושבעים ושלשה חלקים\u0004 (של אחד מאלף ושמונים בשעה).","\u0003ואותו היום מתה אמו של החכם בן זזא, והספידה רבן גמליאל הספד גדול\u0004 בו ביום. \u0003לא מפני שראויה לכך\u0004 להספד גדול זה, \u0003אלא כדי שידעו העם שלא קידשו בית דין את החדש,\u0004 שכן בראש חודש אין מספידים, והספד זה מוכיח שיום זה הוא יום חול לכל דבריו.","שנינו במשנה: \u0003הלך ומצאו ר' עקיבא מיצר (מצטער). איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מי\u0004 היה \u0003מיצר? ר' עקיבא\u0004 היה \u0003מיצר, או ר' יהושע מיצר?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003: הלך ר' עקיבא ומצאו לר' יהושע כשהוא מיצר. אמר לו\u0004 ר' עקיבא לר' יהושע: \u0003רבי, מפני מה אתה מיצר? אמר לו: עקיבא, ראוי לו\u0004 (כלומר, מוטב לו) \u0003שיפול למטה\u0004 חולה \u0003שנים עשר חדש, ואל יגזור עליו גזירה זו,\u0004 שיצטרך לחלל את יום הכיפורים.","\u0003אמר לו: רבי, תרשיני לומר לפניך דבר אחד שלמדתני. אמר לו: אמור. אמר לו: הרי הוא אומר\u0004 בענין קביעת החגים והמועדים \u0003\"אתם\"\u0004 (\"מועדי ה' אשר תקראו אותם מקראי קודש\". ויקרא כג, ב), \u0003\"אתם\"\u0004 (\"אלה מועדי ה' אשר תקראו אותם במועדם\". ויקרא כג, ד), \u0003\"אתם\"\u0004 (\"אלה מועדי ה' אשר תקראו אותם מקראי קודש\". ויקרא כג, לז), \u0003שלש פעמים\u0004 והרי זה כאילו נאמר לשון \"אתם\" ללמד:","\u0003אתם\u0004 — \u0003אפילו שוגגין,\u0004 שבשגגה נקבע החודש שלא בזמנו הראוי, \u0003\"אתם\"\u0004 — \u0003אפילו\u0004 הייתם \u0003מזידין\u0004 כשקבעתם את החודש שלא בזמנו, \u0003\"אתם\"\u0004 — \u0003אפילו\u0004 הייתם \u0003מוטעין\u0004 על ידי עדי שקר. ובכל זאת כיון שקבעתם את החודש — הרי הוא מקודש, ומסכים הקדוש ברוך הוא עם קביעתכם. ומוסיפים, \u0003בלשון הזה אמר לו: \"עקיבא, 'נחמתני', 'נחמתני'\".\u0004","שנינו במשנה: \u0003בא לו\u0004 ר' יהושע \u0003אצל ר' דוסא בן הורכינס,\u0004 והוכיח ר' דוסא שיש לסמוך על רבן גמליאל כשם שסמכו על משה ובית דינו. ונלמד הדבר ממה שלא הוזכרו שמותם של אותם זקנים שהיו עם משה, אף שבודאי גדולים וחשובים היו, לומר שכל שלושה ושלושה שעמדו ונעשו בית דין לדון את ישראל הרי הם כבית דינו של משה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003למה לא נתפרשו שמותם של זקנים הללו\u0004 שהיו עם משה? \u0003שלא יאמר אדם:\u0004 דיין \u0003פלוני\u0004 שבדורי הוא \u0003כמשה ואהרן?\u0004 האם \u0003פלוני\u0004 הוא \u0003כנדב ואביהוא?\u0004 האם \u0003פלוני\u0004 הוא \u0003כאלדד ומידד?\u0004 ולכן לא נתפרשו שמותיהם של שאר הזקנים, שאין לדעת אם זקנים שבדורו של משה היו טובים מאלה.","כיוצא בו \u0003אומר: \"ויאמר שמואל אל העם ה' אשר עשה את משה ואת אהרן\"\u0004 (שמואל א' יב, ו). \u0003ואומר\u0004 עוד: \u0003\"וישלח ה' את ירבעל ואת בדן ואת יפתח ואת שמואל\"\u0004 (שמואל א' יב, יא). ומסבירים: \u0003\"ירובעל\"\u0004 — \u0003זה גדעון, ולמה נקרא שמו \"ירובעל\"\u0004 — \u0003שעשה מריבה עם הבעל. \"בדן\"\u0004 — \u0003זה שמשון, ולמה נקרא שמו \"בדן\"\u0004 — \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003מ\u0004שבט \u0003דן\u0004 ו\"בדן\" הוא קיצור של בן דן. \u0003יפתח\u0004 — \u0003כמשמעו.\u0004"],["\u0003ואומר\u0004 בכתוב אחר: \u0003\"משה ואהרן בכהניו ושמואל בקראי שמו\u0004 קוראים אל ה' והוא יענם\" (תהלים צט, ו), שמשווה את שמואל למשה ואהרן, נמצא שכאן \u0003שקל הכתוב שלשה קלי עולם\u0004 שמשון גדעון ויפתח \u0003כשלשה חמורי עולם,\u0004 שהיו מגדולי ישראל בכל הדורות,","\u0003לומר לך: ירובעל בדורו\u0004 חשוב וצריך לציית לו \u0003כמשה בדורו, בדן בדורו\u0004 — \u0003כאהרן בדורו, יפתח בדורו\u0004 — \u0003כשמואל בדורו. ללמדך: שאפילו קל שבקלים ונתמנה פרנס על הצבור\u0004 — \u0003הרי הוא כאביר\u0004 (גדול וחשוב) \u0003שבאבירים,\u0004 וחובה לשמוע בקולו ולציית לפסיקותיו. \u0003ואומר: \"ובאת אל הכהנים הלוים ואל השפט אשר יהיה בימים ההם\"\u0004 (דברים יז, ט), \u0003וכי תעלה על דעתך שאדם הולך אצל הדיין שלא היה בימיו?\u0004 ואם כן מה משמעות המילים \"בימים ההם\" — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין לך לילך אלא אצל שופט שבימיו,\u0004 כלומר כל שופט שבימים ההם הוא המוסמך לדון ולקבוע. \u0003ואומר: \"אל תאמר מה היה שהימים הראשנים היו טובים מאלה\u0004 כי לא מחכמה שאלת על זה \u0003\"(קהלת ז, י), ויש לקבל את הוראת מנהיגי אותו הדור.\u0004","","מסופר במשנה בהמשך הדברים: \u0003נטל\u0004 ר' יהושע \u0003מקלו ומעותיו בידו\u0004 ובא לבית רבן גמליאל ביום שיצא לפי חשבונו יום הכיפורים, כפי שהורה לו רבן גמליאל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא בהרחבה: \u0003כיון שראה אותו\u0004 רבן גמליאל, \u0003עמד מכסאו ונשקו על ראשו,\u0004 ו\u0003אמר לו: שלום עליך רבי ותלמידי! רבי\u0004 — \u0003שלמדתני תורה ברבים, ותלמידי\u0004 — \u0003שאני גוזר עליך גזירה ואתה מקיימה כתלמיד\u0004 שלי. \u0003אשרי הדור שהגדולים נשמעים לקטנים, קל וחומר\u0004 שישמעו \u0003קטנים לגדולים.\u0004 על לשון זו תוהים: \u0003קל וחומר?!\u0004 מה מקום לקל וחומר? הלא \u0003חיובא הוא\u0004 \u0005[חובה היא]\u0006 שישמעו הקטנים לגדולים מהם! \u0003אלא\u0004 כך יש להבין: \u0003מתוך שהגדולים נשמעים לקטנים\u0004 — \u0003נושאין קטנים קל וחומר בעצמן\u0004 ובוודאי הם נשמעים לאלה שראוי להישמע להם.","","","\u0003ראוהו\u0004 את הירח \u0003בית דין וכל ישראל, נחקרו העדים ולא הספיקו\u0004 בית דין \u0003לומר \"מקודש\" עד שחשיכה\u0004 ואם כן עבר יום השלושים — \u0003הרי זה מעובר,\u0004 שלא יחול ראש החודש ביום השלושים שנראה בו המולד אלא ביום שלאחריו, כיון שלא הספיקו בית דין לקדשו. \u0003ראוהו בית דין בלבד\u0004 — \u0003יעמדו שנים\u0004 מחברי בית הדין \u0003ויעידו בפניהם, ויאמרו\u0004 בית הדין: \u0003\"מקודש מקודש\". ראוהו שלשה\u0004 מחברי בית הדין \u0003והן בית דין\u0004 בעצמן — \u0003יעמדו השנים\u0004 מחברי בית הדין \u0003ויושיבו מחבריהם אצל היחיד\u0004 כדי שיהיה שם בית דין של שלושה, \u0003ויעידו\u0004 השנים \u0003בפניהם, ויאמרו: \"מקודש מקודש\", שאין היחיד נאמן על ידי עצמו\u0004 לא להעיד ולא להיות דיין, ויש צורך בבית דין של שלושה.","","שואלים: \u0003למה לי למיתנא\u0004 \u0005[מדוע צריך הוא לשנות]\u0006 \u0003ראוהו בית דין וכל ישראל?\u0004 דיו לומר ראוהו בית דין, שהרי בהם הדבר תלוי! ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וראוהו בית דין וכל ישראל\u0004 — \u0003איפרסמא לה [התפרסם\u0004 הדבר\u0005]\u0006 כבר שחל ראש החודש באותו יום \u0003ו\u0004שוב \u0003לא ליעברוה\u0004 \u0005[יעברוהו],\u0006 שהרי הכל יודעים שהיה במולד אתמול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף על פי כן אין קובעים ראש חודש אלא אם כן קידשוהו בית הדין במפורש.","ועוד שואלים: \u0003וכיון דתנא ליה\u0004 \u0005[ששנה\u0006 כבר\u0005]\u0006 \u0003ראוהו בית דין וכל ישראל\u0004 — \u0003נחקרו העדים למה לי,\u0004 שהרי כבר ראוהו בית דין! ומשיבים \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אם היה זה במקרה ש\u0003נחקרו העדים ולא הספיקו\u0004 בית הדין \u0003לומר \"מקודש\" עד שחשיכה\u0004 — \u0003הרי זה מעובר.\u0004 ושואלים עוד: \u0003וכיון דתנא ליה\u0004 \u0005[ששנה]\u0006 \u0003\"עד שחשיכה הרי זה מעובר\"\u0004 — \u0003למה לי למיתנייה\u0004 \u0005[לשנות]\u0006 \u0003חקירת העדים כלל?\u0004 שהרי כבר נאמר דין זה אפילו כשראוהו בית דין עצמם!","","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003תיהוי\u0004 \u0005[שתהיה]\u0006 \u0003חקירת\u0004 ה\u0003עדים כתחילת דין, ו\u0004אמירת \u0003\"מקודש מקודש\"\u0004 תהיה \u0003כגמר דין ולקדשי בליליא\u0004 \u0005[ושיקדשו\u0006 את החודש \u0005בלילה],\u0006 כיון שכבר התחיל הדין מבעוד יום, \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 ב\u0003דיני ממונות דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003דיני ממונות,\u0004 אף שצריכים להידון ביום, מכל מקום \u0003דנין את עיקר הדין ביום וגומרין\u0004 את הפסק \u0003בלילה\u0004 — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מקדשין בליליא\u0004 \u0005[בלילה]\u0006 אם כבר החלו בגוף הדיון ביום, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור שכך\u0006 הוא \u0005גם כן]\u0006 שדין קידוש החודש כדין דיני ממונות? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי ראש השנה: \u0003\"כי חק לישראל הוא משפט לאלהי יעקב\"\u0004 (תהלים פא, ה), \u0003אימת הוי\u0004 \u0005[מתי הרי הוא נעשה]\u0006 \u0003\"חק\"\u0004 — \u0003בגמר דין, וקא קרי ליה רחמנא\u0004 \u0005[וקוראת\u0006 לו \u0005התורה]\u0006 \u0003\"משפט\",\u0004 לומר: \u0003מה משפט\u0004 עיקר זמנו \u0003ביום\u0004 — \u0003אף הכא\u0004 \u0005[כאן],\u0006 בחוק קביעת הזמנים, הריהו נעשה \u0003נמי\u0004 \u0005[גם כן]\u0006 רק \u0003ביום.\u0004","שנינו במשנה: \u0003ראוהו בית דין\u0004 — \u0003יעמדו שנים ויעידו בפניהם.\u0004 ותוהים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אם ראוהו בית דין עצמם שיבואו ויעידו בפניהם? \u0003לא תהא שמיעה גדולה מראייה!\u0004 שאם חברי בית הדין עצמם ראוהו — לשם מה צריכים הם לשמוע עדות מפי אחר המעיד שראה? ומשיבים, \u0003אמר ר' זירא: כגון שראוהו בלילה\u0004 וכיון שבלילה אין בית הדין יכול לקבוע ולקדש את החודש, לפי שאין דנים בלילה, נמצא שה\"משפט\" שבדבר נעשה רק למחרת, ואז אין בית הדין יכול עוד לקבוע על סמך ראיה שהיא לעיניהם לפניהם ממש, ולכן יש צורך להעיד מחדש.","","אמרנו שאם \u0003ראוהו שלשה והן בית דין\u0004 — \u0003יעמדו שנים\u0004 מהם \u0003ויושיבו מחבריהם אצל היחיד,\u0004 והם יעידו. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הכא נמי נימא\u0004 \u0005[כאן גם כן נאמר]:\u0006 \u0003לא תהא שמיעה גדולה מראייה! וכי תימא: הכא נמי\u0004 \u0005[ואם תאמר: כאן גם כן]\u0006 עוסקים אנו במקרה מסויים, \u0003כגון שראוהו בלילה\u0004 — אולם \u0003היינו הך\u0004 \u0005[זה אותו דבר]\u0006 ואין צורך לשנות שני מקרים לחוד!","ומשיבים: \u0003סיפא איצטריכא ליה\u0004 \u0005[סופו\u0006 של אותו קטע \u0005הוצרך לו],\u0006 לחדש הלכה \u0003שאין היחיד נאמן על ידי עצמו. דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003הואיל ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003דיני ממונות בשלשה, ו\u0004אולם \u0003אם היה מומחה לרבים\u0004 — \u0003דן אפילו ביחיד,\u0004 אם כן נדמה את הדינים האחד לשני, \u0003הכא נמי ניקדשיה\u0004 \u0005[כאן גם כן ש\u0006דיין אחד \u0005יקדשו]\u0006 לחודש \u0003ביחידי\u0004 אם הוא דיין המומחה לרבים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלקידוש החודש צריך שלושה דווקא.","ושואלים: \u0003ואימא הכא נמי\u0004 \u0005[ואמור כאן גם כן]\u0006 שיהא די בדיין אחד מומחה? ודוחים: הרי בודאי \u0003אין לך מומחה לרבים בישראל יותר ממשה רבינו\u0004 ובכל זאת \u0003קאמר ליה\u0004 \u0005[אמר לו]\u0006 \u0003הקדוש ברוך הוא: עד דאיכא\u0004 \u0005[שיש,\u0006 שיהיה\u0005]\u0006 \u0003אהרן בהדך\u0004 \u0005[אתך]\u0006 לא תקדש, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויאמר ה' אל משה ואל אהרן בארץ מצרים לאמר. החדש הזה לכם ראש חודשים \"(שמות יב, א-ב) וכיון שאין עושים בית־דין שקול (שמספר חבריו זוגי) כדי שיהא מי שיוכל להכריע, נמצא שמן התורה צריך בית דין של שלושה.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 מתוך הדברים ששנינו כאן ש\u0003עד נעשה דיין,\u0004 שאדם שראה מאורע יכול הוא בעצמו להיות דיין באותו נושא? \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 כי \u0005משנתנו]\u0006 היא ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא; דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סנהדרין שראו\u0004 בעצמם אדם \u0003אחד שהרג את הנפש\u0004 —"]]};
